```', 60, 120, 'TCNH-02', true, null, '[{"id":"C1","label":"Độ chính xác và chiều sâu trong phân tích tài chính","weight":35,"maxScore":35},{"id":"C2","label":"Lý do, lập luận rõ ràng, bám sát tiêu chí đề bài","weight":25,"maxScore":25},{"id":"C3","label":"Khả năng xử lý sâu vấn đề phát sinh trong tình huống","weight":25,"maxScore":25},{"id":"C4","label":"Trình bày mạch lạc, đúng thời gian","weight":15,"maxScore":15}]'::jsonb, '[{"id":"C1","label":"Độ chính xác và chiều sâu trong phân tích tài chính","description":"{\"checklist\":[{\"text\":\"Tính toán chính xác và đầy đủ các tỷ số tài chính yêu cầu cho cả 3 năm\",\"points\":15,\"checklist_id\":\"TCNH-02-C1-1\",\"scoring_source\":\"ai\"},{\"text\":\"Phân tích được xu hướng của từng chỉ số và ý nghĩa đối với sức khỏe tài chính doanh nghiệp\",\"points\":10,\"checklist_id\":\"TCNH-02-C1-2\",\"scoring_source\":\"ai\"},{\"text\":\"Đánh giá được sức khỏe dòng tiền của doanh nghiệp\",\"points\":5,\"checklist_id\":\"TCNH-02-C1-3\",\"scoring_source\":\"ai\"},{\"text\":\"Xác định đúng các rủi ro tín dụng trọng yếu nhất\",\"points\":5,\"checklist_id\":\"TCNH-02-C1-4\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":35,"maxScore":35},{"id":"C2","label":"Lý do, lập luận rõ ràng, bám sát tiêu chí đề bài","description":"{\"checklist\":[{\"text\":\"Mỗi luận điểm trong bài đều có dẫn chứng từ số liệu và thông tin được cung cấp\",\"points\":15,\"checklist_id\":\"TCNH-02-C2-1\",\"scoring_source\":\"ai\"},{\"text\":\"Nhận diện được các rủi ro trọng yếu nhất trong tổng thể hồ sơ\",\"points\":10,\"checklist_id\":\"TCNH-02-C2-2\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":25,"maxScore":25},{"id":"C3","label":"Khả năng xử lý sâu vấn đề phát sinh trong tình huống","description":"{\"checklist\":[{\"text\":\"Quyết định cấp vốn (Đồng ý/Từ chối) rõ ràng và nhất quán với toàn bộ phần phân tích phía trước\",\"points\":15,\"checklist_id\":\"TCNH-02-C3-1\",\"scoring_source\":\"ai\"},{\"