t_id":"TCNH-02-C4-3","scoring_source":"system"}]}],"input_artifacts":[{"artifact_id":"TCNH-02-DATA-01","type":"table_or_excel","description":"Bộ hồ sơ tài chính 3 năm gần nhất: Báo cáo tài chính, Dòng tiền/Báo cáo lưu chuyển tiền tệ, Lịch sử tín dụng, Thông tin tài sản đảm bảo, Phương án sử dụng vốn.","required":true,"mapping_note":"File thực tế của đề thi sẽ được hệ thống map vào task này theo position_id; không tự tạo dữ liệu mẫu."}],"hard_constraints":[],"artifacts":{"TCNH-02-DATA-01":{"artifact_id":"TCNH-02-DATA-01","position_id":"TCNH-02","company":"Công ty Cổ phần Con Sứa (SME)","period":"3 năm gần nhất (N-2, N-1, N)","unit":"Tỷ VNĐ","loan_request":{"amount":5,"purpose":"Mở rộng hoạt động sản xuất kinh doanh","collateral":"Bất động sản nhà xưởng định giá 6.5 tỷ VNĐ, máy móc thiết bị cũ"},"financial_summary":[{"year":"N-2","revenue":32,"net_profit":2.8,"debt_to_equity":1.4,"interest_coverage_ratio":4.5,"roa_percent":8.7,"roe_percent":18.2,"cfo":2.5},{"year":"N-1","revenue":38,"net_profit":2.2,"debt_to_equity":2.1,"interest_coverage_ratio":2.8,"roa_percent":5.8,"roe_percent":13.5,"cfo":1.2},{"year":"N (Năm gần nhất)","revenue":41,"net_profit":1.3,"debt_to_equity":2.8,"interest_coverage_ratio":1.6,"roa_percent":3.1,"roe_percent":7.9,"cfo":-0.8}],"credit_history":"Không có nợ xấu nhóm 3-5 tại CIC trong 24 tháng gần nhất, tuy nhiên có 2 lần chậm trả nợ lãi nhóm 2 ngắn hạn dưới 30 ngày.","notes":"Hệ số nợ vay/VCSH tăng mạnh từ 1.4 lên 2.8, khả năng trả lãi ICR giảm từ 4.5 xuống 1.6 tiến sát ngưỡng rủi ro, dòng tiền CFO chuyển sang âm trong năm N do công nợ khách hàng đọng lớn."}}}'::jsonb)
