values ('0878eafa-018f-522f-bb00-55a103af253d', 'r2w-tcnh-03', 'Tài chính - Ngân hàng', 'Risk Analyst (Chuyên viên Quản trị Rủi ro)', 'Bạn là 1 chuyên viên phân tích rủi ro tại Bộ phận Quản trị Rủi ro tín dụng của Ngân hàng Đại Dương. Hiện tại, Phòng Tín dụng đang đề xuất cấp khoản vay trung hạn 400 tỷ VNĐ cho Công ty CP Con Cua (sản xuất thép xây dựng) để mở rộng nhà máy tại Khu công nghiệp Phố Nối A, tỉnh Hưng Yên. Bạn được cung cấp bộ hồ sơ bao gồm: Doanh thu 2024: 2.500 tỷ VNĐ, lợi nhuận sau thuế: 150 tỷ VNĐ; Hệ số nợ vay/VCSH (D/E): 4,2; Hệ số thanh toán hiện hành: 0,85; Tỷ lệ nợ xấu nội bộ: 2%. Ngành thép đang đối mặt với biến động giá nguyên liệu (quặng sắt, than cốc) và cạnh tranh gay gắt từ thép nhập khẩu Trung Quốc. Ngân hàng yêu cầu bạn đánh giá toàn diện rủi ro và đưa ra khuyến nghị về việc cấp tín dụng.', '## Bối cảnh

Bạn là 1 chuyên viên phân tích rủi ro tại Bộ phận Quản trị Rủi ro tín dụng của Ngân hàng Đại Dương. Hiện tại, Phòng Tín dụng đang đề xuất cấp khoản vay trung hạn 400 tỷ VNĐ cho Công ty CP Con Cua (sản xuất thép xây dựng) để mở rộng nhà máy tại Khu công nghiệp Phố Nối A, tỉnh Hưng Yên. Bạn được cung cấp bộ hồ sơ bao gồm: Doanh thu 2024: 2.500 tỷ VNĐ, lợi nhuận sau thuế: 150 tỷ VNĐ; Hệ số nợ vay/VCSH (D/E): 4,2; Hệ số thanh toán hiện hành: 0,85; Tỷ lệ nợ xấu nội bộ: 2%. Ngành thép đang đối mặt với biến động giá nguyên liệu (quặng sắt, than cốc) và cạnh tranh gay gắt từ thép nhập khẩu Trung Quốc. Ngân hàng yêu cầu bạn đánh giá toàn diện rủi ro và đưa ra khuyến nghị về việc cấp tín dụng.

## Yêu cầu nhiệm vụ

1. Phân tích rủi ro tín dụng dựa trên các chỉ số D/E, Thanh khoản, Lợi nhuận biên và các yếu tố vĩ mô/ngành.

2. Đề xuất ít nhất 3 biện pháp bảo vệ ngân hàng và giải thích cơ chế của từng biện pháp.

3. Viết báo cáo ngắn (tối đa 200 từ) gửi Hội đồng Tín dụng với kết luận: Đồng ý cho vay / Cho vay có điều kiện / Từ chối.', 60, 120, 'TCNH-03', true, null, '[{"id":"C1","label":"Mức độ chính xác và chiều sâu trong phân tích rủi ro tài chính","weight":40,"maxScore":40},{"id":"C2","label":"Đề xuất giải pháp bảo vệ ngân hàng","weight":20,"maxScore":20},{"id":"C3","label":"Năng lực viết báo cáo, lập luận","weight":30,"maxScore":30},{"id":"C4","label":"Trình bày cấu trúc và thời gian","weight":10,"maxScore":10}]'::jsonb, '[{"id":"C1","label":"Mức độ chính xác và chiều sâu trong phân tích rủi ro tài chính","description":"{\"checklist\":[{\"text\":\"Phân tích đúng và đầy đủ các chỉ số D/E (4,2), Thanh khoản (0,85), Lợi nhuận biên và kết luận đúng về mức rủi ro tài chính\",\"points\":25,\"checklist_id\":\"TCNH-03-C1-1\",\"scoring_source\":\"ai\"},{\"text\":\"Phân tích được các yếu tố rủi ro vĩ mô/ngành (biến động giá nguyên liệu, cạnh tranh thép nhập khẩu Trung Quốc) và liên hệ với khả năng trả nợ của doanh nghiệp\",\"points\":15,\"checklist_id\":\"TCNH-03-C1-2\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":40,"maxScore":40},{"id":"C2","label":"Đề xuất giải pháp bảo vệ ngân hàng","description":"{\"checklist\":[{\"text\":\"Đề xuất chính xác ít nhất 3 giải pháp và nêu được cơ chế của từng biện pháp đối với ngân hàng (VD: tài sản thế chấp bổ sung, giải ngân theo tiến độ, covenant tài chính, bảo lãnh của công ty mẹ)\",\"points\":20,\"checklist_id\":\"TCNH-03-C2-1\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":20,"maxScore":20},{"id":"C3","label":"Năng lực viết báo cáo, lập luận","description":"{\"checklist\":[{\"text\":\"Có tiêu đề, người nhận, mở đầu - kết thúc đầy đủ\",\"points\":10,\"checklist_id\":\"TCNH-03-C3-1\",\"scoring_source\":\"ai\"},{\"text\":\"Khuyến nghị rõ ràng kèm lý do\",\"points\":10,\"checklist_id\":\"TCNH-03-C3-2\",\"scoring_source\":\"ai\"},{\"text\":\"Ngôn ngữ súc tích, không lan man, đúng giới hạn tối đa 200 từ\",\"points\":10,\"checklist_id\":\"TCNH-03-C3-3\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":30,"maxScore":30},{"id":"C4","label":"Trình bày cấu trúc và thời gian","description":"{\"checklist\":[{\"text\":\"Bài làm có cấu trúc rõ ràng, logic theo thứ tự các phần yêu cầu\",\"points\":5,\"checklist_id\":\"TCNH-03-C4-1\",\"scoring_source\":\"ai\"},{\"text\":\"Sử dụng bảng biểu, ngôn ngữ tài chính chính xác\",\"points\":3,\"checklist_id\":\"TCNH-03-C4-2\",\"scoring_source\":\"ai\"},{\"text\":\"Hoàn thành bài làm trong đúng thời gian 60 phút\",\"points\":2,\"checklist_id\":\"TCNH-03-C4-3\",\"scoring_source\":\"system\"}],\"hard_constraints\":[]}","keywords":[],"weight":10,"maxScore":10}]'::jsonb, '{"position_id":"TCNH-03","position_name":"Risk Analyst (Chuyên viên Quản trị Rủi ro)","level":"Fresher/Junior","time_limit_minutes":60,"context":"Bạn là 1 chuyên viên phân tích rủi ro tại Bộ phận Quản trị Rủi ro tín dụng của Ngân hàng Đại Dương. Hiện tại, Phòng Tín dụng đang đề xuất cấp khoản vay trung hạn 400 tỷ VNĐ cho Công ty CP Con Cua (sản xuất thép xây dựng) để mở rộng nhà máy tại Khu công nghiệp Phố Nối A, tỉnh Hưng Yên. Bạn được cung cấp bộ hồ sơ bao gồm: Doanh thu 2024: 2.500 tỷ VNĐ, lợi nhuận sau thuế: 150 tỷ VNĐ; Hệ số nợ vay/VCSH (D/E): 4,2; Hệ số thanh toán hiện hành: 0,85; Tỷ lệ nợ xấu nội bộ: 2%. Ngành thép đang đối mặt với biến động giá nguyên liệu (quặng sắt, than cốc) và cạnh tranh gay gắt từ thép nhập khẩu Trung Quốc. Ngân hàng yêu cầu bạn đánh giá toàn diện rủi ro và đưa ra khuyến nghị về việc cấp tín dụng.","requirements":["Phân tích rủi ro tín dụng dựa trên các chỉ số D/E, Thanh khoản, Lợi nhuận biên và các yếu tố vĩ mô/ngành.","Đề xuất ít nhất 3 biện pháp bảo vệ ngân hàng và giải thích cơ chế của từng biện pháp.","Viết báo cáo ngắn (tối đa 200 từ) gửi Hội đồng Tín dụng với kết luận: Đồng ý cho vay / Cho vay có điều kiện / Từ chối."],"rubric":[{"criterion_id":"C1","criterion_name":"Mức độ chính xác và chiều sâu trong phân tích rủi ro tài chính","max_points":40,"checklist":[{"text":"Phân tích đúng và đầy đủ các chỉ số D/E (4,2), Thanh khoản (0,85), Lợi nhuận biên và kết luận đúng về mức rủi ro tài chính","points":25,"checklist_id":"TCNH-03-C1-1","scoring_source":"ai"},{"text":"Phân tích được các yếu tố rủi ro vĩ mô/ngành (biến động giá nguyên liệu, cạnh tranh thép nhập khẩu Trung Quốc) và liên hệ với khả năng trả nợ của doanh nghiệp","points":15,"checklist_id":"TCNH-03-C1-2","scoring_source":"ai"}]},{"criterion_id":"C2","criterion_name":"Đề xuất giải pháp bảo vệ ngân hàng","max_points":20,"checklist":[{"text":"Đề xuất chính xác ít nhất 3 giải pháp và nêu được cơ chế của từng biện pháp đối với ngân hàng (VD: tài sản thế chấp bổ sung, giải ngân theo tiến độ, covenant tài chính, bảo lãnh của công ty mẹ)","points":20,"checklist_id":"TCNH-03-C2-1","scoring_source":"ai"}]},{"criterion_id":"C3","criterion_name":"Năng lực viết báo cáo, lập luận","max_points":30,"checklist":[{"text":"Có tiêu đề, người nhận, mở đầu - kết thúc đầy đủ","points":10,"checklist_id":"TCNH-03-C3-1","scoring_source":"ai"},{"text":"Khuyến nghị rõ ràng kèm lý do","points":10,"checklist_id":"TCNH-03-C3-2","scoring_source":"ai"},{"text":"Ngôn ngữ súc tích, không lan man, đúng giới hạn tối đa 200 từ","points":10,"checklist_id":"TCNH-03-C3-3","scoring_source":"ai"}]},{"criterion_id":"C4","criterion_name":"Trình bày cấu trúc và thời gian","max_points":10,"checklist":[{"text":"Bài làm có cấu trúc rõ ràng, logic theo thứ tự các phần yêu cầu","points":5,"checklist_id":"TCNH-03-C4-1","scoring_source":"ai"},{"text":"Sử dụng bảng biểu, ngôn ngữ tài chính chính xác","points":3,"checklist_id":"TCNH-03-C4-2","scoring_source":"ai"},{"text":"Hoàn thành bài làm trong đúng thời gian 60 phút","points":2,"checklist_id":"TCNH-03-C4-3","scoring_source":"system"}]}],"hard_constraints":[],"artifacts":{}}'::jsonb)
