insert into public.simulations (id, slug, industry, position_title, brief, task_instructions, estimated_minutes, min_words, position_id, is_available, unavailable_reason, rubric, grading_rubric, reference_data)
values ('6d16f729-3ca3-523b-b031-9f1797fc8cd1', 'r2w-mkt-01', 'Marketing', 'Marketing Intern (Thực tập sinh Marketing)', 'Một thương hiệu thời trang địa phương (Local Brand) bán sản phẩm qua Fanpage và Shopee. Nhãn hàng sắp ra mắt BST Thu-Đông dành cho sinh viên. Lượng tương tác trên Fanpage bị sụt giảm 30%, bài đăng lặp lại hình ảnh sản phẩm đơn điệu, chưa có kế hoạch nội dung bài bản và chưa khai thác kênh video ngắn (TikTok/Reels).', '## Bối cảnh

Một thương hiệu thời trang địa phương (Local Brand) bán sản phẩm qua Fanpage và Shopee. Nhãn hàng sắp ra mắt BST Thu-Đông dành cho sinh viên. Lượng tương tác trên Fanpage bị sụt giảm 30%, bài đăng lặp lại hình ảnh sản phẩm đơn điệu, chưa có kế hoạch nội dung bài bản và chưa khai thác kênh video ngắn (TikTok/Reels).

## Yêu cầu nhiệm vụ

1. Xây dựng kế hoạch nội dung 7 ngày ra mắt BST.

2. Viết 01 bài Copywriting hoàn chỉnh cho mẫu sản phẩm chủ đạo.

3. Đề xuất 02 kịch bản video ngắn (TikTok Script 30s) bắt trend.', 45, 120, 'MKT-01', true, null, '[{"id":"C1","label":"Độ chính xác trong quyết định/đề xuất chính","weight":30,"maxScore":30},{"id":"C2","label":"Lý do/lập luận rõ ràng, bám sát tiêu chí đề bài","weight":30,"maxScore":30},{"id":"C3","label":"Khả năng xử lý sâu vấn đề phát sinh trong tình huống","weight":20,"maxScore":20},{"id":"C4","label":"Trình bày mạch lạc, đúng thời gian","weight":20,"maxScore":20}]'::jsonb, '[{"id":"C1","label":"Độ chính xác trong quyết định/đề xuất chính","description":"{\"checklist\":[{\"text\":\"Kế hoạch 7 ngày có đủ 7 ngày nội dung, đa dạng định dạng (không lặp lại kiểu bài cũ đã bị nêu là đơn điệu trong đề bài)\",\"points\":15,\"checklist_id\":\"MKT-01-C1-1\",\"scoring_source\":\"ai\"},{\"text\":\"Nội dung Copywriting và 2 kịch bản TikTok bám đúng đặc điểm BST Thu-Đông và đúng insight sinh viên (đối tượng mục tiêu)\",\"points\":15,\"checklist_id\":\"MKT-01-C1-2\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":30,"maxScore":30},{"id":"C2","label":"Lý do/lập luận rõ ràng, bám sát tiêu chí đề bài","description":"{\"checklist\":[{\"text\":\"Giải thích được vì sao chọn định dạng/kênh/thời điểm đăng cho từng ngày trong kế hoạch\",\"points\":15,\"checklist_id\":\"MKT-01-C2-1\",\"scoring_source\":\"ai\"},{\"text\":\"Copywriting và 2 kịch bản TikTok có lập luận rõ về thông điệp, CTA và lý do bắt trend phù hợp\",\"points\":15,\"checklist_id\":\"MKT-01-C2-2\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":30,"maxScore":30},{"id":"C3","label":"Khả năng xử lý sâu vấn đề phát sinh trong tình huống","description":"{\"checklist\":[{\"text\":\"Đề xuất giải quyết trực tiếp 2 vấn đề nêu trong bối cảnh — tương tác Fanpage giảm 30% và nội dung hình ảnh lặp lại đơn điệu — chứ không làm nội dung chung chung\",\"points\":20,\"checklist_id\":\"MKT-01-C3-1\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":20,"maxScore":20},{"id":"C4","label":"Trình bày mạch lạc, đúng thời gian","description":"{\"checklist\":[{\"text\":\"Bài làm có cấu trúc rõ ràng (lịch 7 ngày dạng bảng, copywriting và kịch bản tách bạch)\",\"points\":12,\"checklist_id\":\"MKT-01-C4-1\",\"scoring_source\":\"ai\"},{\"text\":\"Hoàn thành đúng thời gian quy định (45 phút)\",\"points\":8,\"checklist_id\":\"MKT-01-C4-2\",\"scoring_source\":\"system\"}],\"hard_constraints\":[]}","keywords":[],"weight":20,"maxScore":20}]'::jsonb, '{"position_id":"MKT-01","position_name":"Marketing Intern (Thực tập sinh Marketing)","level":"Intern","time_limit_minutes":45,"context":"Một thương hiệu thời trang địa phương (Local Brand) bán sản phẩm qua Fanpage và Shopee. Nhãn hàng sắp ra mắt BST Thu-Đông dành cho sinh viên. Lượng tương tác trên Fanpage bị sụt giảm 30%, bài đăng lặp lại hình ảnh sản phẩm đơn điệu, chưa có kế hoạch nội dung bài bản và chưa khai thác kênh video ngắn (TikTok/Reels).","requirements":["Xây dựng kế hoạch nội dung 7 ngày ra mắt BST.","Viết 01 bài Copywriting hoàn chỉnh cho mẫu sản phẩm chủ đạo.","Đề xuất 02 kịch bản video ngắn (TikTok Script 30s) bắt trend."],"rubric":[{"criterion_id":"C1","criterion_name":"Độ chính xác trong quyết định/đề xuất chính","max_points":30,"checklist":[{"text":"Kế hoạch 7 ngày có đủ 7 ngày nội dung, đa dạng định dạng (không lặp lại kiểu bài cũ đã bị nêu là đơn điệu trong đề bài)","points":15,"checklist_id":"MKT-01-C1-1","scoring_source":"ai"},{"text":"Nội dung Copywriting và 2 kịch bản TikTok bám đúng đặc điểm BST Thu-Đông và đúng insight sinh viên (đối tượng mục tiêu)","points":15,"checklist_id":"MKT-01-C1-2","scoring_source":"ai"}]},{"criterion_id":"C2","criterion_name":"Lý do/lập luận rõ ràng, bám sát tiêu chí đề bài","max_points":30,"checklist":[{"text":"Giải thích được vì sao chọn định dạng/kênh/thời điểm đăng cho từng ngày trong kế hoạch","points":15,"checklist_id":"MKT-01-C2-1","scoring_source":"ai"},{"text":"Copywriting và 2 kịch bản TikTok có lập luận rõ về thông điệp, CTA và lý do bắt trend phù hợp","points":15,"checklist_id":"MKT-01-C2-2","scoring_source":"ai"}]},{"criterion_id":"C3","criterion_name":"Khả năng xử lý sâu vấn đề phát sinh trong tình huống","max_points":20,"checklist":[{"text":"Đề xuất giải quyết trực tiếp 2 vấn đề nêu trong bối cảnh — tương tác Fanpage giảm 30% và nội dung hình ảnh lặp lại đơn điệu — chứ không làm nội dung chung chung","points":20,"checklist_id":"MKT-01-C3-1","scoring_source":"ai"}]},{"criterion_id":"C4","criterion_name":"Trình bày mạch lạc, đúng thời gian","max_points":20,"checklist":[{"text":"Bài làm có cấu trúc rõ ràng (lịch 7 ngày dạng bảng, copywriting và kịch bản tách bạch)","points":12,"checklist_id":"MKT-01-C4-1","scoring_source":"ai"},{"text":"Hoàn thành đúng thời gian quy định (45 phút)","points":8,"checklist_id":"MKT-01-C4-2","scoring_source":"system"}]}],"hard_constraints":[],"artifacts":{}}'::jsonb)
