insert into public.simulations (id, slug, industry, position_title, brief, task_instructions, estimated_minutes, min_words, position_id, is_available, unavailable_reason, rubric, grading_rubric, reference_data)
values ('1762775b-5a57-53a9-ab91-70f13aa22ba6', 'r2w-mkt-02', 'Marketing', 'Digital Marketing Executive (Chuyên viên Marketing Số)', 'Một trung tâm tiếng Anh giao tiếp tung ra khóa học mới với mục tiêu thu về 100 Lead trong 14 ngày. Ngân sách chạy thử 3 ngày đầu là 5.000.000 VNĐ nhưng chỉ thu được 8 Lead, CPL bị đội lên 625.000 VNĐ/Lead (mục tiêu tối đa 200.000 VNĐ/Lead), CTR chỉ đạt 0,8%.', '## Bối cảnh

Một trung tâm tiếng Anh giao tiếp tung ra khóa học mới với mục tiêu thu về 100 Lead trong 14 ngày. Ngân sách chạy thử 3 ngày đầu là 5.000.000 VNĐ nhưng chỉ thu được 8 Lead, CPL bị đội lên 625.000 VNĐ/Lead (mục tiêu tối đa 200.000 VNĐ/Lead), CTR chỉ đạt 0,8%.

## Yêu cầu nhiệm vụ

1. Đánh giá và chỉ ra 3 nguyên nhân chính khiến CPL tăng cao.

2. Đề xuất phương án tối ưu chiến dịch (A/B Testing Target, Creative, Landing Page).

3. Lập kế hoạch phân bổ 15.000.000 VNĐ còn lại cho 11 ngày tiếp theo để đạt đủ 100 Lead.', 45, 120, 'MKT-02', true, null, '[{"id":"C1","label":"Độ chính xác trong quyết định/đề xuất chính","weight":30,"maxScore":30},{"id":"C2","label":"Lý do/lập luận rõ ràng, bám sát tiêu chí đề bài","weight":30,"maxScore":30},{"id":"C3","label":"Khả năng xử lý sâu vấn đề phát sinh trong tình huống","weight":20,"maxScore":20},{"id":"C4","label":"Trình bày mạch lạc, đúng thời gian","weight":20,"maxScore":20}]'::jsonb, '[{"id":"C1","label":"Độ chính xác trong quyết định/đề xuất chính","description":"{\"checklist\":[{\"text\":\"Chỉ ra đúng 3 nguyên nhân có căn cứ từ số liệu đề bài (CTR 0,8% thấp, CPL 625.000đ vượt xa mục tiêu 200.000đ, ngân sách/thời gian thử nghiệm ngắn)\",\"points\":15,\"checklist_id\":\"MKT-02-C1-1\",\"scoring_source\":\"ai\"},{\"text\":\"Kế hoạch phân bổ 15.000.000 VNĐ cho 11 ngày có con số cụ thể, khả thi để đạt 100 Lead đúng mục tiêu CPL\",\"points\":15,\"checklist_id\":\"MKT-02-C1-2\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":30,"maxScore":30},{"id":"C2","label":"Lý do/lập luận rõ ràng, bám sát tiêu chí đề bài","description":"{\"checklist\":[{\"text\":\"Mỗi nguyên nhân CPL cao được lập luận gắn với chỉ số cụ thể (CTR, CPL, ngân sách)\",\"points\":15,\"checklist_id\":\"MKT-02-C2-1\",\"scoring_source\":\"ai\"},{\"text\":\"Phương án tối ưu A/B Testing nêu rõ biến số thử nghiệm (Target/Creative/Landing Page) và cách đo lường kết quả\",\"points\":15,\"checklist_id\":\"MKT-02-C2-2\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":30,"maxScore":30},{"id":"C3","label":"Khả năng xử lý sâu vấn đề phát sinh trong tình huống","description":"{\"checklist\":[{\"text\":\"Có tính đến ràng buộc thời gian còn lại (11 ngày) và ngân sách còn lại (15.000.000đ) khi đề xuất giải pháp, không đề xuất chung chung thiếu tính khả thi\",\"points\":20,\"checklist_id\":\"MKT-02-C3-1\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":20,"maxScore":20},{"id":"C4","label":"Trình bày mạch lạc, đúng thời gian","description":"{\"checklist\":[{\"text\":\"Có bảng/số liệu minh họa cho kế hoạch phân bổ ngân sách theo ngày/giai đoạn\",\"points\":12,\"checklist_id\":\"MKT-02-C4-1\",\"scoring_source\":\"ai\"},{\"text\":\"Trình bày rõ ràng, hoàn thành đúng thời gian làm bài (45 phút)\",\"points\":8,\"checklist_id\":\"MKT-02-C4-2\",\"scoring_source\":\"hybrid\",\"scoring_source_note\":\"Phần \\\"hoàn thành đúng thời gian\\\" trong ý này do HỆ THỐNG tự động xác định dựa trên time_limit_minutes và actual_duration_seconds (xem time_scoring_rule); phần nội dung còn lại của ý này vẫn do AI đánh giá như checklist gốc.\"}],\"hard_constraints\":[]}","keywords":[],"weight":20,"maxScore":20}]'::jsonb, '{"position_id":"MKT-02","position_name":"Digital Marketing Executive (Chuyên viên Marketing Số)","level":"Fresher/Junior","time_limit_minutes":45,"context":"Một trung tâm tiếng Anh giao tiếp tung ra khóa học mới với mục tiêu thu về 100 Lead trong 14 ngày. Ngân sách chạy thử 3 ngày đầu là 5.000.000 VNĐ nhưng chỉ thu được 8 Lead, CPL bị đội lên 625.000 VNĐ/Lead (mục tiêu tối đa 200.000 VNĐ/Lead), CTR chỉ đạt 0,8%.","requirements":["Đánh giá và chỉ ra 3 nguyên nhân chính khiến CPL tăng cao.","Đề xuất phương án tối ưu chiến dịch (A/B Testing Target, Creative, Landing Page).","Lập kế hoạch phân bổ 15.000.000 VNĐ còn lại cho 11 ngày tiếp theo để đạt đủ 100 Lead."],"rubric":[{"criterion_id":"C1","criterion_name":"Độ chính xác trong quyết định/đề xuất chính","max_points":30,"checklist":[{"text":"Chỉ ra đúng 3 nguyên nhân có căn cứ từ số liệu đề bài (CTR 0,8% thấp, CPL 625.000đ vượt xa mục tiêu 200.000đ, ngân sách/thời gian thử nghiệm ngắn)","points":15,"checklist_id":"MKT-02-C1-1","scoring_source":"ai"},{"text":"Kế hoạch phân bổ 15.000.000 VNĐ cho 11 ngày có con số cụ thể, khả thi để đạt 100 Lead đúng mục tiêu CPL","points":15,"checklist_id":"MKT-02-C1-2","scoring_source":"ai"}]},{"criterion_id":"C2","criterion_name":"Lý do/lập luận rõ ràng, bám sát tiêu chí đề bài","max_points":30,"checklist":[{"text":"Mỗi nguyên nhân CPL cao được lập luận gắn với chỉ số cụ thể (CTR, CPL, ngân sách)","points":15,"checklist_id":"MKT-02-C2-1","scoring_source":"ai"},{"text":"Phương án tối ưu A/B Testing nêu rõ biến số thử nghiệm (Target/Creative/Landing Page) và cách đo lường kết quả","points":15,"checklist_id":"MKT-02-C2-2","scoring_source":"ai"}]},{"criterion_id":"C3","criterion_name":"Khả năng xử lý sâu vấn đề phát sinh trong tình huống","max_points":20,"checklist":[{"text":"Có tính đến ràng buộc thời gian còn lại (11 ngày) và ngân sách còn lại (15.000.000đ) khi đề xuất giải pháp, không đề xuất chung chung thiếu tính khả thi","points":20,"checklist_id":"MKT-02-C3-1","scoring_source":"ai"}]},{"criterion_id":"C4","criterion_name":"Trình bày mạch lạc, đúng thời gian","max_points":20,"checklist":[{"text":"Có bảng/số liệu minh họa cho kế hoạch phân bổ ngân sách theo ngày/giai đoạn","points":12,"checklist_id":"MKT-02-C4-1","scoring_source":"ai"},{"text":"Trình bày rõ ràng, hoàn thành đúng thời gian làm bài (45 phút)","points":8,"checklist_id":"MKT-02-C4-2","scoring_source":"hybrid","scoring_source_note":"Phần \"hoàn thành đúng thời gian\" trong ý này do HỆ THỐNG tự động xác định dựa trên time_limit_minutes và actual_duration_seconds (xem time_scoring_rule); phần nội dung còn lại của ý này vẫn do AI đánh giá như checklist gốc."}]}],"hard_constraints":[],"artifacts":{}}'::jsonb)
