insert into public.simulations (id, slug, industry, position_title, brief, task_instructions, estimated_minutes, min_words, position_id, is_available, unavailable_reason, rubric, grading_rubric, reference_data)
values ('e0f08d10-acc9-58fe-8a27-aa9625092067', 'r2w-mkt-03', 'Marketing', 'Content Marketing Specialist (Chuyên viên Sáng tạo Nội dung)', 'Một công ty SaaS kinh doanh Phần mềm Quản lý Bán hàng cho cửa hàng F&B vừa và nhỏ chuẩn bị ra mắt tính năng "Tự động quản lý nguyên vật liệu & cảnh báo tồn kho". Lượng Organic Traffic vào Website hiện rất thấp, Blog thiếu các bài viết chuyên sâu giải quyết đúng "nỗi đau" khách hàng.', '## Bối cảnh

Một công ty SaaS kinh doanh Phần mềm Quản lý Bán hàng cho cửa hàng F&B vừa và nhỏ chuẩn bị ra mắt tính năng "Tự động quản lý nguyên vật liệu & cảnh báo tồn kho". Lượng Organic Traffic vào Website hiện rất thấp, Blog thiếu các bài viết chuyên sâu giải quyết đúng "nỗi đau" khách hàng.

## Yêu cầu nhiệm vụ

1. Xây dựng Kế hoạch Nội dung 1 tháng áp dụng mô hình Phễu Marketing (TOFU - MOFU - BOFU) với 6 chủ đề.

2. Chọn bộ 5 từ khóa SEO chủ đạo.

3. Viết 01 bài viết chuẩn SEO (~800-1000 từ) cho giai đoạn MOFU.', 60, 120, 'MKT-03', true, null, '[{"id":"C1","label":"Độ chính xác trong quyết định/đề xuất chính","weight":30,"maxScore":30},{"id":"C2","label":"Lý do/lập luận rõ ràng, bám sát tiêu chí đề bài","weight":30,"maxScore":30},{"id":"C3","label":"Khả năng xử lý sâu vấn đề phát sinh trong tình huống","weight":20,"maxScore":20},{"id":"C4","label":"Trình bày mạch lạc, đúng thời gian","weight":20,"maxScore":20}]'::jsonb, '[{"id":"C1","label":"Độ chính xác trong quyết định/đề xuất chính","description":"{\"checklist\":[{\"text\":\"6 chủ đề được phân bổ đúng và hợp lý theo 3 giai đoạn phễu TOFU - MOFU - BOFU\",\"points\":15,\"checklist_id\":\"MKT-03-C1-1\",\"scoring_source\":\"ai\"},{\"text\":\"Bộ 5 từ khóa SEO liên quan trực tiếp đến tính năng \\\"Tự động quản lý nguyên vật liệu & cảnh báo tồn kho\\\" và đúng ý định tìm kiếm (search intent) của khách hàng F&B mục tiêu\",\"points\":15,\"checklist_id\":\"MKT-03-C1-2\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":30,"maxScore":30},{"id":"C2","label":"Lý do/lập luận rõ ràng, bám sát tiêu chí đề bài","description":"{\"checklist\":[{\"text\":\"Giải thích được vì sao mỗi chủ đề thuộc đúng giai đoạn phễu đã chọn\",\"points\":15,\"checklist_id\":\"MKT-03-C2-1\",\"scoring_source\":\"ai\"},{\"text\":\"Bài viết MOFU giải quyết đúng \\\"nỗi đau\\\" tồn kho/nguyên vật liệu của chủ cửa hàng F&B đã nêu trong bối cảnh, có tối ưu từ khóa SEO tự nhiên trong bài\",\"points\":15,\"checklist_id\":\"MKT-03-C2-2\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":30,"maxScore":30},{"id":"C3","label":"Khả năng xử lý sâu vấn đề phát sinh trong tình huống","description":"{\"checklist\":[{\"text\":\"Nội dung đề xuất có hướng giải quyết trực tiếp vấn đề Organic Traffic thấp và thiếu bài viết chuyên sâu đã nêu trong bối cảnh, không chỉ liệt kê chủ đề chung chung\",\"points\":20,\"checklist_id\":\"MKT-03-C3-1\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":20,"maxScore":20},{"id":"C4","label":"Trình bày mạch lạc, đúng thời gian","description":"{\"checklist\":[{\"text\":\"Bài viết SEO đạt đúng khoảng 800-1000 từ, có cấu trúc heading rõ ràng (H1/H2)\",\"points\":12,\"checklist_id\":\"MKT-03-C4-1\",\"scoring_source\":\"ai\"},{\"text\":\"Kế hoạch nội dung trình bày dạng bảng theo tuần/giai đoạn; hoàn thành đúng thời gian (60 phút)\",\"points\":8,\"checklist_id\":\"MKT-03-C4-2\",\"scoring_source\":\"hybrid\",\"scoring_source_note\":\"Phần \\\"hoàn thành đúng thời gian\\\" trong ý này do HỆ THỐNG tự động xác định dựa trên time_limit_minutes và actual_duration_seconds (xem time_scoring_rule); phần nội dung còn lại của ý này vẫn do AI đánh giá như checklist gốc.\"}],\"hard_constraints\":[]}","keywords":[],"weight":20,"maxScore":20}]'::jsonb, '{"position_id":"MKT-03","position_name":"Content Marketing Specialist (Chuyên viên Sáng tạo Nội dung)","level":"Junior","time_limit_minutes":60,"context":"Một công ty SaaS kinh doanh Phần mềm Quản lý Bán hàng cho cửa hàng F&B vừa và nhỏ chuẩn bị ra mắt tính năng \"Tự động quản lý nguyên vật liệu & cảnh báo tồn kho\". Lượng Organic Traffic vào Website hiện rất thấp, Blog thiếu các bài viết chuyên sâu giải quyết đúng \"nỗi đau\" khách hàng.","requirements":["Xây dựng Kế hoạch Nội dung 1 tháng áp dụng mô hình Phễu Marketing (TOFU - MOFU - BOFU) với 6 chủ đề.","Chọn bộ 5 từ khóa SEO chủ đạo.","Viết 01 bài viết chuẩn SEO (~800-1000 từ) cho giai đoạn MOFU."],"rubric":[{"criterion_id":"C1","criterion_name":"Độ chính xác trong quyết định/đề xuất chính","max_points":30,"checklist":[{"text":"6 chủ đề được phân bổ đúng và hợp lý theo 3 giai đoạn phễu TOFU - MOFU - BOFU","points":15,"checklist_id":"MKT-03-C1-1","scoring_source":"ai"},{"text":"Bộ 5 từ khóa SEO liên quan trực tiếp đến tính năng \"Tự động quản lý nguyên vật liệu & cảnh báo tồn kho\" và đúng ý định tìm kiếm (search intent) của khách hàng F&B mục tiêu","points":15,"checklist_id":"MKT-03-C1-2","scoring_source":"ai"}]},{"criterion_id":"C2","criterion_name":"Lý do/lập luận rõ ràng, bám sát tiêu chí đề bài","max_points":30,"checklist":[{"text":"Giải thích được vì sao mỗi chủ đề thuộc đúng giai đoạn phễu đã chọn","points":15,"checklist_id":"MKT-03-C2-1","scoring_source":"ai"},{"text":"Bài viết MOFU giải quyết đúng \"nỗi đau\" tồn kho/nguyên vật liệu của chủ cửa hàng F&B đã nêu trong bối cảnh, có tối ưu từ khóa SEO tự nhiên trong bài","points":15,"checklist_id":"MKT-03-C2-2","scoring_source":"ai"}]},{"criterion_id":"C3","criterion_name":"Khả năng xử lý sâu vấn đề phát sinh trong tình huống","max_points":20,"checklist":[{"text":"Nội dung đề xuất có hướng giải quyết trực tiếp vấn đề Organic Traffic thấp và thiếu bài viết chuyên sâu đã nêu trong bối cảnh, không chỉ liệt kê chủ đề chung chung","points":20,"checklist_id":"MKT-03-C3-1","scoring_source":"ai"}]},{"criterion_id":"C4","criterion_name":"Trình bày mạch lạc, đúng thời gian","max_points":20,"checklist":[{"text":"Bài viết SEO đạt đúng khoảng 800-1000 từ, có cấu trúc heading rõ ràng (H1/H2)","points":12,"checklist_id":"MKT-03-C4-1","scoring_source":"ai"},{"text":"Kế hoạch nội dung trình bày dạng bảng theo tuần/giai đoạn; hoàn thành đúng thời gian (60 phút)","points":8,"checklist_id":"MKT-03-C4-2","scoring_source":"hybrid","scoring_source_note":"Phần \"hoàn thành đúng thời gian\" trong ý này do HỆ THỐNG tự động xác định dựa trên time_limit_minutes và actual_duration_seconds (xem time_scoring_rule); phần nội dung còn lại của ý này vẫn do AI đánh giá như checklist gốc."}]}],"hard_constraints":[],"artifacts":{}}'::jsonb)
