insert into public.simulations (id, slug, industry, position_title, brief, task_instructions, estimated_minutes, min_words, position_id, is_available, unavailable_reason, rubric, grading_rubric, reference_data)
values ('dc733352-6e39-5c00-9599-f08eef282abb', 'r2w-it-01', 'Công nghệ thông tin', 'Business Analyst (IT BA / Chuyên viên Phân tích Nghiệp vụ)', 'Một trung tâm đào tạo hiện quản lý học viên bằng Excel. Khi học viên đăng ký khóa học, nhân viên phải nhập thông tin thủ công, kiểm tra lớp còn chỗ và xác nhận học phí. Việc này dẫn đến dữ liệu bị trùng, cập nhật trạng thái chậm và khó theo dõi số lượng học viên theo lớp. Trung tâm muốn xây dựng chức năng đăng ký khóa học trực tuyến trên hệ thống quản lý học viên, với các yêu cầu từ quản lý: (1) Học viên có thể xem danh sách khóa học và số chỗ còn lại; (2) Học viên chọn khóa học và gửi đăng ký; (3) Hệ thống kiểm tra điều kiện đăng ký và số chỗ; (4) Sau khi đăng ký, hệ thống ghi nhận thông tin và chuyển trạng thái sang "Chờ xác nhận học phí"; (5) Nhân viên có thể xem danh sách đăng ký và cập nhật trạng thái học phí.', '## Bối cảnh

Một trung tâm đào tạo hiện quản lý học viên bằng Excel. Khi học viên đăng ký khóa học, nhân viên phải nhập thông tin thủ công, kiểm tra lớp còn chỗ và xác nhận học phí. Việc này dẫn đến dữ liệu bị trùng, cập nhật trạng thái chậm và khó theo dõi số lượng học viên theo lớp. Trung tâm muốn xây dựng chức năng đăng ký khóa học trực tuyến trên hệ thống quản lý học viên, với các yêu cầu từ quản lý: (1) Học viên có thể xem danh sách khóa học và số chỗ còn lại; (2) Học viên chọn khóa học và gửi đăng ký; (3) Hệ thống kiểm tra điều kiện đăng ký và số chỗ; (4) Sau khi đăng ký, hệ thống ghi nhận thông tin và chuyển trạng thái sang "Chờ xác nhận học phí"; (5) Nhân viên có thể xem danh sách đăng ký và cập nhật trạng thái học phí.

## Yêu cầu nhiệm vụ

1. Xác định 5 yêu cầu chức năng chính (Functional Requirements) từ mô tả nghiệp vụ trên.

2. Viết 3 User Stories cho các nhóm người dùng liên quan.

3. Viết Acceptance Criteria (AC) cho cả 3 User Stories.', 60, 120, 'IT-01', true, null, '[{"id":"C1","label":"Độ chính xác và đầy đủ của Yêu cầu chức năng","weight":30,"maxScore":30},{"id":"C2","label":"Chất lượng User Stories","weight":25,"maxScore":25},{"id":"C3","label":"Chất lượng Acceptance Criteria","weight":25,"maxScore":25},{"id":"C4","label":"Trình bày mạch lạc, đúng thời gian","weight":20,"maxScore":20}]'::jsonb, '[{"id":"C1","label":"Độ chính xác và đầy đủ của Yêu cầu chức năng","description":"{\"checklist\":[{\"text\":\"Xác định đủ 5 yêu cầu chức năng, mỗi yêu cầu bám sát đúng 5 gạch đầu dòng nghiệp vụ đã mô tả (không bỏ sót, không suy diễn thêm yêu cầu không có căn cứ)\",\"points\":20,\"checklist_id\":\"IT-01-C1-1\",\"scoring_source\":\"ai\"},{\"text\":\"Yêu cầu chức năng được viết rõ ràng, có thể chuyển giao trực tiếp cho đội phát triển\",\"points\":10,\"checklist_id\":\"IT-01-C1-2\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":30,"maxScore":30},{"id":"C2","label":"Chất lượng User Stories","description":"{\"checklist\":[{\"text\":\"Đúng định dạng chuẩn \\\"Là [vai trò], tôi muốn [hành động], để [giá trị/lợi ích]\\\" cho cả 3 story\",\"points\":10,\"checklist_id\":\"IT-01-C2-1\",\"scoring_source\":\"ai\"},{\"text\":\"3 User Stories bao phủ đủ các vai trò liên quan (Học viên, Nhân viên, góc nhìn hệ thống/quản lý)\",\"points\":10,\"checklist_id\":\"IT-01-C2-2\",\"scoring_source\":\"ai\"},{\"text\":\"Mỗi story độc lập, có giá trị nghiệp vụ rõ ràng, không trùng lặp nội dung\",\"points\":5,\"checklist_id\":\"IT-01-C2-3\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":25,"maxScore":25},{"id":"C3","label":"Chất lượng Acceptance Criteria","description":"{\"checklist\":[{\"text\":\"AC viết theo cấu trúc rõ ràng (khuyến khích Given-When-Then hoặc gạch đầu dòng điều kiện đạt/không đạt)\",\"points\":10,\"checklist_id\":\"IT-01-C3-1\",\"scoring_source\":\"ai\"},{\"text\":\"AC bao phủ được trường hợp chính (happy path) và ít nhất 1 trường hợp ngoại lệ mỗi story (VD: hết chỗ, sai điều kiện đăng ký)\",\"points\":10,\"checklist_id\":\"IT-01-C3-2\",\"scoring_source\":\"ai\"},{\"text\":\"AC nhất quán với User Story và Yêu cầu chức năng tương ứng\",\"points\":5,\"checklist_id\":\"IT-01-C3-3\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":25,"maxScore":25},{"id":"C4","label":"Trình bày mạch lạc, đúng thời gian","description":"{\"checklist\":[{\"text\":\"Tài liệu có cấu trúc rõ ràng, đúng thứ tự (Yêu cầu chức năng → User Stories → Acceptance Criteria), dễ theo dõi để bàn giao cho đội phát triển\",\"points\":10,\"checklist_id\":\"IT-01-C4-1\",\"scoring_source\":\"ai\"},{\"text\":\"Dùng đúng thuật ngữ BA chuẩn; hoàn thành đúng thời gian 60 phút\",\"points\":10,\"checklist_id\":\"IT-01-C4-2\",\"scoring_source\":\"hybrid\",\"scoring_source_note\":\"Phần \\\"hoàn thành đúng thời gian\\\" trong ý này do HỆ THỐNG tự động xác định dựa trên time_limit_minutes và actual_duration_seconds (xem time_scoring_rule); phần nội dung còn lại của ý này vẫn do AI đánh giá như checklist gốc.\"}],\"hard_constraints\":[]}","keywords":[],"weight":20,"maxScore":20}]'::jsonb, '{"position_id":"IT-01","position_name":"Business Analyst (IT BA / Chuyên viên Phân tích Nghiệp vụ)","level":"Fresher/Junior","time_limit_minutes":60,"context":"Một trung tâm đào tạo hiện quản lý học viên bằng Excel. Khi học viên đăng ký khóa học, nhân viên phải nhập thông tin thủ công, kiểm tra lớp còn chỗ và xác nhận học phí. Việc này dẫn đến dữ liệu bị trùng, cập nhật trạng thái chậm và khó theo dõi số lượng học viên theo lớp. Trung tâm muốn xây dựng chức năng đăng ký khóa học trực tuyến trên hệ thống quản lý học viên, với các yêu cầu từ quản lý: (1) Học viên có thể xem danh sách khóa học và số chỗ còn lại; (2) Học viên chọn khóa học và gửi đăng ký; (3) Hệ thống kiểm tra điều kiện đăng ký và số chỗ; (4) Sau khi đăng ký, hệ thống ghi nhận thông tin và chuyển trạng thái sang \"Chờ xác nhận học phí\"; (5) Nhân viên có thể xem danh sách đăng ký và cập nhật trạng thái học phí.","requirements":["Xác định 5 yêu cầu chức năng chính (Functional Requirements) từ mô tả nghiệp vụ trên.","Viết 3 User Stories cho các nhóm người dùng liên quan.","Viết Acceptance Criteria (AC) cho cả 3 User Stories."],"rubric":[{"criterion_id":"C1","criterion_name":"Độ chính xác và đầy đủ của Yêu cầu chức năng","max_points":30,"checklist":[{"text":"Xác định đủ 5 yêu cầu chức năng, mỗi yêu cầu bám sát đúng 5 gạch đầu dòng nghiệp vụ đã mô tả (không bỏ sót, không suy diễn thêm yêu cầu không có căn cứ)","points":20,"checklist_id":"IT-01-C1-1","scoring_source":"ai"},{"text":"Yêu cầu chức năng được viết rõ ràng, có thể chuyển giao trực tiếp cho đội phát triển","points":10,"checklist_id":"IT-01-C1-2","scoring_source":"ai"}]},{"criterion_id":"C2","criterion_name":"Chất lượng User Stories","max_points":25,"checklist":[{"text":"Đúng định dạng chuẩn \"Là [vai trò], tôi muốn [hành động], để [giá trị/lợi ích]\" cho cả 3 story","points":10,"checklist_id":"IT-01-C2-1","scoring_source":"ai"},{"text":"3 User Stories bao phủ đủ các vai trò liên quan (Học viên, Nhân viên, góc nhìn hệ thống/quản lý)","points":10,"checklist_id":"IT-01-C2-2","scoring_source":"ai"},{"text":"Mỗi story độc lập, có giá trị nghiệp vụ rõ ràng, không trùng lặp nội dung","points":5,"checklist_id":"IT-01-C2-3","scoring_source":"ai"}]},{"criterion_id":"C3","criterion_name":"Chất lượng Acceptance Criteria","max_points":25,"checklist":[{"text":"AC viết theo cấu trúc rõ ràng (khuyến khích Given-When-Then hoặc gạch đầu dòng điều kiện đạt/không đạt)","points":10,"checklist_id":"IT-01-C3-1","scoring_source":"ai"},{"text":"AC bao phủ được trường hợp chính (happy path) và ít nhất 1 trường hợp ngoại lệ mỗi story (VD: hết chỗ, sai điều kiện đăng ký)","points":10,"checklist_id":"IT-01-C3-2","scoring_source":"ai"},{"text":"AC nhất quán với User Story và Yêu cầu chức năng tương ứng","points":5,"checklist_id":"IT-01-C3-3","scoring_source":"ai"}]},{"criterion_id":"C4","criterion_name":"Trình bày mạch lạc, đúng thời gian","max_points":20,"checklist":[{"text":"Tài liệu có cấu trúc rõ ràng, đúng thứ tự (Yêu cầu chức năng → User Stories → Acceptance Criteria), dễ theo dõi để bàn giao cho đội phát triển","points":10,"checklist_id":"IT-01-C4-1","scoring_source":"ai"},{"text":"Dùng đúng thuật ngữ BA chuẩn; hoàn thành đúng thời gian 60 phút","points":10,"checklist_id":"IT-01-C4-2","scoring_source":"hybrid","scoring_source_note":"Phần \"hoàn thành đúng thời gian\" trong ý này do HỆ THỐNG tự động xác định dựa trên time_limit_minutes và actual_duration_seconds (xem time_scoring_rule); phần nội dung còn lại của ý này vẫn do AI đánh giá như checklist gốc."}]}],"hard_constraints":[],"artifacts":{}}'::jsonb)
