insert into public.simulations (id, slug, industry, position_title, brief, task_instructions, estimated_minutes, min_words, position_id, is_available, unavailable_reason, rubric, grading_rubric, reference_data)
values ('f40f7bfb-899f-5007-9500-11fff91358f6', 'r2w-it-02', 'Công nghệ thông tin', 'Software Tester / QA (Chuyên viên Kiểm thử / Đảm bảo Chất lượng)', 'Một ứng dụng đặt đồ ăn vừa phát triển xong tính năng "Giỏ hàng & Thanh toán". Trong vòng test nội bộ, đội QA ghi nhận 2 lỗi sau: Lỗi 1 - Sai tổng tiền: Giỏ hàng 2 ly trà sữa (35.000đ/ly) + phí giao hàng 15.000đ. Khách nhập mã giảm giá SALE20 (giảm 20% trên tổng đơn hàng, không áp dụng cho phí ship). Hệ thống hiển thị tổng thanh toán = 68.000đ (số đúng phải là (70.000 × 0,8) + 15.000 = 71.000đ). Lỗi 2 - Đơn hàng bị trùng: Khách bấm nút "Đặt hàng" lúc mạng chập chờn (loading xoay hơn 3 giây). Khách bấm thêm lần 2 vì tưởng chưa nhận. Sau đó vào mục "Đơn hàng của tôi" thấy xuất hiện 2 đơn giống hệt nhau, cùng bị trừ tiền 2 lần trong lịch sử giao dịch.', '## Bối cảnh

Một ứng dụng đặt đồ ăn vừa phát triển xong tính năng "Giỏ hàng & Thanh toán". Trong vòng test nội bộ, đội QA ghi nhận 2 lỗi sau: Lỗi 1 - Sai tổng tiền: Giỏ hàng 2 ly trà sữa (35.000đ/ly) + phí giao hàng 15.000đ. Khách nhập mã giảm giá SALE20 (giảm 20% trên tổng đơn hàng, không áp dụng cho phí ship). Hệ thống hiển thị tổng thanh toán = 68.000đ (số đúng phải là (70.000 × 0,8) + 15.000 = 71.000đ). Lỗi 2 - Đơn hàng bị trùng: Khách bấm nút "Đặt hàng" lúc mạng chập chờn (loading xoay hơn 3 giây). Khách bấm thêm lần 2 vì tưởng chưa nhận. Sau đó vào mục "Đơn hàng của tôi" thấy xuất hiện 2 đơn giống hệt nhau, cùng bị trừ tiền 2 lần trong lịch sử giao dịch.

## Yêu cầu nhiệm vụ

1. Viết 2 Bug Report theo mẫu chuẩn cho 2 lỗi đã mô tả, mỗi report gồm: Tiêu đề, Các bước tái hiện, Kết quả mong đợi, Kết quả thực tế, Mức độ nghiêm trọng, Đề xuất hướng xử lý.', 45, 120, 'IT-02', true, null, '[{"id":"C1","label":"Độ chính xác trong mô tả lỗi","weight":30,"maxScore":30},{"id":"C2","label":"Chất lượng các bước tái hiện lỗi (Steps to Reproduce)","weight":25,"maxScore":25},{"id":"C3","label":"Đánh giá Mức độ nghiêm trọng (Severity) và Đề xuất hướng xử lý","weight":25,"maxScore":25},{"id":"C4","label":"Trình bày đúng mẫu Bug Report và thời gian","weight":20,"maxScore":20}]'::jsonb, '[{"id":"C1","label":"Độ chính xác trong mô tả lỗi","description":"{\"checklist\":[{\"text\":\"Bug 1: tính đúng số tiền kỳ vọng (70.000 × 0,8 + 15.000 = 71.000đ) và chỉ rõ nguyên nhân là mã giảm giá bị áp dụng nhầm luôn cho phí ship\",\"points\":15,\"checklist_id\":\"IT-02-C1-1\",\"scoring_source\":\"ai\"},{\"text\":\"Bug 2: mô tả đúng nguyên nhân khả dĩ (double-click/timeout khi mạng chập chờn khiến gọi API đặt hàng 2 lần) và hệ quả bị trừ tiền 2 lần\",\"points\":15,\"checklist_id\":\"IT-02-C1-2\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":30,"maxScore":30},{"id":"C2","label":"Chất lượng các bước tái hiện lỗi (Steps to Reproduce)","description":"{\"checklist\":[{\"text\":\"Các bước được viết tuần tự, rõ ràng, người khác có thể làm theo để tái hiện đúng lỗi, không bỏ sót điều kiện tiên quyết (VD: áp mã SALE20; điều kiện mạng chập chờn) cho cả 2 report\",\"points\":25,\"checklist_id\":\"IT-02-C2-1\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":25,"maxScore":25},{"id":"C3","label":"Đánh giá Mức độ nghiêm trọng (Severity) và Đề xuất hướng xử lý","description":"{\"checklist\":[{\"text\":\"Đánh giá đúng mức độ nghiêm trọng phù hợp bản chất lỗi (cả 2 lỗi liên quan trực tiếp giao dịch tài chính nên cần xếp mức Nghiêm trọng/Critical-High, có giải thích lý do)\",\"points\":15,\"checklist_id\":\"IT-02-C3-1\",\"scoring_source\":\"ai\"},{\"text\":\"Đề xuất hướng xử lý hợp lý cho từng lỗi (VD: sửa logic tính giảm giá loại trừ phí ship; thêm cơ chế chống double-submit/idempotency key khi đặt hàng)\",\"points\":10,\"checklist_id\":\"IT-02-C3-2\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":25,"maxScore":25},{"id":"C4","label":"Trình bày đúng mẫu Bug Report và thời gian","description":"{\"checklist\":[{\"text\":\"Mỗi report có đủ 5 trường bắt buộc (Tiêu đề, Các bước tái hiện, Kết quả mong đợi, Kết quả thực tế, Mức độ nghiêm trọng) và Đề xuất hướng xử lý\",\"points\":12,\"checklist_id\":\"IT-02-C4-1\",\"scoring_source\":\"ai\"},{\"text\":\"Tiêu đề report ngắn gọn, nêu được bản chất lỗi; hoàn thành đúng thời gian (45 phút)\",\"points\":8,\"checklist_id\":\"IT-02-C4-2\",\"scoring_source\":\"hybrid\",\"scoring_source_note\":\"Phần \\\"hoàn thành đúng thời gian\\\" trong ý này do HỆ THỐNG tự động xác định dựa trên time_limit_minutes và actual_duration_seconds (xem time_scoring_rule); phần nội dung còn lại của ý này vẫn do AI đánh giá như checklist gốc.\"}],\"hard_constraints\":[{\"constraint_id\":\"IT-02-HC1\",\"type\":\"required_elements\",\"trigger_checklist_id\":\"IT-02-C4-1\",\"condition\":\"Mỗi Bug Report phải có đủ 5 trường bắt buộc: Tiêu đề, Các bước tái hiện, Kết quả mong đợi, Kết quả thực tế, Mức độ nghiêm trọng (và Đề xuất hướng xử lý).\",\"effect\":\"Thiếu trường nào thì không được tính đủ 12đ của checklist item C4-1 (đánh giá theo mức độ đầy đủ của biểu mẫu).\",\"source_note\":\"Chuyển thể từ ràng buộc gốc trong checklist C4, không thay đổi điểm/nội dung rubric.\"}]}","keywords":[],"weight":20,"maxScore":20}]'::jsonb, '{"position_id":"IT-02","position_name":"Software Tester / QA (Chuyên viên Kiểm thử / Đảm bảo Chất lượng)","level":"Fresher/Junior","time_limit_minutes":45,"context":"Một ứng dụng đặt đồ ăn vừa phát triển xong tính năng \"Giỏ hàng & Thanh toán\". Trong vòng test nội bộ, đội QA ghi nhận 2 lỗi sau: Lỗi 1 - Sai tổng tiền: Giỏ hàng 2 ly trà sữa (35.000đ/ly) + phí giao hàng 15.000đ. Khách nhập mã giảm giá SALE20 (giảm 20% trên tổng đơn hàng, không áp dụng cho phí ship). Hệ thống hiển thị tổng thanh toán = 68.000đ (số đúng phải là (70.000 × 0,8) + 15.000 = 71.000đ). Lỗi 2 - Đơn hàng bị trùng: Khách bấm nút \"Đặt hàng\" lúc mạng chập chờn (loading xoay hơn 3 giây). Khách bấm thêm lần 2 vì tưởng chưa nhận. Sau đó vào mục \"Đơn hàng của tôi\" thấy xuất hiện 2 đơn giống hệt nhau, cùng bị trừ tiền 2 lần trong lịch sử giao dịch.","requirements":["Viết 2 Bug Report theo mẫu chuẩn cho 2 lỗi đã mô tả, mỗi report gồm: Tiêu đề, Các bước tái hiện, Kết quả mong đợi, Kết quả thực tế, Mức độ nghiêm trọng, Đề xuất hướng xử lý."],"rubric":[{"criterion_id":"C1","criterion_name":"Độ chính xác trong mô tả lỗi","max_points":30,"checklist":[{"text":"Bug 1: tính đúng số tiền kỳ vọng (70.000 × 0,8 + 15.000 = 71.000đ) và chỉ rõ nguyên nhân là mã giảm giá bị áp dụng nhầm luôn cho phí ship","points":15,"checklist_id":"IT-02-C1-1","scoring_source":"ai"},{"text":"Bug 2: mô tả đúng nguyên nhân khả dĩ (double-click/timeout khi mạng chập chờn khiến gọi API đặt hàng 2 lần) và hệ quả bị trừ tiền 2 lần","points":15,"checklist_id":"IT-02-C1-2","scoring_source":"ai"}]},{"criterion_id":"C2","criterion_name":"Chất lượng các bước tái hiện lỗi (Steps to Reproduce)","max_points":25,"checklist":[{"text":"Các bước được viết tuần tự, rõ ràng, người khác có thể làm theo để tái hiện đúng lỗi, không bỏ sót điều kiện tiên quyết (VD: áp mã SALE20; điều kiện mạng chập chờn) cho cả 2 report","points":25,"checklist_id":"IT-02-C2-1","scoring_source":"ai"}]},{"criterion_id":"C3","criterion_name":"Đánh giá Mức độ nghiêm trọng (Severity) và Đề xuất hướng xử lý","max_points":25,"checklist":[{"text":"Đánh giá đúng mức độ nghiêm trọng phù hợp bản chất lỗi (cả 2 lỗi liên quan trực tiếp giao dịch tài chính nên cần xếp mức Nghiêm trọng/Critical-High, có giải thích lý do)","points":15,"checklist_id":"IT-02-C3-1","scoring_source":"ai"},{"text":"Đề xuất hướng xử lý hợp lý cho từng lỗi (VD: sửa logic tính giảm giá loại trừ phí ship; thêm cơ chế chống double-submit/idempotency key khi đặt hàng)","points":10,"checklist_id":"IT-02-C3-2","scoring_source":"ai"}]},{"criterion_id":"C4","criterion_name":"Trình bày đúng mẫu Bug Report và thời gian","max_points":20,"checklist":[{"text":"Mỗi report có đủ 5 trường bắt buộc (Tiêu đề, Các bước tái hiện, Kết quả mong đợi, Kết quả thực tế, Mức độ nghiêm trọng) và Đề xuất hướng xử lý","points":12,"checklist_id":"IT-02-C4-1","scoring_source":"ai"},{"text":"Tiêu đề report ngắn gọn, nêu được bản chất lỗi; hoàn thành đúng thời gian (45 phút)","points":8,"checklist_id":"IT-02-C4-2","scoring_source":"hybrid","scoring_source_note":"Phần \"hoàn thành đúng thời gian\" trong ý này do HỆ THỐNG tự động xác định dựa trên time_limit_minutes và actual_duration_seconds (xem time_scoring_rule); phần nội dung còn lại của ý này vẫn do AI đánh giá như checklist gốc."}]}],"hard_constraints":[{"constraint_id":"IT-02-HC1","type":"required_elements","trigger_checklist_id":"IT-02-C4-1","condition":"Mỗi Bug Report phải có đủ 5 trường bắt buộc: Tiêu đề, Các bước tái hiện, Kết quả mong đợi, Kết quả thực tế, Mức độ nghiêm trọng (và Đề xuất hướng xử lý).","effect":"Thiếu trường nào thì không được tính đủ 12đ của checklist item C4-1 (đánh giá theo mức độ đầy đủ của biểu mẫu).","source_note":"Chuyển thể từ ràng buộc gốc trong checklist C4, không thay đổi điểm/nội dung rubric."}],"artifacts":{}}'::jsonb)
