 và doanh thu theo tháng (Tháng 5-8) của 4 chi nhánh (Q1, Q3, Bình Thạnh, Thủ Đức), có ghi chú chương trình khuyến mãi \"mua 1 tặng 1\" tại Bình Thạnh trong tuần đầu tháng 7.","required":true,"mapping_note":"File thực tế của đề thi sẽ được hệ thống map vào task này theo position_id; không tự tạo dữ liệu mẫu."}],"hard_constraints":[],"artifacts":{"IT-03-DATA-01":{"artifact_id":"IT-03-DATA-01","position_id":"IT-03","company":"Chuỗi cà phê Mobile Order","period":"Tháng 5 đến Tháng 8 (4 tháng gần nhất)","branches_data":[{"branch_id":"Q1","branch_name":"Chi nhánh Quận 1","promotions":"Không có chương trình khuyến mãi riêng","monthly_metrics":[{"month":"Tháng 5","orders":420,"revenue_million_vnd":21},{"month":"Tháng 6","orders":460,"revenue_million_vnd":23},{"month":"Tháng 7","orders":510,"revenue_million_vnd":25.5},{"month":"Tháng 8","orders":560,"revenue_million_vnd":28}],"growth_rate_mom":["+9.52%","+10.87%","+9.80%"],"total_growth":"+33.33%"},{"branch_id":"Q3","branch_name":"Chi nhánh Quận 3","promotions":"Không có chương trình khuyến mãi riêng","monthly_metrics":[{"month":"Tháng 5","orders":380,"revenue_million_vnd":19},{"month":"Tháng 6","orders":400,"revenue_million_vnd":20},{"month":"Tháng 7","orders":390,"revenue_million_vnd":19.5},{"month":"Tháng 8","orders":405,"revenue_million_vnd":20.3}],"growth_rate_mom":["+5.26%","-2.50%","+4.10%"],"total_growth":"+6.84%"},{"branch_id":"BINH_THANH","branch_name":"Chi nhánh Bình Thạnh","promotions":"Khuyến mãi ''Mua 1 tặng 1'' trong tuần đầu Tháng 7 (Outlier)","monthly_metrics":[{"month":"Tháng 5","orders":300,"revenue_million_vnd":15},{"month":"Tháng 6","orders":340,"revenue_million_vnd":17},{"month":"Tháng 7","orders":400,"revenue_million_vnd":20},{"month":"Tháng 8","orders":470,"revenue_million_vnd":23.5}],"growth_rate_mom":["+13.33%","+17.65%","+17.50%"],"total_growth":"+56.67%"},{"branch_id":"THU_DUC","branch_name":"Chi nhánh Thủ Đức","promotions":"Không có chương trình khuyến mãi riêng","monthly_metrics":[{"month":"Thá