insert into public.simulations (id, slug, industry, position_title, brief, task_instructions, estimated_minutes, min_words, position_id, is_available, unavailable_reason, rubric, grading_rubric, reference_data)
values ('ee458aec-a264-5191-9180-aa56cd3ad80d', 'r2w-kk-03', 'Kế toán - Kiểm toán', 'Trợ Lý Thuế (Tax Assistant)', 'Bạn là Tư vấn viên thuế (Tax Assistant) đang làm việc với khách hàng là Công ty TNHH Một thành viên Gamma (do 1 cá nhân làm chủ, đồng thời là Giám đốc trực tiếp điều hành công ty). Kế toán của Gamma vừa gửi Bảng cân đối tài khoản năm 2026. Lợi nhuận kế toán trước thuế (LNKTTT) hiện đang là 5.000.000.000 VNĐ. Trong quá trình rà soát Sổ cái các tài khoản chi phí (TK 641, 642, 811), phát hiện các khoản chi sau đã được kế toán trừ hết vào chi phí trong kỳ: (1) Chi phí đồng phục bằng tiền mặt cho 100 nhân viên: 600.000.000 VNĐ (bình quân 6 triệu/người/năm); (2) Chi phí phạt vi phạm hợp đồng kinh tế (giao hàng chậm cho đối tác): 150.000.000 VNĐ; (3) Chi phí phạt vi phạm hành chính (chậm nộp tờ khai thuế GTGT và lấn chiếm lòng lề đường): 35.000.000 VNĐ; (4) Tiền lương và Bảo hiểm của Giám đốc (chủ sở hữu Công ty TNHH 1 thành viên): 480.000.000 VNĐ/năm; (5) Chi tài trợ cho phường xây dựng nhà văn hóa khu phố: 50.000.000 VNĐ (có biên bản xác nhận của UBND Phường).', '## Bối cảnh

Bạn là Tư vấn viên thuế (Tax Assistant) đang làm việc với khách hàng là Công ty TNHH Một thành viên Gamma (do 1 cá nhân làm chủ, đồng thời là Giám đốc trực tiếp điều hành công ty). Kế toán của Gamma vừa gửi Bảng cân đối tài khoản năm 2026. Lợi nhuận kế toán trước thuế (LNKTTT) hiện đang là 5.000.000.000 VNĐ. Trong quá trình rà soát Sổ cái các tài khoản chi phí (TK 641, 642, 811), phát hiện các khoản chi sau đã được kế toán trừ hết vào chi phí trong kỳ: (1) Chi phí đồng phục bằng tiền mặt cho 100 nhân viên: 600.000.000 VNĐ (bình quân 6 triệu/người/năm); (2) Chi phí phạt vi phạm hợp đồng kinh tế (giao hàng chậm cho đối tác): 150.000.000 VNĐ; (3) Chi phí phạt vi phạm hành chính (chậm nộp tờ khai thuế GTGT và lấn chiếm lòng lề đường): 35.000.000 VNĐ; (4) Tiền lương và Bảo hiểm của Giám đốc (chủ sở hữu Công ty TNHH 1 thành viên): 480.000.000 VNĐ/năm; (5) Chi tài trợ cho phường xây dựng nhà văn hóa khu phố: 50.000.000 VNĐ (có biên bản xác nhận của UBND Phường).

## Yêu cầu nhiệm vụ

1. Rà soát loại trừ chi phí: phân tích từng khoản chi (từ 1 đến 5); khoản nào được tính là Chi phí hợp lý (Deductible), khoản nào Không hợp lý (Non-deductible)? Giải thích căn cứ pháp lý ngắn gọn dựa trên Thông tư 78/2014/TT-BTC & 96/2015/TT-BTC.

2. Tính Thuế TNDN: tính tổng các khoản điều chỉnh tăng (chỉ tiêu B4) và xác định Thuế TNDN phải nộp năm 2026, biết thuế suất Thuế TNDN là 20% và công ty không có khoản lỗ kết chuyển hay ưu đãi thuế.', 60, 120, 'KK-03', true, null, '[{"id":"C1","label":"Rà soát Chi phí 1 — Đồng phục bằng tiền mặt","weight":10,"maxScore":10},{"id":"C2","label":"Rà soát Chi phí 2 — Phạt vi phạm hợp đồng kinh tế","weight":10,"maxScore":10},{"id":"C3","label":"Rà soát Chi phí 3 — Phạt vi phạm hành chính","weight":10,"maxScore":10},{"id":"C4","label":"Rà soát Chi phí 4 — Tiền lương Chủ DNTN/Chủ công ty TNHH 1 thành viên","weight":20,"maxScore":20},{"id":"C5","label":"Rà soát Chi phí 5 — Tài trợ địa phương","weight":10,"maxScore":10},{"id":"C6","label":"Tổng hợp & Tính Thuế TNDN","weight":40,"maxScore":40}]'::jsonb, '[{"id":"C1","label":"Rà soát Chi phí 1 — Đồng phục bằng tiền mặt","description":"{\"checklist\":[{\"text\":\"Nhận định đúng: luật quy định tối đa 5 triệu/người/năm. Khoản không hợp lý (B4) = (6tr - 5tr) × 100 người = 100.000.000 VNĐ\",\"points\":10,\"checklist_id\":\"KK-03-C1-1\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":10,"maxScore":10},{"id":"C2","label":"Rà soát Chi phí 2 — Phạt vi phạm hợp đồng kinh tế","description":"{\"checklist\":[{\"text\":\"Nhận định đúng: được tính vào chi phí hợp lệ (hoặc bù trừ với thu nhập phạt hợp đồng); không bị loại (0 VNĐ)\",\"points\":10,\"checklist_id\":\"KK-03-C2-1\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":10,"maxScore":10},{"id":"C3","label":"Rà soát Chi phí 3 — Phạt vi phạm hành chính","description":"{\"checklist\":[{\"text\":\"Nhận định đúng: phạt vi phạm hành chính, luật pháp KHÔNG được tính vào chi phí hợp lệ. Khoản không hợp lý (B4) = 35.000.000 VNĐ\",\"points\":10,\"checklist_id\":\"KK-03-C3-1\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":10,"maxScore":10},{"id":"C4","label":"Rà soát Chi phí 4 — Tiền lương Chủ DNTN/Chủ công ty TNHH 1 thành viên","description":"{\"checklist\":[{\"text\":\"Nhận định đúng: tiền lương của chủ DNTN/chủ công ty TNHH 1 thành viên (dù có tham gia điều hành) KHÔNG được tính vào chi phí hợp lệ. Khoản không hợp lý (B4) = 480.000.000 VNĐ. Đây là lỗi rất nhiều kế toán mới ra trường mắc phải — cần chấm nghiêm mục này\",\"points\":20,\"checklist_id\":\"KK-03-C4-1\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":20,"maxScore":20},{"id":"C5","label":"Rà soát Chi phí 5 — Tài trợ địa phương","description":"{\"checklist\":[{\"text\":\"Nhận định đúng: tài trợ không thuộc diện tài trợ Y tế, Giáo dục, Xây nhà tình nghĩa, Khắc phục thiên tai theo quy định nên KHÔNG được tính vào chi phí hợp lý. Khoản không hợp lý (B4) = 50.000.000 VNĐ\",\"points\":10,\"checklist_id\":\"KK-03-C5-1\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":10,"maxScore":10},{"id":"C6","label":"Tổng hợp & Tính Thuế TNDN","description":"{\"checklist\":[{\"text\":\"Tính đúng Tổng chi phí bị loại (chỉ tiêu B4) = 100M + 35M + 480M + 50M = 665.000.000 VNĐ\",\"points\":20,\"checklist_id\":\"KK-03-C6-1\",\"scoring_source\":\"ai\"},{\"text\":\"Thu nhập tính thuế = LNKTTT + B4 = 5.000M + 665M = 5.665.000.000 VNĐ\",\"points\":10,\"checklist_id\":\"KK-03-C6-2\",\"scoring_source\":\"ai\"},{\"text\":\"Thuế TNDN phải nộp = 5.665M × 20% = 1.133.000.000 VNĐ\",\"points\":10,\"checklist_id\":\"KK-03-C6-3\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":40,"maxScore":40}]'::jsonb, '{"position_id":"KK-03","position_name":"Trợ Lý Thuế (Tax Assistant)","level":"Fresher/Junior","time_limit_minutes":60,"context":"Bạn là Tư vấn viên thuế (Tax Assistant) đang làm việc với khách hàng là Công ty TNHH Một thành viên Gamma (do 1 cá nhân làm chủ, đồng thời là Giám đốc trực tiếp điều hành công ty). Kế toán của Gamma vừa gửi Bảng cân đối tài khoản năm 2026. Lợi nhuận kế toán trước thuế (LNKTTT) hiện đang là 5.000.000.000 VNĐ. Trong quá trình rà soát Sổ cái các tài khoản chi phí (TK 641, 642, 811), phát hiện các khoản chi sau đã được kế toán trừ hết vào chi phí trong kỳ: (1) Chi phí đồng phục bằng tiền mặt cho 100 nhân viên: 600.000.000 VNĐ (bình quân 6 triệu/người/năm); (2) Chi phí phạt vi phạm hợp đồng kinh tế (giao hàng chậm cho đối tác): 150.000.000 VNĐ; (3) Chi phí phạt vi phạm hành chính (chậm nộp tờ khai thuế GTGT và lấn chiếm lòng lề đường): 35.000.000 VNĐ; (4) Tiền lương và Bảo hiểm của Giám đốc (chủ sở hữu Công ty TNHH 1 thành viên): 480.000.000 VNĐ/năm; (5) Chi tài trợ cho phường xây dựng nhà văn hóa khu phố: 50.000.000 VNĐ (có biên bản xác nhận của UBND Phường).","requirements":["Rà soát loại trừ chi phí: phân tích từng khoản chi (từ 1 đến 5); khoản nào được tính là Chi phí hợp lý (Deductible), khoản nào Không hợp lý (Non-deductible)? Giải thích căn cứ pháp lý ngắn gọn dựa trên Thông tư 78/2014/TT-BTC & 96/2015/TT-BTC.","Tính Thuế TNDN: tính tổng các khoản điều chỉnh tăng (chỉ tiêu B4) và xác định Thuế TNDN phải nộp năm 2026, biết thuế suất Thuế TNDN là 20% và công ty không có khoản lỗ kết chuyển hay ưu đãi thuế."],"public_display_note":"Đối với B2C, giao diện chỉ hiện các tên mục in đậm (criterion_name) và số điểm (max_points), ẩn phần checklist chi tiết bên dưới.","rubric":[{"criterion_id":"C1","criterion_name":"Rà soát Chi phí 1 — Đồng phục bằng tiền mặt","max_points":10,"checklist":[{"text":"Nhận định đúng: luật quy định tối đa 5 triệu/người/năm. Khoản không hợp lý (B4) = (6tr - 5tr) × 100 người = 100.000.000 VNĐ","points":10,"checklist_id":"KK-03-C1-1","scoring_source":"ai"}]},{"criterion_id":"C2","criterion_name":"Rà soát Chi phí 2 — Phạt vi phạm hợp đồng kinh tế","max_points":10,"checklist":[{"text":"Nhận định đúng: được tính vào chi phí hợp lệ (hoặc bù trừ với thu nhập phạt hợp đồng); không bị loại (0 VNĐ)","points":10,"checklist_id":"KK-03-C2-1","scoring_source":"ai"}]},{"criterion_id":"C3","criterion_name":"Rà soát Chi phí 3 — Phạt vi phạm hành chính","max_points":10,"checklist":[{"text":"Nhận định đúng: phạt vi phạm hành chính, luật pháp KHÔNG được tính vào chi phí hợp lệ. Khoản không hợp lý (B4) = 35.000.000 VNĐ","points":10,"checklist_id":"KK-03-C3-1","scoring_source":"ai"}]},{"criterion_id":"C4","criterion_name":"Rà soát Chi phí 4 — Tiền lương Chủ DNTN/Chủ công ty TNHH 1 thành viên","max_points":20,"checklist":[{"text":"Nhận định đúng: tiền lương của chủ DNTN/chủ công ty TNHH 1 thành viên (dù có tham gia điều hành) KHÔNG được tính vào chi phí hợp lệ. Khoản không hợp lý (B4) = 480.000.000 VNĐ. Đây là lỗi rất nhiều kế toán mới ra trường mắc phải — cần chấm nghiêm mục này","points":20,"checklist_id":"KK-03-C4-1","scoring_source":"ai"}]},{"criterion_id":"C5","criterion_name":"Rà soát Chi phí 5 — Tài trợ địa phương","max_points":10,"checklist":[{"text":"Nhận định đúng: tài trợ không thuộc diện tài trợ Y tế, Giáo dục, Xây nhà tình nghĩa, Khắc phục thiên tai theo quy định nên KHÔNG được tính vào chi phí hợp lý. Khoản không hợp lý (B4) = 50.000.000 VNĐ","points":10,"checklist_id":"KK-03-C5-1","scoring_source":"ai"}]},{"criterion_id":"C6","criterion_name":"Tổng hợp & Tính Thuế TNDN","max_points":40,"checklist":[{"text":"Tính đúng Tổng chi phí bị loại (chỉ tiêu B4) = 100M + 35M + 480M + 50M = 665.000.000 VNĐ","points":20,"checklist_id":"KK-03-C6-1","scoring_source":"ai"},{"text":"Thu nhập tính thuế = LNKTTT + B4 = 5.000M + 665M = 5.665.000.000 VNĐ","points":10,"checklist_id":"KK-03-C6-2","scoring_source":"ai"},{"text":"Thuế TNDN phải nộp = 5.665M × 20% = 1.133.000.000 VNĐ","points":10,"checklist_id":"KK-03-C6-3","scoring_source":"ai"}]}],"hard_constraints":[],"artifacts":{}}'::jsonb)
