values ('13d886bc-5629-5770-bc92-6a883144a14f', 'r2w-log-02', 'Logistics', 'Supply Chain Analyst (Chuyên viên Phân tích Chuỗi cung ứng)', 'Bạn là Chuyên viên Phân tích tại công ty. Công ty đang chuẩn bị lập kế hoạch sản xuất mặt hàng "Nước tăng lực lon" cho đợt cao điểm Tết Nguyên Đán. Thời gian giao hàng (Lead-time) bình thường từ nhà máy đến kho phân phối là 7 ngày. Nhưng Giám đốc Vận tải vừa cảnh báo: tháng cận Tết sẽ thiếu xe tải, thời gian giao hàng chậm nhất (Max Lead-time) có thể kéo dài lên tới 11 ngày.', '## Bối cảnh

Bạn là Chuyên viên Phân tích tại công ty. Công ty đang chuẩn bị lập kế hoạch sản xuất mặt hàng "Nước tăng lực lon" cho đợt cao điểm Tết Nguyên Đán. Thời gian giao hàng (Lead-time) bình thường từ nhà máy đến kho phân phối là 7 ngày. Nhưng Giám đốc Vận tải vừa cảnh báo: tháng cận Tết sẽ thiếu xe tải, thời gian giao hàng chậm nhất (Max Lead-time) có thể kéo dài lên tới 11 ngày.

## Yêu cầu nhiệm vụ

1. Xử lý dữ liệu tuần Flash Sale khi tính Average Daily Sales (mức bán trung bình ngày).

2. Đề xuất Mức tồn kho an toàn (Safety Stock).

3. Tính Điểm đặt hàng lại (Reorder Point - ROP) để kho không bị đứt hàng mùa Tết, cũng không bị Over-stock (tồn kho quá mức).

## Dữ liệu đầu vào

### LOG-02-DATA-01

```json
{
  "artifact_id": "LOG-02-DATA-01",
  "position_id": "LOG-02",
  "company": "Công ty FMCG Nước giải khát",
  "product": "Nước tăng lực lon",
  "planning_period": "Cao điểm Tết Nguyên Đán",
  "historical_sales_6_months": {
    "total_days": 180,
    "normal_period_days": 173,
    "flash_sale_week_days": 7,
    "normal_sales_total_units": 86500,
    "flash_sale_week_sales_units": 21000,
    "total_sales_units": 107500,
    "max_daily_sales_normal": 720,
    "min_daily_sales_normal": 350
  },
  "lead_time_parameters": {
    "average_lead_time_days": 7,
    "max_lead_time_days": 11,
    "lead_time_variance_days": 4
  }
}
```', 60, 120, 'LOG-02', true, null, '[{"id":"C1","label":"Xử lý dữ liệu & Lập luận số liệu","weight":40,"maxScore":40},{"id":"C2","label":"Độ chính xác của Công thức","weight":40,"maxScore":40},{"id":"C3","label":"Trình bày báo cáo","weight":20,"maxScore":20}]'::jsonb, '[{"id":"C1","label":"Xử lý dữ liệu & Lập luận số liệu","description":"{\"checklist\":[{\"text\":\"Xác định được tuần \\\"Flash Sale\\\" là dữ liệu nhiễu (outlier) và đề xuất loại bỏ hoặc điều chỉnh dữ liệu tuần này ra khỏi mức tính Average Daily Sales. Nếu lấy trung bình cộng có chứa cả số lượng của đợt Sale → kết quả dự báo bị sai lệch (ảo), dẫn đến ôm hàng quá nhiều → chấm 0 điểm phần lập luận này\",\"points\":40,\"checklist_id\":\"LOG-02-C1-1\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[{\"constraint_id\":\"LOG-02-HC1\",\"type\":\"auto_zero_criterion\",\"trigger_checklist_id\":\"LOG-02-C1-1\",\"condition\":\"Thí sinh tính Average Daily Sales bằng cách lấy trung bình cộng có bao gồm cả số liệu của tuần \\\"Flash Sale\\\" (không loại trừ outlier).\",\"effect\":\"Chấm 0 điểm cho phần lập luận của tiêu chí C1 (Xử lý dữ liệu & Lập luận số liệu), tối đa 40đ của C1 = 0.\",\"source_note\":\"Chuyển thể từ ràng buộc gốc trong checklist C1, không thay đổi điểm/nội dung rubric.\"}]}","keywords":[],"weight":40,"maxScore":40},{"id":"C2","label":"Độ chính xác của Công thức","description":"{\"checklist\":[{\"text\":\"Tính Safety Stock có sử dụng tham số (Max Leadtime - Average Leadtime), tức khoảng trễ 11 - 7 = 4 ngày\",\"points\":20,\"checklist_id\":\"LOG-02-C2-1\",\"scoring_source\":\"ai\"},{\"text\":\"Sử dụng đúng công thức ROP = (Average Leadtime × Average Daily Sales) + Safety Stock\",\"points\":20,\"checklist_id\":\"LOG-02-C2-2\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":40,"maxScore":40},{"id":"C3","label":"Trình bày báo cáo","description":"{\"checklist\":[{\"text\":\"Cấu trúc chuẩn 3 phần: Nhận định Data → Kết quả tính toán → Đề xuất phương án dự phòng (VD: thuê thêm 3PLs để bù đắp việc thiếu xe tải)\",\"points\":20,\"checklist_id\":\"LOG-02-C3-1\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":20,"maxScore":20}]'::jsonb, '{"position_id":"LOG-02","position_name":"Supply Chain Analyst (Chuyên viên Phân tích Chuỗi cung ứng)","level":"Fresher/Junior","time_limit_minutes":60,"context":"Bạn là Chuyên viên Phân tích tại công ty. Công ty đang chuẩn bị lập kế hoạch sản xuất mặt hàng \"Nước tăng lực lon\" cho đợt cao điểm Tết Nguyên Đán. Thời gian giao hàng (Lead-time) bình thường từ nhà máy đến kho phân phối là 7 ngày. Nhưng Giám đốc Vận tải vừa cảnh báo: tháng cận Tết sẽ thiếu xe tải, thời gian giao hàng chậm nhất (Max Lead-time) có thể kéo dài lên tới 11 ngày.","context_data_note":"Dữ liệu lịch sử bán hàng 6 tháng gần nhất được cung cấp qua bảng tính đính kèm riêng theo đề thi; trong dữ liệu có một tuần \"Flash Sale\" (khuyến mãi ngắn hạn) làm tăng đột biến số lượng bán.","requirements":["Xử lý dữ liệu tuần Flash Sale khi tính Average Daily Sales (mức bán trung bình ngày).","Đề xuất Mức tồn kho an toàn (Safety Stock).","Tính Điểm đặt hàng lại (Reorder Point - ROP) để kho không bị đứt hàng mùa Tết, cũng không bị Over-stock (tồn kho quá mức)."],"rubric":[{"criterion_id":"C1","criterion_name":"Xử lý dữ liệu & Lập luận số liệu","max_points":40,"checklist":[{"text":"Xác định được tuần \"Flash Sale\" là dữ liệu nhiễu (outlier) và đề xuất loại bỏ hoặc điều chỉnh dữ liệu tuần này ra khỏi mức tính Average Daily Sales. Nếu lấy trung bình cộng có chứa cả số lượng của đợt Sale → kết quả dự báo bị sai lệch (ảo), dẫn đến ôm hàng quá nhiều → chấm 0 điểm phần lập luận này","points":40,"checklist_id":"LOG-02-C1-1","scoring_source":"ai"}]},{"criterion_id":"C2","criterion_name":"Độ chính xác của Công thức","max_points":40,"checklist":[{"text":"Tính Safety Stock có sử dụng tham số (Max Leadtime - Average Leadtime), tức khoảng trễ 11 - 7 = 4 ngày","points":20,"checklist_id":"LOG-02-C2-1","scoring_source":"ai"},{"text":"Sử dụng đúng công thức ROP = (Average Leadtime × Average Daily Sales) + Safety Stock","points":20,"checklist_id":"LOG-02-C2-2","scoring_source":"ai"}]},{"criterion_id":"C3","criterion_name":"Trình bày báo cáo","max_points":20,"checklist":[{"text":"Cấu trúc chuẩn 3 phần: Nhận định Data → Kết quả tính toán → Đề xuất phương án dự phòng (VD: thuê thêm 3PLs để bù đắp việc thiếu xe tải)","points":20,"checklist_id":"LOG-02-C3-1","scoring_source":"ai"}]}],"input_artifacts":[{"artifact_id":"LOG-02-DATA-01","type":"table_or_excel","description":"Dữ liệu lịch sử bán hàng 6 tháng gần nhất của mặt hàng \"Nước tăng lực lon\", trong đó có 1 tuần \"Flash Sale\" gây tăng đột biến số lượng bán.","required":true,"mapping_note":"File thực tế của đề thi sẽ được hệ thống map vào task này theo position_id; không tự tạo dữ liệu mẫu."}],"hard_constraints":[{"constraint_id":"LOG-02-HC1","type":"auto_zero_criterion","trigger_checklist_id":"LOG-02-C1-1","condition":"Thí sinh tính Average Daily Sales bằng cách lấy trung bình cộng có bao gồm cả số liệu của tuần \"Flash Sale\" (không loại trừ outlier).","effect":"Chấm 0 điểm cho phần lập luận của tiêu chí C1 (Xử lý dữ liệu & Lập luận số liệu), tối đa 40đ của C1 = 0.","source_note":"Chuyển thể từ ràng buộc gốc trong checklist C1, không thay đổi điểm/nội dung rubric."}],"artifacts":{"LOG-02-DATA-01":{"artifact_id":"LOG-02-DATA-01","position_id":"LOG-02","company":"Công ty FMCG Nước giải khát","product":"Nước tăng lực lon","planning_period":"Cao điểm Tết Nguyên Đán","historical_sales_6_months":{"total_days":180,"normal_period_days":173,"flash_sale_week_days":7,"normal_sales_total_units":86500,"flash_sale_week_sales_units":21000,"total_sales_units":107500,"average_daily_sales_with_outlier":597.2,"average_daily_sales_without_outlier":500,"max_daily_sales_normal":720,"min_daily_sales_normal":350},"lead_time_parameters":{"average_lead_time_days":7,"max_lead_time_days":11,"lead_time_variance_days":4},"standard_formula_reference":{"safety_stock_formula":"Safety Stock = (Max Lead Time - Average Lead Time) * Average Daily Sales (without outlier) = (11 - 7) * 500 = 2,000 lon","reorder_point_formula":"ROP = (Average Lead Time * Average Daily Sales) + Safety Stock = (7 * 500) + 2,000 = 5,500 lon","outlier_rule":"Tuần Flash Sale là ngoại lai (Outlier). Nếu không loại bỏ mà lấy số 597 lon/ngày thì Safety Stock và ROP sẽ bị phóng đại ảo dẫn đến tồn kho dư thừa nghiêm trọng sau Tết."}}}}'::jsonb)
