insert into public.simulations (id, slug, industry, position_title, brief, task_instructions, estimated_minutes, min_words, position_id, is_available, unavailable_reason, rubric, grading_rubric, reference_data)
values ('b41fec44-4dbd-52e9-81d2-908714770e53', 'r2w-log-03', 'Logistics', 'Procurement / Purchasing Executive (Chuyên viên Thu mua)', 'Nhà máy sản xuất bao bì VN đang cần nhập khẩu 50 tấn hạt nhựa LLDPE để chạy đơn hàng cho đối tác. Kho nhà máy báo cáo: tồn kho hiện tại chỉ còn đủ chạy máy trong đúng 7 ngày. Nếu quá 7 ngày không có hạt nhựa, máy phải dừng hoạt động, thiệt hại ước tính 100 triệu VNĐ/ngày. Đồng thời, Phòng Tài chính thông báo: công ty đang kẹt dòng tiền mặt nghiêm trọng, trong 30 ngày tới không có ngân sách thanh toán ngay cho nhà cung cấp (chờ đối tác trả nợ). Có 3 báo giá: NCC A (Trung Quốc) — giá 1.000 USD/tấn, Lead-time 30 ngày, thanh toán T/T 100% ứng trước. NCC B (Thái Lan) — giá 1.100 USD/tấn, Lead-time 15 ngày, thanh toán L/C trả chậm 30 ngày (sau 30 ngày từ khi nhận hàng mới phải trả tiền). NCC C (Việt Nam - Công ty Thương mại) — giá 1.300 USD/tấn (đắt nhất), Lead-time 3 ngày, thanh toán Công nợ (Net 60 ngày).', '## Bối cảnh

Nhà máy sản xuất bao bì VN đang cần nhập khẩu 50 tấn hạt nhựa LLDPE để chạy đơn hàng cho đối tác. Kho nhà máy báo cáo: tồn kho hiện tại chỉ còn đủ chạy máy trong đúng 7 ngày. Nếu quá 7 ngày không có hạt nhựa, máy phải dừng hoạt động, thiệt hại ước tính 100 triệu VNĐ/ngày. Đồng thời, Phòng Tài chính thông báo: công ty đang kẹt dòng tiền mặt nghiêm trọng, trong 30 ngày tới không có ngân sách thanh toán ngay cho nhà cung cấp (chờ đối tác trả nợ). Có 3 báo giá: NCC A (Trung Quốc) — giá 1.000 USD/tấn, Lead-time 30 ngày, thanh toán T/T 100% ứng trước. NCC B (Thái Lan) — giá 1.100 USD/tấn, Lead-time 15 ngày, thanh toán L/C trả chậm 30 ngày (sau 30 ngày từ khi nhận hàng mới phải trả tiền). NCC C (Việt Nam - Công ty Thương mại) — giá 1.300 USD/tấn (đắt nhất), Lead-time 3 ngày, thanh toán Công nợ (Net 60 ngày).

## Yêu cầu nhiệm vụ

1. Lập bảng so sánh 3 nhà cung cấp dựa trên 3 tiêu chí: Giá, Thời gian giao hàng (Lead-time), Dòng tiền (điều khoản thanh toán).

2. Đưa ra quyết định mua 50 tấn hạt nhựa này như thế nào để tối ưu nhất cho công ty (không dừng máy & không vi phạm dòng tiền).', 60, 120, 'LOG-03', true, null, '[{"id":"C1","label":"Độ chính xác trong loại trừ phương án không khả thi","weight":30,"maxScore":30},{"id":"C2","label":"Phân tích & Xử lý sâu vấn đề","weight":50,"maxScore":50},{"id":"C3","label":"Trình bày mạch lạc","weight":20,"maxScore":20}]'::jsonb, '[{"id":"C1","label":"Độ chính xác trong loại trừ phương án không khả thi","description":"{\"checklist\":[{\"text\":\"Loại ngay lập tức phương án mua toàn bộ từ NCC A. Lý do: vi phạm nghiêm trọng về Lead-time (30 ngày hàng mới về → nhà máy dừng máy 23 ngày → phạt 2,3 tỷ VNĐ) và vi phạm dòng tiền (bắt trả T/T 100% ngay trong khi công ty đang kẹt tiền mặt). Nếu ứng viên chọn NCC A → bài thi bị 0 điểm toàn bộ\",\"points\":30,\"checklist_id\":\"LOG-03-C1-1\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[{\"constraint_id\":\"LOG-03-HC1\",\"type\":\"auto_zero_task\",\"trigger_checklist_id\":\"LOG-03-C1-1\",\"condition\":\"Thí sinh chọn phương án mua toàn bộ 50 tấn hạt nhựa từ NCC A (vi phạm nghiêm trọng cả Lead-time lẫn dòng tiền).\",\"effect\":\"total_score = 0 cho TOÀN BỘ bài thi (áp dụng cho mọi tiêu chí, ghi đè mọi điểm số khác đã tính).\",\"source_note\":\"Chuyển thể từ ràng buộc gốc trong checklist C1: ''Nếu ứng viên chọn NCC A → bài thi bị 0 điểm toàn bộ''. Không thay đổi điểm/nội dung rubric.\"}]}","keywords":[],"weight":30,"maxScore":30},{"id":"C2","label":"Phân tích & Xử lý sâu vấn đề","description":"{\"checklist\":[{\"text\":\"Nếu chọn mua toàn bộ từ NCC C: không bị dừng máy, tốt cho dòng tiền, nhưng giá quá đắt (mất thêm 10.000 USD chi phí so với NCC B) → đạt 20/50đ\",\"points\":20,\"checklist_id\":\"LOG-03-C2-1\",\"scoring_source\":\"ai\"},{\"text\":\"Nếu đưa ra chiến lược Split-Order (chia nhỏ đơn hàng): mua 10-15 tấn từ NCC C (Việt Nam) để giao trong 3 ngày giúp nhà máy có hàng chạy ngay, thanh toán Net 60 khớp yêu cầu kế toán; đồng thời đặt 35-40 tấn còn lại từ NCC B (Thái Lan) — giá rẻ hơn, 15 ngày sau hàng về khớp đúng lúc dùng hết hàng của NCC C, thanh toán L/C trả chậm cũng không vi phạm dòng tiền hiện tại → đạt 50/50đ tuyệt đối\",\"points\":30,\"checklist_id\":\"LOG-03-C2-2\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":50,"maxScore":50},{"id":"C3","label":"Trình bày mạch lạc","description":"{\"checklist\":[{\"text\":\"Có kẻ bảng (matrix) so sánh Tổng chi phí sở hữu (Total Cost of Ownership), tính cả rủi ro dừng máy 100 triệu/ngày vào bài toán so sánh giá; lập luận sắc bén, thuyết phục\",\"points\":20,\"checklist_id\":\"LOG-03-C3-1\",\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":20,"maxScore":20}]'::jsonb, '{"position_id":"LOG-03","position_name":"Procurement / Purchasing Executive (Chuyên viên Thu mua)","level":"Fresher/Junior","time_limit_minutes":60,"context":"Nhà máy sản xuất bao bì VN đang cần nhập khẩu 50 tấn hạt nhựa LLDPE để chạy đơn hàng cho đối tác. Kho nhà máy báo cáo: tồn kho hiện tại chỉ còn đủ chạy máy trong đúng 7 ngày. Nếu quá 7 ngày không có hạt nhựa, máy phải dừng hoạt động, thiệt hại ước tính 100 triệu VNĐ/ngày. Đồng thời, Phòng Tài chính thông báo: công ty đang kẹt dòng tiền mặt nghiêm trọng, trong 30 ngày tới không có ngân sách thanh toán ngay cho nhà cung cấp (chờ đối tác trả nợ). Có 3 báo giá: NCC A (Trung Quốc) — giá 1.000 USD/tấn, Lead-time 30 ngày, thanh toán T/T 100% ứng trước. NCC B (Thái Lan) — giá 1.100 USD/tấn, Lead-time 15 ngày, thanh toán L/C trả chậm 30 ngày (sau 30 ngày từ khi nhận hàng mới phải trả tiền). NCC C (Việt Nam - Công ty Thương mại) — giá 1.300 USD/tấn (đắt nhất), Lead-time 3 ngày, thanh toán Công nợ (Net 60 ngày).","requirements":["Lập bảng so sánh 3 nhà cung cấp dựa trên 3 tiêu chí: Giá, Thời gian giao hàng (Lead-time), Dòng tiền (điều khoản thanh toán).","Đưa ra quyết định mua 50 tấn hạt nhựa này như thế nào để tối ưu nhất cho công ty (không dừng máy & không vi phạm dòng tiền)."],"rubric":[{"criterion_id":"C1","criterion_name":"Độ chính xác trong loại trừ phương án không khả thi","max_points":30,"checklist":[{"text":"Loại ngay lập tức phương án mua toàn bộ từ NCC A. Lý do: vi phạm nghiêm trọng về Lead-time (30 ngày hàng mới về → nhà máy dừng máy 23 ngày → phạt 2,3 tỷ VNĐ) và vi phạm dòng tiền (bắt trả T/T 100% ngay trong khi công ty đang kẹt tiền mặt). Nếu ứng viên chọn NCC A → bài thi bị 0 điểm toàn bộ","points":30,"checklist_id":"LOG-03-C1-1","scoring_source":"ai"}]},{"criterion_id":"C2","criterion_name":"Phân tích & Xử lý sâu vấn đề","max_points":50,"checklist":[{"text":"Nếu chọn mua toàn bộ từ NCC C: không bị dừng máy, tốt cho dòng tiền, nhưng giá quá đắt (mất thêm 10.000 USD chi phí so với NCC B) → đạt 20/50đ","points":20,"checklist_id":"LOG-03-C2-1","scoring_source":"ai"},{"text":"Nếu đưa ra chiến lược Split-Order (chia nhỏ đơn hàng): mua 10-15 tấn từ NCC C (Việt Nam) để giao trong 3 ngày giúp nhà máy có hàng chạy ngay, thanh toán Net 60 khớp yêu cầu kế toán; đồng thời đặt 35-40 tấn còn lại từ NCC B (Thái Lan) — giá rẻ hơn, 15 ngày sau hàng về khớp đúng lúc dùng hết hàng của NCC C, thanh toán L/C trả chậm cũng không vi phạm dòng tiền hiện tại → đạt 50/50đ tuyệt đối","points":30,"checklist_id":"LOG-03-C2-2","scoring_source":"ai"}]},{"criterion_id":"C3","criterion_name":"Trình bày mạch lạc","max_points":20,"checklist":[{"text":"Có kẻ bảng (matrix) so sánh Tổng chi phí sở hữu (Total Cost of Ownership), tính cả rủi ro dừng máy 100 triệu/ngày vào bài toán so sánh giá; lập luận sắc bén, thuyết phục","points":20,"checklist_id":"LOG-03-C3-1","scoring_source":"ai"}]}],"hard_constraints":[{"constraint_id":"LOG-03-HC1","type":"auto_zero_task","trigger_checklist_id":"LOG-03-C1-1","condition":"Thí sinh chọn phương án mua toàn bộ 50 tấn hạt nhựa từ NCC A (vi phạm nghiêm trọng cả Lead-time lẫn dòng tiền).","effect":"total_score = 0 cho TOÀN BỘ bài thi (áp dụng cho mọi tiêu chí, ghi đè mọi điểm số khác đã tính).","source_note":"Chuyển thể từ ràng buộc gốc trong checklist C1: ''Nếu ứng viên chọn NCC A → bài thi bị 0 điểm toàn bộ''. Không thay đổi điểm/nội dung rubric."}],"artifacts":{}}'::jsonb)
