values ('1ba735e2-6e89-5080-bf3c-43d29ba84d59', (select id from public.interview_sets where slug = 'r2w-business-analyst'), 1, 'Giới thiệu bản thân và lý do bạn muốn theo đuổi vị trí Business Analyst', '', '{}'::text[], 1, 30, '[{"id":"criterion_1","label":"Nền tảng chuyên môn liên quan","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do chọn nghề đúng bản chất","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Nền tảng chuyên môn liên quan","description":"Nêu cụ thể ngành học/dự án đã làm liên quan trực tiếp đến phân tích nghiệp vụ, không nói chung chung.","keywords":[],"weight":12,"maxScore":12,"skill":"Requirement Analysis"},{"id":"criterion_2","label":"Lý do chọn nghề đúng bản chất","description":"Phải chỉ ra đúng đặc thù công việc Business Analyst là phân tích vấn đề kinh doanh và làm cầu nối với đội kỹ thuật.","keywords":[],"weight":10,"maxScore":10,"skill":"Problem Solving"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Trình bày mạch lạc, có dùng một số thuật ngữ cơ bản (yêu cầu nghiệp vụ/requirement, stakeholder).","keywords":[],"weight":8,"maxScore":8,"skill":"Communication"}]'::jsonb, 'Nêu cụ thể ngành học/dự án đã làm liên quan trực tiếp đến phân tích nghiệp vụ; chỉ ra đúng đặc thù công việc BA là phân tích vấn đề kinh doanh và làm cầu nối với đội kỹ thuật; trình bày mạch lạc, sử dụng thuật ngữ yêu cầu nghiệp vụ, stakeholder.')
