  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('fedc1c97-c678-5bb8-8f33-c2b7e9f3f5e2', (select id from public.interview_sets where slug = 'r2w-business-analyst'), 2, 'Bạn hiểu vai trò của một Business Analyst trong dự án phần mềm là gì?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Xác định đúng vai trò cầu nối","weight":15,"maxScore":15},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Xác định đúng vai trò cầu nối","description":"Nêu rõ BA là người trung gian giữa khách hàng/doanh nghiệp và đội phát triển, không lẫn với PM hay Dev.","keywords":[],"weight":15,"maxScore":15,"skill":"Stakeholder Management"},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","description":"Nêu tối thiểu 3/5 đầu việc: thu thập yêu cầu, phân tích nghiệp vụ, viết tài liệu đặc tả (BRD/SRS), kiểm soát phạm vi (scope), hỗ trợ nghiệm thu (UAT).","keywords":[],"weight":12,"maxScore":12,"skill":"Requirement Analysis"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Dùng đúng thuật ngữ: Requirement, Stakeholder, Scope, UAT, BRD/SRS.","keywords":[],"weight":8,"maxScore":8,"skill":"Communication"}]'::jsonb, 'BA là người trung gian giữa khách hàng/doanh nghiệp và đội phát triển; các đầu việc cốt lõi gồm thu thập yêu cầu, phân tích nghiệp vụ, viết tài liệu đặc tả (BRD/SRS), kiểm soát phạm vi (scope) và hỗ trợ nghiệm thu (UAT).')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('8189e487-3522-57fa-9e69-ded7cb639328', (select id from public.interview_sets where slug = 'r2w-business-analyst'), 3, 'Bạn đã từng tham gia dự án/bài tập nào liên quan đến phân tích nghiệp vụ chưa?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","weight":15,"maxScore":15},{"id":"criterion_2","label":"Trình bày theo STAR","weight":12,"maxScore":12},{"id":"criterion_3","label":"Rút ra bài học cụ thể","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","description":"Nêu tên/bối cảnh dự án hoặc bài tập cụ thể, vai trò đảm nhận rõ ràng.","keywords":[],"weight":15,"maxScore":15,"skill":"Domain Modeling"},{"id":"criterion_2","label":"Trình bày theo STAR","description":"Bối cảnh (Situation) → Nhiệm vụ (Task) → Hành động cụ thể (Action) → Kết quả đo lường được (Result).","keywords":[],"weight":12,"maxScore":12,"skill":"Communication"},{"id":"criterion_3","label":"Rút ra bài học cụ thể","description":"Chỉ ra được 1 bài học nghiệp vụ cụ thể, ví dụ: ''phải xác nhận lại yêu cầu bằng văn bản trước khi triển khai''.","keywords":[],"weight":8,"maxScore":8,"skill":"Problem Solving"}]'::jsonb, 'Nêu tên/bối cảnh dự án phần mềm cụ thể theo mô hình STAR; chỉ rõ các bước phỏng vấn người dùng, vẽ wireframe hoặc viết use case và bài học nghiệp vụ rút ra.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('e0e97e9e-b616-5f77-a639-39a15bb254f3', (select id from public.interview_sets where slug = 'r2w-business-analyst'), 4, 'Phân biệt yêu cầu chức năng (Functional) và phi chức năng (Non-functional), cho ví dụ', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Định nghĩa đúng Functional Requirement","weight":15,"maxScore":15},{"id":"criterion_2","label":"Định nghĩa đúng Non-functional Requirement","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Định nghĩa đúng Functional Requirement","description":"Là yêu cầu mô tả HỆ THỐNG LÀM GÌ, kèm ví dụ cụ thể không chung chung.","keywords":[],"weight":15,"maxScore":15,"skill":"Requirement Analysis"},{"id":"criterion_2","label":"Định nghĩa đúng Non-functional Requirement","description":"Là yêu cầu mô tả hệ thống VẬN HÀNH TỐT ĐẾN MỨC NÀO (hiệu năng, bảo mật, khả dụng), kèm số liệu cụ thể.","keywords":[],"weight":12,"maxScore":12,"skill":"Domain Modeling"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Dùng đúng các thuật ngữ Functional/Non-functional Requirement, Performance, Security, Availability.","keywords":[],"weight":8,"maxScore":8,"skill":"Communication"}]'::jsonb, 'Functional Requirement là yêu cầu mô tả hệ thống làm gì (chức năng, tính năng, hành vi), ví dụ: cho phép người dùng đăng nhập bằng Google hoặc gửi email OTP. Non-functional Requirement là yêu cầu mô tả hệ thống vận hành tốt đến mức nào (hiệu năng, bảo mật, khả dụng), ví dụ: hệ thống đáp ứng 1.000 request/giây với thời gian phản hồi dưới 200ms.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('5213a138-7269-54fa-8b36-e245e15f50fa', (select id from public.interview_sets where slug = 'r2w-business-analyst'), 5, 'Bạn sẽ dùng phương pháp nào để thu thập yêu cầu từ khách hàng (phỏng vấn, workshop, khảo sát...)?', '', '{}'::text[], 2, 30, '[{"id":"criterion_1","label":"Khi nào dùng Phỏng vấn 1-1","weight":15,"maxScore":15},{"id":"criterion_2","label":"Khi nào dùng Workshop","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":3,"maxScore":3}]'::jsonb, '[{"id":"criterion_1","label":"Khi nào dùng Phỏng vấn 1-1","description":"Dùng khi cần đào sâu nghiệp vụ với người có chuyên môn cao, hoặc chủ đề nhạy cảm cần trao đổi riêng.","keywords":[],"weight":15,"maxScore":15,"skill":"Requirement Analysis"},{"id":"criterion_2","label":"Khi nào dùng Workshop","description":"Dùng khi có nhiều stakeholder với quan điểm khác nhau cần thống nhất trong cùng buổi họp để tránh yêu cầu mâu thuẫn.","keywords":[],"weight":12,"maxScore":12,"skill":"Stakeholder Management"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Dùng đúng các thuật ngữ Stakeholder, Workshop, Elicitation (khai thác yêu cầu).","keywords":[],"weight":3,"maxScore":3,"skill":"Communication"}]'::jsonb, 'Tùy thuộc vào bối cảnh: Phỏng vấn 1-1 khi cần đào sâu quy trình chuyên môn với chuyên gia hoặc chủ đề nhạy cảm; Workshop khi có nhiều bên liên quan (stakeholders) với quan điểm trái ngược cần ngồi lại để thống nhất; Khảo sát (Survey) khi cần thu thập phản hồi từ số lượng lớn người dùng cuối.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('6d6e4636-61f8-5e54-af61-f737a6bd9e9f', (select id from public.interview_sets where slug = 'r2w-business-analyst'), 6, 'Trình bày các thành phần chính trong một tài liệu SRS/BRD', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Liệt kê đủ thành phần cốt lõi","weight":18,"maxScore":18},{"id":"criterion_2","label":"Giải thích Acceptance Criteria","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đủ thành phần cốt lõi","description":"Nêu tối thiểu 4/5: mục tiêu & phạm vi, yêu cầu chức năng chi tiết, yêu cầu phi chức năng, ràng buộc/giả định, tiêu chí nghiệm thu (acceptance criteria).","keywords":[],"weight":18,"maxScore":18,"skill":"Domain Modeling"},{"id":"criterion_2","label":"Giải thích Acceptance Criteria","description":"Nêu được đây là căn cứ để xác nhận sản phẩm đạt yêu cầu trước khi khách hàng nghiệm thu UAT.","keywords":[],"weight":10,"maxScore":10,"skill":"Requirement Analysis"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Dùng đúng các thuật ngữ SRS, BRD, Acceptance Criteria, Constraint.","keywords":[],"weight":7,"maxScore":7,"skill":"Communication"}]'::jsonb, 'Một tài liệu đặc tả chuẩn gồm: 1) Mục tiêu & Phạm vi dự án (Scope); 2) Mô tả người dùng & Stakeholder; 3) Yêu cầu chức năng chi tiết (Use case, User stories); 4) Yêu cầu phi chức năng (Performance, Security); 5) Ràng buộc & Giả định; 6) Tiêu chí nghiệm thu (Acceptance Criteria) làm căn cứ bàn giao UAT.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('d49801e6-3cb0-5e97-8b5c-12b2c118e262', (select id from public.interview_sets where slug = 'r2w-business-analyst'), 7, 'Khách hàng liên tục thay đổi yêu cầu giữa dự án, bạn xử lý thế nào?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Quy trình Change Request chính thức","weight":20,"maxScore":20},{"id":"criterion_2","label":"Đánh giá tác động (Impact Analysis)","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Quy trình Change Request chính thức","description":"Không phản đối/chấp nhận cảm tính, đề xuất ghi nhận yêu cầu bằng văn bản qua quy trình Change Request.","keywords":[],"weight":20,"maxScore":20,"skill":"Stakeholder Management"},{"id":"criterion_2","label":"Đánh giá tác động (Impact Analysis)","description":"Đánh giá impact lên scope, thời gian, chi phí trước khi quyết định, phối hợp với PM và Dev.","keywords":[],"weight":20,"maxScore":20,"skill":"Problem Solving"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Dùng đúng các thuật ngữ Change Request, Scope Creep, Impact Analysis.","keywords":[],"weight":10,"maxScore":10,"skill":"Requirement Analysis"}]'::jsonb, 'Không phản đối hay chấp nhận theo cảm tính; ghi nhận yêu cầu mới bằng văn bản và áp dụng quy trình Quản lý thay đổi (Change Request); thực hiện phân tích tác động (Impact Analysis) lên phạm vi (scope), tiến độ và ngân sách dự án; trình bày các phương án để khách hàng và PM cùng quyết định đánh đổi.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

