values ('7505add1-e09a-59f3-8e51-306710e86db7', (select id from public.interview_sets where slug = 'r2w-business-analyst'), 8, 'Đội Dev và khách hàng bất đồng về một yêu cầu, là Business Analyst bạn sẽ làm gì?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Trung gian dựa trên tài liệu gốc","weight":20,"maxScore":20},{"id":"criterion_2","label":"Giải pháp cụ thể để thống nhất","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Trung gian dựa trên tài liệu gốc","description":"Đề xuất quay lại tài liệu yêu cầu đã ký duyệt để làm rõ ý định ban đầu, không thiên vị cảm tính.","keywords":[],"weight":20,"maxScore":20,"skill":"Stakeholder Management"},{"id":"criterion_2","label":"Giải pháp cụ thể để thống nhất","description":"Tổ chức họp ba bên hoặc làm prototype/wireframe để minh hoạ trực quan giúp cả hai bên hình dung.","keywords":[],"weight":20,"maxScore":20,"skill":"Problem Solving"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Dùng đúng các thuật ngữ Traceability, Prototype, Sign-off.","keywords":[],"weight":10,"maxScore":10,"skill":"Communication"}]'::jsonb, 'Đóng vai trò trung gian khách quan dựa trên tài liệu yêu cầu (SRS/BRD) đã được hai bên ký duyệt (Sign-off); tổ chức cuộc họp 3 bên để làm rõ bản chất khúc mắc; sử dụng wireframe, prototype hoặc user story để trực quan hóa giải pháp trung hòa, tránh tranh cãi suông.')
on conflict (set_id, position) do update set
