insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('31de923d-3ca3-571d-9742-0f30e848dfde', (select id from public.interview_sets where slug = 'r2w-credit-analyst'), 2, 'Bạn hiểu vai trò của một Credit Analyst là gì?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Xác định đúng vai trò","weight":15,"maxScore":15},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Xác định đúng vai trò","description":"Nêu rõ Credit Analyst là người phân tích thông tin tài chính và phi tài chính của khách hàng để hỗ trợ quyết định cấp tín dụng của ngân hàng.","keywords":[],"weight":15,"maxScore":15,"skill":"Credit Analysis"},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","description":"Nêu tối thiểu 3/5 nội dung: phân tích BCTC, đánh giá dòng tiền, lịch sử tín dụng, khả năng trả nợ, xác định rủi ro tín dụng.","keywords":[],"weight":12,"maxScore":12,"skill":"Repayment Capacity"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Dùng đúng thuật ngữ: Credit Assessment, Cash Flow, Debt Service, Collateral, Credit Risk.","keywords":[],"weight":8,"maxScore":8,"skill":"Credit Risk"}]'::jsonb, 'Credit Analyst là người phân tích thông tin tài chính và phi tài chính của khách hàng để hỗ trợ Hội đồng tín dụng ra quyết định cấp tín dụng; các đầu việc cốt lõi gồm phân tích BCTC, đánh giá dòng tiền, lịch sử tín dụng (CIC), khả năng trả nợ và xác định rủi ro tín dụng.')
