insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('ff934cd9-01ec-5e46-9e11-ed6f87a15781', (select id from public.interview_sets where slug = 'r2w-credit-analyst'), 3, 'Bạn đã từng tham gia dự án/bài tập nào liên quan đến phân tích tài chính chưa?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","weight":15,"maxScore":15},{"id":"criterion_2","label":"Trình bày theo cấu trúc STAR","weight":12,"maxScore":12},{"id":"criterion_3","label":"Rút ra bài học cụ thể","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","description":"Không trả lời “chưa có kinh nghiệm” chung chung - phải nêu tên/bối cảnh dự án hoặc bài tập cụ thể, vai trò đảm nhận rõ ràng.","keywords":[],"weight":15,"maxScore":15,"skill":"Financial Analysis"},{"id":"criterion_2","label":"Trình bày theo cấu trúc STAR","description":"Bối cảnh (Situation) → Nhiệm vụ (Task) → Hành động cụ thể (Action) → Kết quả đo lường được (Result).","keywords":[],"weight":12,"maxScore":12,"skill":"Credit Analysis"},{"id":"criterion_3","label":"Rút ra bài học cụ thể","description":"Chỉ ra được 1 bài học nghiệp vụ cụ thể khi thẩm định tài chính.","keywords":[],"weight":8,"maxScore":8,"skill":"Risk Mitigation"}]'::jsonb, 'Nêu dự án/bài tập thẩm định tín dụng cụ thể theo cấu trúc STAR (Situation -> Task -> Action -> Result); nêu rõ phương pháp phân tích chỉ số, đánh giá dòng tiền và rút ra bài học kinh nghiệm.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('80e7df52-d618-56f5-a4d1-7e4ef03fb878', (select id from public.interview_sets where slug = 'r2w-credit-analyst'), 4, 'Khi phân tích khả năng trả nợ của một doanh nghiệp, bạn sẽ xem xét những chỉ tiêu nào ?', '', '{}'::text[], 2, 30, '[{"id":"criterion_1","label":"Nhóm chỉ tiêu chính","weight":15,"maxScore":15},{"id":"criterion_2","label":"Liên hệ khả năng trả nợ","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng chuyên ngành","weight":3,"maxScore":3}]'::jsonb, '[{"id":"criterion_1","label":"Nhóm chỉ tiêu chính","description":"Nêu được các nhóm chỉ tiêu chính: thanh khoản, đòn bẩy, khả năng sinh lời, dòng tiền.","keywords":[],"weight":15,"maxScore":15,"skill":"Financial Analysis"},{"id":"criterion_2","label":"Liên hệ khả năng trả nợ","description":"Biết liên hệ chỉ tiêu với khả năng trả nợ thực tế thay vì chỉ đọc số liệu thuần túy.","keywords":[],"weight":12,"maxScore":12,"skill":"Repayment Capacity"},{"id":"criterion_3","label":"Từ vựng chuyên ngành","description":"Dùng đúng các thuật ngữ Liquidity, Leverage, Profitability, Cash Flow.","keywords":[],"weight":3,"maxScore":3,"skill":"Credit Analysis"}]'::jsonb, 'Xem xét các nhóm chỉ tiêu: Thanh khoản (Current Ratio, Quick Ratio), Đòn bẩy tài chính (Debt/Equity, Debt/EBITDA), Khả năng thanh toán lãi vay và nợ gốc (ICR, DSCR), và Dòng tiền hoạt động kinh doanh (CFO); biết liên hệ số liệu với chu kỳ kinh doanh thực tế.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('067b09e2-f00e-5619-826e-2da985aae6a7', (select id from public.interview_sets where slug = 'r2w-credit-analyst'), 5, 'Trình bày quy trình thẩm định tín dụng một khách hàng doanh nghiệp', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Liệt kê đúng các bước","weight":15,"maxScore":15},{"id":"criterion_2","label":"Giải thích mục đích từng bước","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng chuyên môn","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đúng các bước","description":"Thu thập hồ sơ → phân tích tài chính/phi tài chính → đánh giá tài sản bảo đảm → xếp hạng tín dụng → đề xuất cấp tín dụng → giám sát sau vay.","keywords":[],"weight":15,"maxScore":15,"skill":"Credit Analysis"},{"id":"criterion_2","label":"Giải thích mục đích từng bước","description":"Nêu rõ mỗi bước nhằm đánh giá khả năng trả nợ, mức độ rủi ro và điều kiện cấp tín dụng.","keywords":[],"weight":12,"maxScore":12,"skill":"Credit Risk"},{"id":"criterion_3","label":"Từ vựng chuyên môn","description":"Dùng đúng thuật ngữ: Credit Appraisal, Due Diligence, Credit Rating, Covenant.","keywords":[],"weight":8,"maxScore":8,"skill":"Risk Mitigation"}]'::jsonb, 'Quy trình chuẩn gồm: Thu thập hồ sơ -> Thẩm định tư cách pháp lý & uy tín -> Phân tích tài chính & dòng tiền -> Đánh giá phương án kinh doanh -> Định giá tài sản bảo đảm -> Xếp hạng tín dụng & Đề xuất điều kiện cấp tín dụng -> Quản lý, giám sát sau cho vay.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('7d8e1570-7c44-53e9-b502-275640118a01', (select id from public.interview_sets where slug = 'r2w-credit-analyst'), 6, 'Làm thế nào để đánh giá tài sản bảo đảm và tỷ lệ LTV?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Định nghĩa đúng LTV","weight":18,"maxScore":18},{"id":"criterion_2","label":"Quy trình định giá và pháp lý","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng chuyên ngành","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Định nghĩa đúng LTV","description":"LTV là tỷ lệ dư nợ trên giá trị tài sản bảo đảm; ảnh hưởng trực tiếp đến hạn mức cho vay.","keywords":[],"weight":18,"maxScore":18,"skill":"Credit Analysis"},{"id":"criterion_2","label":"Quy trình định giá và pháp lý","description":"Kiểm tra pháp lý, định giá độc lập, đánh giá tính thanh khoản của tài sản.","keywords":[],"weight":10,"maxScore":10,"skill":"Risk Mitigation"},{"id":"criterion_3","label":"Từ vựng chuyên ngành","description":"Dùng đúng thuật ngữ: Collateral, LTV, Valuation, Liquidity.","keywords":[],"weight":7,"maxScore":7,"skill":"Financial Analysis"}]'::jsonb, 'LTV (Loan to Value) là tỷ lệ giữa khoản dư nợ vay và giá trị định giá của tài sản bảo đảm; cần kiểm tra tính pháp lý của tài sản, thuê định giá độc lập, đánh giá tính thanh khoản của tài sản khi xử lý nợ; quy định tỷ lệ LTV phù hợp với từng loại tài sản (BĐS 70-80%, máy móc 40-50%).')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('f915aaa3-e25b-51d8-b34d-0077c4a548b9', (select id from public.interview_sets where slug = 'r2w-credit-analyst'), 7, 'Khách hàng có tài sản bảo đảm tốt nhưng dòng tiền yếu, bạn có đề xuất cho vay không?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Đánh giá dòng tiền là cốt lõi","weight":20,"maxScore":20},{"id":"criterion_2","label":"Phương án giảm thiểu rủi ro","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng chuyên ngành","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Đánh giá dòng tiền là cốt lõi","description":"Không chỉ dựa vào tài sản bảo đảm; phân tích dòng tiền, nguồn trả nợ chính.","keywords":[],"weight":20,"maxScore":20,"skill":"Repayment Capacity"},{"id":"criterion_2","label":"Phương án giảm thiểu rủi ro","description":"Giảm hạn mức, tăng tài sản bảo đảm, thêm điều kiện covenant, giám sát chặt dòng tiền.","keywords":[],"weight":20,"maxScore":20,"skill":"Risk Mitigation"},{"id":"criterion_3","label":"Từ vựng chuyên ngành","description":"Dùng đúng thuật ngữ: DSCR, Covenant, Collateral, Risk Mitigation.","keywords":[],"weight":10,"maxScore":10,"skill":"Credit Risk"}]'::jsonb, 'Nguyên tắc cốt lõi: Nguồn trả nợ chính phải đến từ dòng tiền hoạt động SXKD của khách hàng, tài sản bảo đảm chỉ là nguồn thu hồi nợ thứ cấp khi rủi ro xảy ra; do đó không thể duyệt khoản vay chỉ dựa vào TSBĐ; nếu muốn cho vay cần giảm hạn mức, kiểm soát chặt dòng tiền, tăng điều kiện covenant.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('b1d84eed-c019-5491-8992-210a143b7191', (select id from public.interview_sets where slug = 'r2w-credit-analyst'), 8, 'Cấp trên yêu cầu bạn nhanh chóng phê duyệt một khoản vay lớn nhưng hồ sơ tài chính còn thiếu thông tin. Bạn xử lý thế nào?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Tuân thủ nguyên tắc rủi ro","weight":20,"maxScore":20},{"id":"criterion_2","label":"Giải pháp xử lý khẩn cấp","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Tuân thủ nguyên tắc rủi ro","description":"Không chấp nhận phê duyệt cảm tính khi thiếu thông tin trọng yếu, giữ tính độc lập của KTV/Analyst.","keywords":[],"weight":20,"maxScore":20,"skill":"Credit Risk"},{"id":"criterion_2","label":"Giải pháp xử lý khẩn cấp","description":"Lập danh sách thông tin trọng yếu cần bổ sung ngay và trao đổi minh bạch với cấp trên.","keywords":[],"weight":20,"maxScore":20,"skill":"Risk Mitigation"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Dùng đúng các thuật ngữ: Credit Risk, Due Diligence, Approval Condition, Risk Tolerance.","keywords":[],"weight":10,"maxScore":10,"skill":"Credit Analysis"}]'::jsonb, 'Giữ vững nguyên tắc quản trị rủi ro độc lập; thẳng thắn giải trình với cấp trên về những lỗ hổng thông tin và rủi ro tiềm ẩn nếu phê duyệt nóng; chủ động lập danh mục thông tin tối thiểu cần bổ sung gấp trong ngày để khách hàng cung cấp trước khi trình ký có điều kiện.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
