values ('77e051a1-4da8-59a5-903d-9f3e04d14f8b', (select id from public.interview_sets where slug = 'r2w-data-analyst'), 1, 'Giới thiệu bản thân và vì sao bạn theo đuổi Data Analyst', '', '{}'::text[], 1, 30, '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","weight":14,"maxScore":14},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","weight":11,"maxScore":11},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","description":"Nêu ngành học/dự án cụ thể có liên quan đến xử lý số liệu, không nói chung chung.","keywords":[],"weight":14,"maxScore":14,"skill":"Data Analysis"},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","description":"Chỉ ra đặc thù công việc là tìm insight từ dữ liệu để hỗ trợ ra quyết định kinh doanh.","keywords":[],"weight":11,"maxScore":11,"skill":"Data Storytelling"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Chia sẻ được về Insight, Data-driven decision.","keywords":[],"weight":5,"maxScore":5,"skill":"Data Analysis"}]'::jsonb, 'Nêu ngành học/dự án cụ thể liên quan đến xử lý số liệu; chỉ ra đúng đặc thù nghề DA là tìm kiếm insight từ dữ liệu để giải quyết bài toán kinh doanh và hỗ trợ ra quyết định; không nhầm với Data Engineer (hạ tầng dữ liệu) hay Data Scientist (xây thuật toán ML).')
