values ('a7544021-89e7-500f-a579-0d661371062c', (select id from public.interview_sets where slug = 'r2w-data-analyst'), 2, 'Quy trình phân tích dữ liệu cơ bản gồm những bước nào?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Liệt kê đúng thứ tự các bước","weight":20,"maxScore":20},{"id":"criterion_2","label":"Vai trò bước làm sạch dữ liệu","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đúng thứ tự các bước","description":"Thu thập → làm sạch → phân tích → trực quan hoá → kết luận/đề xuất.","keywords":[],"weight":20,"maxScore":20,"skill":"Data Analysis"},{"id":"criterion_2","label":"Vai trò bước làm sạch dữ liệu","description":"Nhấn mạnh Data Cleaning là bước quan trọng nhất quyết định độ tin cậy của toàn bộ phân tích.","keywords":[],"weight":10,"maxScore":10,"skill":"Data Cleaning"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Dùng đúng các thuật ngữ Data Cleaning, Data Visualization, Insight.","keywords":[],"weight":5,"maxScore":5,"skill":"Data Visualization"}]'::jsonb, 'Quy trình chuẩn: 1) Xác định bài toán kinh doanh -> 2) Thu thập dữ liệu (Extract/Query SQL) -> 3) Làm sạch & tiền xử lý dữ liệu (Data Cleaning) -> 4) Phân tích khám phá (EDA) -> 5) Trực quan hóa dữ liệu (Visualization) -> 6) Kể chuyện dữ liệu & Đề xuất hành động kinh doanh (Data Storytelling).')
on conflict (set_id, position) do update set
