insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('0f252ac5-0591-5a33-bfce-4c952054c12c', (select id from public.interview_sets where slug = 'r2w-data-analyst'), 3, 'Bạn thành thạo công cụ nào (Excel, SQL, Power BI, Python...)?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Nêu công cụ kèm mục đích rõ ràng","weight":18,"maxScore":18},{"id":"criterion_2","label":"Ví dụ thực tế áp dụng","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Tên hàm cụ thể","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Nêu công cụ kèm mục đích rõ ràng","description":"SQL để truy vấn database, Excel/Power BI để xử lý và trực quan hoá - có giải thích mục đích rõ ràng.","keywords":[],"weight":18,"maxScore":18,"skill":"SQL"},{"id":"criterion_2","label":"Ví dụ thực tế áp dụng","description":"Mô tả một tình huống thực tế đã dùng công cụ đó để giải quyết vấn đề gì, kết quả ra sao.","keywords":[],"weight":10,"maxScore":10,"skill":"Data Analysis"},{"id":"criterion_3","label":"Từ vựng & Tên hàm cụ thể","description":"Dùng đúng tên công cụ/hàm cụ thể: Pivot Table, VLOOKUP, JOIN, GROUP BY.","keywords":[],"weight":7,"maxScore":7,"skill":"SQL"}]'::jsonb, 'Nêu công cụ gắn liền với mục đích sử dụng: SQL để trích xuất và biến đổi dữ liệu từ RDBMS; Excel/Power BI để mô hình hóa và xây dựng Dashboard trực quan; Python để phân tích chuyên sâu hoặc tự động hóa; kèm ví dụ bài tập thực tế.')
