insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('e04d99eb-6f44-5d57-a819-48d1b4bd2e2b', (select id from public.interview_sets where slug = 'r2w-data-analyst'), 4, 'Hãy viết câu SQL JOIN 2 bảng để lấy dữ liệu theo điều kiện cho trước', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Cú pháp SQL chuẩn xác","weight":20,"maxScore":20},{"id":"criterion_2","label":"Chọn đúng loại JOIN","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng chuyên ngành","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Cú pháp SQL chuẩn xác","description":"Câu lệnh đúng cú pháp chuẩn (SELECT...FROM...JOIN...ON...WHERE), không lỗi cú pháp cơ bản.","keywords":[],"weight":20,"maxScore":20,"skill":"SQL"},{"id":"criterion_2","label":"Chọn đúng loại JOIN","description":"Giải thích được vì sao chọn loại JOIN đó (ví dụ INNER JOIN vì chỉ cần dữ liệu khớp cả hai bảng).","keywords":[],"weight":10,"maxScore":10,"skill":"SQL"},{"id":"criterion_3","label":"Từ vựng chuyên ngành","description":"Gọi đúng tên các mệnh đề SQL: SELECT, FROM, JOIN, ON, WHERE.","keywords":[],"weight":5,"maxScore":5,"skill":"SQL"}]'::jsonb, 'Cú pháp chuẩn: SELECT a.id, a.name, b.order_date, b.total_amount FROM Customers a INNER JOIN Orders b ON a.id = b.customer_id WHERE b.total_amount > 1000000; giải thích lý do dùng INNER JOIN là để chỉ lấy các khách hàng thực sự đã phát sinh đơn hàng.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('207d512b-baf9-52be-a782-c0cda47bb5ff', (select id from public.interview_sets where slug = 'r2w-data-analyst'), 5, 'Bạn hãy phân biệt các loại JOIN (INNER, LEFT, RIGHT, FULL)', '', '{}'::text[], 2, 30, '[{"id":"criterion_1","label":"Bản chất INNER và LEFT JOIN","weight":15,"maxScore":15},{"id":"criterion_2","label":"Ví dụ kinh doanh thực tế","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Tên 4 loại JOIN","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Bản chất INNER và LEFT JOIN","description":"INNER JOIN chỉ lấy dữ liệu khớp ở cả hai bảng; LEFT JOIN lấy toàn bộ bảng trái kèm dữ liệu khớp bên phải.","keywords":[],"weight":15,"maxScore":15,"skill":"SQL"},{"id":"criterion_2","label":"Ví dụ kinh doanh thực tế","description":"Ví dụ dùng LEFT JOIN để lấy tất cả khách hàng kể cả người chưa từng mua hàng (WHERE b.id IS NULL).","keywords":[],"weight":10,"maxScore":10,"skill":"Data Analysis"},{"id":"criterion_3","label":"Từ vựng & Tên 4 loại JOIN","description":"Dùng đúng tên bốn loại JOIN bằng tiếng Anh.","keywords":[],"weight":5,"maxScore":5,"skill":"SQL"}]'::jsonb, 'INNER JOIN: Chỉ lấy bản ghi khớp ở cả 2 bảng. LEFT JOIN: Lấy toàn bộ bảng trái và các bản ghi khớp ở bảng phải (không khớp thì NULL). RIGHT JOIN: Lấy toàn bộ bảng phải và bản ghi khớp ở bảng trái. FULL OUTER JOIN: Lấy toàn bộ bản ghi của cả 2 bảng. Ví dụ dùng LEFT JOIN để tìm khách hàng chưa từng mua hàng.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('d4b3b9f9-41df-5b92-9e2d-aadc82e8ecee', (select id from public.interview_sets where slug = 'r2w-data-analyst'), 6, 'Hãy chỉ ra cách xử lý dữ liệu missing/outlier trong tập dữ liệu', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Xử lý dữ liệu thiếu (Missing Data)","weight":18,"maxScore":18},{"id":"criterion_2","label":"Phát hiện và xử lý Outlier","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Thuật ngữ","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Xử lý dữ liệu thiếu (Missing Data)","description":"Tỉ lệ thiếu lớn cân nhắc loại bỏ; tỷ lệ thiếu nhỏ và quan trọng thì điền giá trị thay thế (mean/median/mode).","keywords":[],"weight":18,"maxScore":18,"skill":"Data Cleaning"},{"id":"criterion_2","label":"Phát hiện và xử lý Outlier","description":"Dùng Boxplot hoặc IQR để phát hiện, và cân nhắc bối cảnh nghiệp vụ trước khi loại bỏ.","keywords":[],"weight":10,"maxScore":10,"skill":"Data Cleaning"},{"id":"criterion_3","label":"Từ vựng & Thuật ngữ","description":"Dùng đúng các thuật ngữ Missing Data, Outlier, IQR, Mean/Median/Mode.","keywords":[],"weight":7,"maxScore":7,"skill":"Data Analysis"}]'::jsonb, 'Xử lý Missing Data: Nếu tỷ lệ thiếu cao (>50%) và không quan trọng -> Xóa cột/dòng; nếu quan trọng -> Điền giá trị thay thế (Mean/Median nếu phân phối chuẩn/lệch, Mode cho biến định danh, hoặc Forward Fill). Xử lý Outlier: Nhận diện bằng Boxplot hoặc khoảng IQR (Q1 - 1.5*IQR đến Q3 + 1.5*IQR); kiểm tra xem outlier là lỗi nhập liệu hay biến động tự nhiên trước khi xóa hoặc capping.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('1a153414-7c89-53a5-b8b2-a089fcf302c9', (select id from public.interview_sets where slug = 'r2w-data-analyst'), 7, 'Cấp trên yêu cầu báo cáo insight nhưng dữ liệu bị thiếu/không sạch, bạn sẽ làm gì?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Xử lý dữ liệu trước khi báo cáo","weight":20,"maxScore":20},{"id":"criterion_2","label":"Minh bạch về độ tin cậy kết quả","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng chuyên môn","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Xử lý dữ liệu trước khi báo cáo","description":"Đề xuất làm sạch/bổ sung nguồn dữ liệu trước khi phân tích, không báo cáo ngay trên dữ liệu thô chưa xử lý.","keywords":[],"weight":20,"maxScore":20,"skill":"Data Cleaning"},{"id":"criterion_2","label":"Minh bạch về độ tin cậy kết quả","description":"Báo cáo trung thực với sếp về giới hạn/độ tin cậy của số liệu, không che giấu hạn chế của dữ liệu.","keywords":[],"weight":20,"maxScore":20,"skill":"Data Storytelling"},{"id":"criterion_3","label":"Từ vựng chuyên môn","description":"Dùng đúng các thuật ngữ Data Quality, Confidence Level, Data Cleaning.","keywords":[],"weight":10,"maxScore":10,"skill":"Data Analysis"}]'::jsonb, 'Thực hiện làm sạch và xử lý dữ liệu trước khi phân tích, tuyệt đối không chạy báo cáo trên dữ liệu thô bị lỗi; thông báo trung thực với sếp về chất lượng dữ liệu hiện tại, nêu rõ giới hạn tin cậy (Confidence Level) của phân tích và những vùng dữ liệu cần thận trọng khi ra quyết định.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('8d72da81-163f-560e-8449-277ded946b19', (select id from public.interview_sets where slug = 'r2w-data-analyst'), 8, 'Sau khi phân tích xong, bạn phát hiện ra kết quả phân tích trái với kỳ vọng của cấp trên, bạn sẽ trình bày thế nào?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Giữ nguyên kết quả khách quan","weight":20,"maxScore":20},{"id":"criterion_2","label":"Chiến lược truyền đạt thuyết phục","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Giữ nguyên kết quả khách quan","description":"Khẳng định không điều chỉnh số liệu để vừa ý cấp trên, trình bày đúng như dữ liệu thể hiện.","keywords":[],"weight":20,"maxScore":20,"skill":"Data Storytelling"},{"id":"criterion_2","label":"Chiến lược truyền đạt thuyết phục","description":"Đề xuất dùng biểu đồ trực quan và giải thích rõ phương pháp phân tích để sếp hiểu và tin tưởng kết quả.","keywords":[],"weight":20,"maxScore":20,"skill":"Data Visualization"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Dùng đúng các thuật ngữ Data Integrity, Data Storytelling, Objective.","keywords":[],"weight":10,"maxScore":10,"skill":"Data Analysis"}]'::jsonb, 'Giữ vững tính trung thực và liêm chính dữ liệu (Data Integrity), không tự ý uốn nắn số liệu để chiều lòng sếp; chuẩn bị biểu đồ trực quan, giải thích rõ phương pháp luận phân tích và dữ liệu thực chứng; mở đầu bằng việc công nhận kỳ vọng ban đầu, sau đó dẫn dắt bằng câu chuyện dữ liệu khách quan và đề xuất góc nhìn giải pháp mới.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('190f7cf7-7172-5015-bf4f-cc75f60c5f7a', (select id from public.interview_sets where slug = 'r2w-digital-marketing'), 1, 'Hãy chia sẻ về một chiến dịch Digital Marketing bạn từng tối ưu thành công hoặc một sự cố chết tài khoản Ads/lỗi Tracking mà bạn đã giải quyết.', '', '{}'::text[], 1, 20, '[{"id":"criterion_1","label":"Tình huống thực tế & con số","weight":4,"maxScore":4},{"id":"criterion_2","label":"Phân tích nguyên nhân kỹ thuật","weight":4,"maxScore":4},{"id":"criterion_3","label":"Hành động xử lý dứt điểm","weight":5,"maxScore":5},{"id":"criterion_4","label":"Kết quả đo lường được","weight":4,"maxScore":4},{"id":"criterion_5","label":"Bài học kinh nghiệm","weight":3,"maxScore":3}]'::jsonb, '[{"id":"criterion_1","label":"Tình huống thực tế & con số","description":"Tình huống thực tế, con số minh họa rõ ràng (CPL, ROAS, tỷ lệ chuyển đổi).","keywords":[],"weight":4,"maxScore":4,"skill":"Performance Marketing"},{"id":"criterion_2","label":"Phân tích nguyên nhân kỹ thuật","description":"Khả năng bình tĩnh & phân tích nguyên nhân kỹ thuật (Tracking, Pixel, Audience Overlap).","keywords":[],"weight":4,"maxScore":4,"skill":"Data Analysis"},{"id":"criterion_3","label":"Hành động xử lý dứt điểm","description":"Hành động xử lý dứt điểm, đúng chuyên môn Digital Marketing.","keywords":[],"weight":5,"maxScore":5,"skill":"Performance Marketing"},{"id":"criterion_4","label":"Kết quả đo lường được","description":"Kết quả đo lường được bằng số liệu định lượng cụ thể.","keywords":[],"weight":4,"maxScore":4,"skill":"Budget Optimization"},{"id":"criterion_5","label":"Bài học kinh nghiệm","description":"Bài học rút ra cho các chiến dịch tương lai.","keywords":[],"weight":3,"maxScore":3,"skill":"Multi-channel Management"}]'::jsonb, 'Nêu bối cảnh sự cố/mục tiêu chiến dịch -> Phân tích dữ liệu tìm ra nguyên nhân gốc rễ (nghiệm thu Pixel, lỗi CVR trên trang đích, Ad Fatigue) -> Các hành động kỹ thuật can thiệp -> Kết quả đo lường cụ thể (CPL giảm %, ROAS tăng) -> Bài học rút ra cho các chiến dịch sau.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('72219849-92ba-5dbe-af93-54388b5dcd97', (select id from public.interview_sets where slug = 'r2w-digital-marketing'), 2, 'Bạn sẽ thực hiện những bước nào để phân tích và tìm nguyên nhân khi một chiến dịch quảng cáo Facebook/Google bị sụt giảm hiệu quả nghiêm trọng (CPL tăng gấp đôi)?', '', '{}'::text[], 2, 20, '[{"id":"criterion_1","label":"Rà soát tần suất & đối tượng","weight":4,"maxScore":4},{"id":"criterion_2","label":"Phân tích chỉ số sáng tạo","weight":4,"maxScore":4},{"id":"criterion_3","label":"Kiểm tra chuyển đổi Landing Page","weight":4,"maxScore":4},{"id":"criterion_4","label":"Yếu tố kỹ thuật & thuật toán","weight":4,"maxScore":4},{"id":"criterion_5","label":"Trình bày logic, có quy trình","weight":4,"maxScore":4}]'::jsonb, '[{"id":"criterion_1","label":"Rà soát tần suất & đối tượng","description":"Rà soát chỉ số tần suất & đối tượng (Frequency/Audience Overlap).","keywords":[],"weight":4,"maxScore":4,"skill":"Data Analysis"},{"id":"criterion_2","label":"Phân tích chỉ số sáng tạo","description":"Phân tích chỉ số sáng tạo (CTR/CPC).","keywords":[],"weight":4,"maxScore":4,"skill":"Performance Marketing"},{"id":"criterion_3","label":"Kiểm tra chuyển đổi Landing Page","description":"Kiểm tra tỷ lệ chuyển đổi Landing Page (CR).","keywords":[],"weight":4,"maxScore":4,"skill":"A/B Testing"},{"id":"criterion_4","label":"Yếu tố kỹ thuật & thuật toán","description":"Đánh giá yếu tố kỹ thuật & thuật toán kênh quảng cáo.","keywords":[],"weight":4,"maxScore":4,"skill":"Performance Marketing"},{"id":"criterion_5","label":"Trình bày logic, có quy trình","description":"Trình bày có quy trình, logic, giải thích rõ ràng.","keywords":[],"weight":4,"maxScore":4,"skill":"Data Analysis"}]'::jsonb, 'Em sẽ rà soát từ tổng quan đến chi tiết: Kiểm tra xem tệp đối tượng có bị trùng lặp (Audience Overlap) hoặc quá bão hòa (Ad Fatigue - Tần suất Frequency quá cao) không. Sau đó kiểm tra chỉ số CTR và CPC để đánh giá chất lượng Content/Creative. Tiếp theo là kiểm tra Tỷ lệ chuyển đổi (CR) trên Landing Page để xem lỗi do Ads hay do trang đích. Cuối cùng, em kiểm tra các yếu tố bên ngoài như biến động thị trường hoặc thuật toán kênh.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('efa28043-0479-566a-bde1-18fd21a134db', (select id from public.interview_sets where slug = 'r2w-digital-marketing'), 3, 'Bạn hãy mô tả quy trình thực hiện một chiến dịch A/B Testing cho quảng cáo.', '', '{}'::text[], 2, 20, '[{"id":"criterion_1","label":"Xác định 1 biến độc lập duy nhất","weight":4,"maxScore":4},{"id":"criterion_2","label":"Phân bổ ngân sách & thời gian","weight":4,"maxScore":4},{"id":"criterion_3","label":"Đo lường ý nghĩa thống kê","weight":4,"maxScore":4},{"id":"criterion_4","label":"Quyết định Scale up hợp lý","weight":4,"maxScore":4},{"id":"criterion_5","label":"Quy trình chuẩn khoa học","weight":4,"maxScore":4}]'::jsonb, '[{"id":"criterion_1","label":"Xác định 1 biến độc lập duy nhất","description":"Xác định biến độc lập duy nhất khi test (Creative, Copy, Audience).","keywords":[],"weight":4,"maxScore":4,"skill":"A/B Testing"},{"id":"criterion_2","label":"Phân bổ ngân sách & thời gian","description":"Phân bổ ngân sách & thời gian thử nghiệm công bằng giữa các nhóm.","keywords":[],"weight":4,"maxScore":4,"skill":"Budget Optimization"},{"id":"criterion_3","label":"Đo lường ý nghĩa thống kê","description":"Đo lường dựa trên ý nghĩa thống kê (Statistical Significance) và KPI cốt lõi.","keywords":[],"weight":4,"maxScore":4,"skill":"Data Analysis"},{"id":"criterion_4","label":"Quyết định Scale up hợp lý","description":"Đưa ra quyết định Scale up ngân sách cho phương án chiến thắng.","keywords":[],"weight":4,"maxScore":4,"skill":"Performance Marketing"},{"id":"criterion_5","label":"Quy trình chuẩn khoa học","description":"Trình bày quy trình chuẩn khoa học, bài bản.","keywords":[],"weight":4,"maxScore":4,"skill":"A/B Testing"}]'::jsonb, 'Đầu tiên, em xác định rõ giả thuyết và chỉ chọn 1 biến duy nhất để thử nghiệm (ví dụ: Hình ảnh, Headline hoặc Target Audience). Tiếp theo, phân bổ ngân sách đều nhau cho các nhóm test và chạy trong cùng một khoảng thời gian đủ dài để đạt đủ mẫu thống kê. Sau đó, em đo lường các chỉ số quyết định (CPL/CPA/CTR), chọn ra phương án thắng cuộc (Winner) và scale up ngân sách cho phương án đó.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('aac3b5ac-bdf5-5e37-9173-5334c692718b', (select id from public.interview_sets where slug = 'r2w-digital-marketing'), 4, 'Nếu ngân sách chiến dịch bị cắt giảm 30% nhưng mục tiêu về số lượng Lead không đổi, bạn sẽ điều chỉnh kế hoạch như thế nào?', '', '{}'::text[], 3, 20, '[{"id":"criterion_1","label":"Cắt giảm chi phí thừa","weight":4,"maxScore":4},{"id":"criterion_2","label":"Dồn ngân sách cho tệp hiệu quả","weight":4,"maxScore":4},{"id":"criterion_3","label":"Đẩy mạnh Remarketing tệp ấm","weight":4,"maxScore":4},{"id":"criterion_4","label":"Tối ưu chuyển đổi On-page (CRO)","weight":4,"maxScore":4},{"id":"criterion_5","label":"Tư duy tối ưu bài bản","weight":4,"maxScore":4}]'::jsonb, '[{"id":"criterion_1","label":"Cắt giảm chi phí thừa","description":"Cắt giảm chi phí thừa (Tắt Adset kém hiệu quả, target rộng không tạo lead).","keywords":[],"weight":4,"maxScore":4,"skill":"Budget Optimization"},{"id":"criterion_2","label":"Dồn ngân sách cho tệp hiệu quả","description":"Tập trung ngân sách cho kênh/tệp có Conversion Rate cao nhất.","keywords":[],"weight":4,"maxScore":4,"skill":"Performance Marketing"},{"id":"criterion_3","label":"Đẩy mạnh Remarketing tệp ấm","description":"Đẩy mạnh Remarketing/Retargeting tệp ấm để hạ CPL.","keywords":[],"weight":4,"maxScore":4,"skill":"Multi-channel Management"},{"id":"criterion_4","label":"Tối ưu chuyển đổi On-page (CRO)","description":"Tối ưu tỷ lệ chuyển đổi On-page trên trang đích (CRO).","keywords":[],"weight":4,"maxScore":4,"skill":"A/B Testing"},{"id":"criterion_5","label":"Tư duy tối ưu bài bản","description":"Tư duy tối ưu hóa chi phí và bảo toàn mục tiêu kinh doanh.","keywords":[],"weight":4,"maxScore":4,"skill":"Budget Optimization"}]'::jsonb, 'Em sẽ tập trung tối ưu hóa chi phí bằng cách: Tắt ngay các nhóm quảng cáo/Content kém hiệu quả và dồn ngân sách cho các Adset có Conversion Rate cao nhất. Thực hiện Remarketing lại tệp khách hàng ấm (Website Visitors, Engagement Page) vì tệp này có CPL rẻ hơn. Đồng thời, tối ưu lại Headline và Form trên Landing Page để tăng tỷ lệ chuyển đổi nhằm bù đắp cho việc giảm ngân sách.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('07073e73-e8ee-5185-86a4-1d5970c5960c', (select id from public.interview_sets where slug = 'r2w-digital-marketing'), 5, 'Trong mùa chiến dịch cao điểm (Mega Sale), bạn cùng lúc phải quản lý nhiều kênh (Facebook, TikTok, Google) với deadline gấp. Bạn ưu tiên công việc như thế nào?', '', '{}'::text[], 3, 20, '[{"id":"criterion_1","label":"Ma trận ưu tiên rõ ràng","weight":5,"maxScore":5},{"id":"criterion_2","label":"Kiểm tra kỹ thuật & Tracking","weight":4,"maxScore":4},{"id":"criterion_3","label":"Tập trung kênh doanh thu cốt lõi","weight":4,"maxScore":4},{"id":"criterion_4","label":"Sử dụng Dashboard theo dõi","weight":3,"maxScore":3},{"id":"criterion_5","label":"Phương án dự phòng (Backup)","weight":4,"maxScore":4}]'::jsonb, '[{"id":"criterion_1","label":"Ma trận ưu tiên rõ ràng","description":"Phương pháp phân loại công việc ưu tiên rõ ràng (Ma trận Eisenhower).","keywords":[],"weight":5,"maxScore":5,"skill":"Multi-channel Management"},{"id":"criterion_2","label":"Kiểm tra kỹ thuật & Tracking","description":"Kiểm tra hệ thống kỹ thuật & luồng Tracking trước giờ G.","keywords":[],"weight":4,"maxScore":4,"skill":"Performance Marketing"},{"id":"criterion_3","label":"Tập trung kênh doanh thu cốt lõi","description":"Tập trung vào kênh tạo doanh thu và số lượng đơn cốt lõi.","keywords":[],"weight":4,"maxScore":4,"skill":"Budget Optimization"},{"id":"criterion_4","label":"Sử dụng Dashboard theo dõi","description":"Sử dụng công cụ theo dõi tự động (Dashboard real-time).","keywords":[],"weight":3,"maxScore":3,"skill":"Data Analysis"},{"id":"criterion_5","label":"Phương án dự phòng (Backup)","description":"Có phương án quản trị rủi ro (Backup tài khoản Ads/Thẻ thanh toán).","keywords":[],"weight":4,"maxScore":4,"skill":"Multi-channel Management"}]'::jsonb, 'Em sẽ phân loại công việc theo Ma trận Eisenhower: Ưu tiên số 1 là kiểm tra ngân sách, trạng thái phê duyệt quảng cáo và luồng Tracking data trên tất cả các kênh trước giờ G. Tiếp theo, em ưu tiên theo dõi kịch bản phân bổ ngân sách cho kênh mang lại doanh thu chính. Lập Dashboard tự động để theo dõi chỉ số real-time và chuẩn bị sẵn phương án dự phòng (Backup Ads) nếu có tài khoản bị vô hiệu hóa.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('3c63791d-e681-5f61-aaac-7656fcfce5b3', (select id from public.interview_sets where slug = 'r2w-financial-analyst'), 1, 'Giới thiệu bản thân và vì sao bạn chọn nghề Financial Analyst', '', '{}'::text[], 1, 30, '[{"id":"criterion_1","label":"Nền tảng chuyên môn cụ thể","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng chuyên ngành","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Nền tảng chuyên môn cụ thể","description":"Nêu cụ thể ngành học/dự án đã làm liên quan trực tiếp đến phân tích tài chính, báo cáo tài chính, định giá hoặc mô hình tài chính.","keywords":[],"weight":12,"maxScore":12,"skill":"Financial Analysis"},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","description":"Chỉ ra đúng đặc thù công việc Financial Analyst là phân tích dữ liệu tài chính, đánh giá hiệu quả kinh doanh, hỗ trợ ra quyết định đầu tư/ngân sách.","keywords":[],"weight":10,"maxScore":10,"skill":"Business Acumen"},{"id":"criterion_3","label":"Từ vựng chuyên ngành","description":"Trình bày mạch lạc, dùng các thuật ngữ cơ bản: Financial Statement, Ratio, Forecast, Budgeting.","keywords":[],"weight":8,"maxScore":8,"skill":"Communication"}]'::jsonb, 'Nêu cụ thể ngành học/dự án tài chính doanh nghiệp, định giá, mô hình tài chính; nêu rõ đặc thù công việc FA là phân tích dữ liệu, đánh giá hiệu quả kinh doanh, xây dựng mô hình dự báo để hỗ trợ lãnh đạo ra quyết định đầu tư và phân bổ vốn.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
