  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('c7b363f3-aa55-59e2-9814-b2b3581644fe', (select id from public.interview_sets where slug = 'r2w-financial-analyst'), 2, 'Bạn hiểu vai trò của một Chuyên viên Phân tích Tài chính trong doanh nghiệp/ngân hàng là gì?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Xác định đúng vai trò","weight":15,"maxScore":15},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Xác định đúng vai trò","description":"Nêu rõ FA phân tích BCTC, xây dựng mô hình tài chính, dự báo và hỗ trợ lãnh đạo ra quyết định kinh doanh.","keywords":[],"weight":15,"maxScore":15,"skill":"Financial Analysis"},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","description":"Nêu tối thiểu 3/5 đầu việc: thu thập dữ liệu tài chính, phân tích tỷ số, xây dựng mô hình dự báo, lập ngân sách, báo cáo biến động.","keywords":[],"weight":12,"maxScore":12,"skill":"Forecasting"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Dùng đúng thuật ngữ: Financial Modeling, Variance Analysis, Budgeting, Forecasting, Financial Statements.","keywords":[],"weight":8,"maxScore":8,"skill":"Business Acumen"}]'::jsonb, 'FA là người xây dựng mô hình tài chính, dự báo doanh thu - chi phí, phân tích độ lệch ngân sách (Variance Analysis), tính toán các chỉ số sinh lời và đánh giá tính khả thi của các dự án đầu tư.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('f3a5d307-5752-5db1-8cb6-6099e96b646b', (select id from public.interview_sets where slug = 'r2w-financial-analyst'), 3, 'Bạn đã từng tham gia dự án/bài tập nào liên quan đến phân tích tài chính chưa?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","weight":15,"maxScore":15},{"id":"criterion_2","label":"Trình bày theo mô hình STAR","weight":12,"maxScore":12},{"id":"criterion_3","label":"Bài học nghiệp vụ rút ra","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","description":"Nêu tên/bối cảnh dự án hoặc bài tập cụ thể, vai trò đảm nhận rõ ràng.","keywords":[],"weight":15,"maxScore":15,"skill":"Data Analysis"},{"id":"criterion_2","label":"Trình bày theo mô hình STAR","description":"Bối cảnh (Situation) → Nhiệm vụ (Task) → Hành động cụ thể (Action) → Kết quả đo lường được (Result).","keywords":[],"weight":12,"maxScore":12,"skill":"Communication"},{"id":"criterion_3","label":"Bài học nghiệp vụ rút ra","description":"Chỉ ra được 1 bài học nghiệp vụ cụ thể, ví dụ: ''phải kiểm tra chéo số liệu và ghi rõ giả định trước khi kết luận''.","keywords":[],"weight":8,"maxScore":8,"skill":"Business Acumen"}]'::jsonb, 'Nêu dự án/case study cụ thể (xây mô hình DCF, định giá cổ phiếu, phân tích chi phí dự án); trình bày rõ ràng theo mô hình STAR và nêu rõ bài học về việc kiểm tra chéo số liệu và tính hợp lý của các giả định.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('947df71b-dd0a-5482-819d-d77ea82e3161', (select id from public.interview_sets where slug = 'r2w-financial-analyst'), 4, 'Các nhóm chỉ số tài chính quan trọng thường dùng để phân tích doanh nghiệp là gì?', '', '{}'::text[], 2, 30, '[{"id":"criterion_1","label":"Liệt kê đủ các nhóm chỉ số","weight":15,"maxScore":15},{"id":"criterion_2","label":"Giải thích ý nghĩa và ví dụ","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng chuyên ngành","weight":3,"maxScore":3}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đủ các nhóm chỉ số","description":"Chỉ số khả năng thanh khoản, cơ cấu vốn và nợ, hiệu quả hoạt động, khả năng sinh lời, định giá thị trường.","keywords":[],"weight":15,"maxScore":15,"skill":"Financial Analysis"},{"id":"criterion_2","label":"Giải thích ý nghĩa và ví dụ","description":"Giải thích được các chỉ số này có ý nghĩa như thế nào khi đánh giá sức khỏe doanh nghiệp.","keywords":[],"weight":12,"maxScore":12,"skill":"Business Acumen"},{"id":"criterion_3","label":"Từ vựng chuyên ngành","description":"Dùng đúng thuật ngữ: Liquidity, Profitability, Leverage, Valuation.","keywords":[],"weight":3,"maxScore":3,"skill":"Data Analysis"}]'::jsonb, 'Nêu 5 nhóm chỉ số: Khả năng thanh toán (Current, Quick Ratio); Cơ cấu vốn & Đòn bẩy (D/E, D/A); Hiệu quả hoạt động (Vòng quay tồn kho, Vòng quay khoản phải thu); Khả năng sinh lời (Gross Margin, Net Margin, ROE, ROA); và Định giá thị trường (P/E, P/B, EV/EBITDA).')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('f2ee8daa-af4b-5ca8-acec-792ecb464624', (select id from public.interview_sets where slug = 'r2w-financial-analyst'), 5, 'Quy trình xây dựng một mô hình dự báo tài chính đơn giản gồm những bước nào?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Liệt kê đúng các bước","weight":18,"maxScore":18},{"id":"criterion_2","label":"Vai trò của giả định (Assumptions)","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đúng các bước","description":"Xác định mục tiêu → thu thập dữ liệu lịch sử → đặt giả định → dự phóng doanh thu/chi phí → lập báo cáo dự phóng → kiểm tra độ nhạy.","keywords":[],"weight":18,"maxScore":18,"skill":"Forecasting"},{"id":"criterion_2","label":"Vai trò của giả định (Assumptions)","description":"Assumption là nền tảng của mô hình, cần có căn cứ thực tế và kiểm chứng, không đặt cảm tính.","keywords":[],"weight":10,"maxScore":10,"skill":"Financial Analysis"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Dùng đúng thuật ngữ: Assumption, Revenue Forecast, Sensitivity Analysis, Scenario.","keywords":[],"weight":7,"maxScore":7,"skill":"Data Analysis"}]'::jsonb, 'Quy trình: 1) Xác định mục tiêu & phạm vi mô hình -> 2) Thu thập và làm sạch dữ liệu lịch sử (3-5 năm) -> 3) Đặt các giả định (Assumptions về tăng trưởng doanh thu, chi phí biên, CAPEX) -> 4) Dự phóng 3 báo cáo tài chính -> 5) Phân tích độ nhạy (Sensitivity Analysis) & Kịch bản (Scenarios).')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('c77247a9-3837-5a50-baa0-58f58f2e02b7', (select id from public.interview_sets where slug = 'r2w-financial-analyst'), 6, 'Trình bày 3 báo cáo tài chính chính và mối liên hệ giữa chúng', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Liệt kê đúng 3 báo cáo","weight":15,"maxScore":15},{"id":"criterion_2","label":"Giải thích mối liên hệ chính xác","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng chuyên ngành","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đúng 3 báo cáo","description":"Bảng cân đối kế toán (Balance Sheet), Báo cáo kết quả kinh doanh (Income Statement), Báo cáo lưu chuyển tiền tệ (Cash Flow Statement).","keywords":[],"weight":15,"maxScore":15,"skill":"Financial Analysis"},{"id":"criterion_2","label":"Giải thích mối liên hệ chính xác","description":"Lợi nhuận ảnh hưởng đến vốn chủ sở hữu; dòng tiền phản ánh tiền thực thu/chi; các báo cáo liên kết với nhau qua tài sản, nợ và dòng tiền.","keywords":[],"weight":12,"maxScore":12,"skill":"Financial Analysis"},{"id":"criterion_3","label":"Từ vựng chuyên ngành","description":"Dùng đúng thuật ngữ: Assets, Liabilities, Equity, Revenue, Expense, Cash Flow.","keywords":[],"weight":8,"maxScore":8,"skill":"Communication"}]'::jsonb, 'Bảng cân đối kế toán (Balance Sheet), Báo cáo kết quả kinh doanh (Income Statement) và Báo cáo lưu chuyển tiền tệ (Cash Flow Statement). Lợi nhuận sau thuế từ IS chảy vào Lợi nhuận giữ lại trên BS; dòng tiền thuần trên CFS khớp với biến động Tiền mặt trên BS; chi phí khấu hao trên IS được cộng lại trong dòng tiền hoạt động CFO trên CFS.')
