  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('a4f6c176-298c-5329-a426-387f7232232f', (select id from public.interview_sets where slug = 'r2w-financial-analyst'), 7, 'Sếp yêu cầu báo cáo tài chính gấp nhưng số liệu từ các phòng ban không khớp, bạn xử lý thế nào?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Xác minh và đối chiếu nguồn","weight":20,"maxScore":20},{"id":"criterion_2","label":"Minh bạch và quản lý kỳ vọng","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng chuyên ngành","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Xác minh và đối chiếu nguồn","description":"Không được tự ý sửa đổi số liệu, kiểm tra chéo và làm việc rõ với phòng ban liên quan.","keywords":[],"weight":20,"maxScore":20,"skill":"Data Analysis"},{"id":"criterion_2","label":"Minh bạch và quản lý kỳ vọng","description":"Báo ngay với sếp về tình trạng số liệu, đề xuất timeline giải quyết và đánh dấu phần chưa chắc chắn.","keywords":[],"weight":20,"maxScore":20,"skill":"Communication"},{"id":"criterion_3","label":"Từ vựng chuyên ngành","description":"Dùng đúng thuật ngữ: Data Reconciliation, Variance, Data Integrity, Deadline.","keywords":[],"weight":10,"maxScore":10,"skill":"Business Acumen"}]'::jsonb, 'Tuyệt đối không tự ý chỉnh sửa số liệu để làm tròn số; báo cáo ngay với sếp tình trạng số liệu không khớp, nêu rõ nguyên nhân và timeline giải quyết; tổ chức họp nhanh với đại diện các phòng ban để đối soát (reconcile); gửi báo cáo sơ bộ kèm ghi chú rõ ràng các phần số liệu chưa xác nhận.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('8c8b8692-e632-5677-b6dc-78117685ff33', (select id from public.interview_sets where slug = 'r2w-financial-analyst'), 8, 'Kết quả phân tích cho thấy dự án thua lỗ nhưng sếp muốn tiếp tục, bạn làm gì?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Giữ nguyên tính khách quan","weight":20,"maxScore":20},{"id":"criterion_2","label":"Đề xuất kịch bản và giải pháp","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng chuyên ngành","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Giữ nguyên tính khách quan","description":"Không điều chỉnh số liệu để vừa ý cấp trên; trình bày đúng như dữ liệu thể hiện.","keywords":[],"weight":20,"maxScore":20,"skill":"Business Acumen"},{"id":"criterion_2","label":"Đề xuất kịch bản và giải pháp","description":"Phân tích độ nhạy, kịch bản, rủi ro, cơ hội; đề xuất phương án cải thiện tính khả thi.","keywords":[],"weight":20,"maxScore":20,"skill":"Forecasting"},{"id":"criterion_3","label":"Từ vựng chuyên ngành","description":"Dùng đúng thuật ngữ: Scenario Analysis, Risk, ROI, NPV, Payback Period.","keywords":[],"weight":10,"maxScore":10,"skill":"Financial Analysis"}]'::jsonb, 'Giữ vững tính trung thực và khách quan nghề nghiệp, không xào xáo số liệu để làm đẹp lòng sếp; phân tích kịch bản đa chiều (Best/Base/Worst Case) và phân tích độ nhạy (Sensitivity) để chỉ ra các điều kiện cần có để dự án có lãi; đề xuất các giải pháp tối ưu chi phí hoặc phương án tái cấu trúc dự án.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('afc665e5-5b0c-5459-9de0-f02c2c180fc5', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien'), 1, 'Hãy giới thiệu ngắn gọn về bản thân và lý do bạn lựa chọn công việc kế toán?', '', '{}'::text[], 1, 30, '[{"id":"criterion_1","label":"Giới thiệu đúng thông tin cá nhân","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do chọn nghề đúng bản chất","weight":10,"maxScore":10},{"id":"criterion_3","label":"Liên hệ điểm mạnh với công việc","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Giới thiệu đúng thông tin cá nhân","description":"Nêu được ngành học, kinh nghiệm/thực tập hoặc hoạt động liên quan đến kế toán.","keywords":[],"weight":12,"maxScore":12,"skill":"Accounting Knowledge"},{"id":"criterion_2","label":"Lý do chọn nghề đúng bản chất","description":"Nêu được lý do cụ thể như yêu thích số liệu, quan tâm đến tài chính - kế toán hoặc muốn phát triển chuyên môn.","keywords":[],"weight":10,"maxScore":10,"skill":"Accounting Knowledge"},{"id":"criterion_3","label":"Liên hệ điểm mạnh với công việc","description":"Nêu tối thiểu 2 điểm mạnh phù hợp như cẩn thận, chính xác, trung thực, trách nhiệm và giải thích được sự phù hợp.","keywords":[],"weight":8,"maxScore":8,"skill":"Accuracy"}]'::jsonb, 'Ứng viên nêu được ngành học, kinh nghiệm/thực tập hoặc hoạt động liên quan đến kế toán; lý do chọn nghề cụ thể (yêu thích số liệu, quan tâm tài chính - kế toán); liên hệ tối thiểu 2 điểm mạnh phù hợp như cẩn thận, chính xác, trung thực, trách nhiệm.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('3d88f6af-39b9-5a6f-a4a3-b5689a4d6b6e', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien'), 2, 'Theo bạn, một kế toán viên cần có những kỹ năng quan trọng nào?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Chính xác và cẩn thận","weight":15,"maxScore":15},{"id":"criterion_2","label":"Kiến thức chuyên môn","weight":12,"maxScore":12},{"id":"criterion_3","label":"Trung thực và trách nhiệm","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Chính xác và cẩn thận","description":"Hiểu rằng kế toán thường xuyên làm việc với số liệu, hóa đơn và chứng từ nên cần hạn chế sai sót.","keywords":[],"weight":15,"maxScore":15,"skill":"Accuracy"},{"id":"criterion_2","label":"Kiến thức chuyên môn","description":"Đề cập được hạch toán, chứng từ, sổ sách, doanh thu - chi phí hoặc nghiệp vụ kế toán cơ bản.","keywords":[],"weight":12,"maxScore":12,"skill":"Accounting Knowledge"},{"id":"criterion_3","label":"Trung thực và trách nhiệm","description":"Hiểu trách nhiệm của kế toán đối với số liệu và không cố tình làm sai lệch thông tin.","keywords":[],"weight":8,"maxScore":8,"skill":"Integrity"}]'::jsonb, 'Kế toán viên cần tính chính xác và cẩn thận do thường xuyên làm việc với số liệu, chứng từ; nắm vững kiến thức chuyên môn (hạch toán, sổ sách, doanh thu - chi phí); có phẩm chất trung thực và trách nhiệm đối với số liệu.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
