  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('27250b7c-0291-5988-9540-ae46cb301e86', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien'), 3, 'Theo bạn, công việc của một kế toán viên trong doanh nghiệp thường bao gồm những nhiệm vụ gì?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Kiểm tra chứng từ","weight":15,"maxScore":15},{"id":"criterion_2","label":"Nhập liệu & hạch toán","weight":12,"maxScore":12},{"id":"criterion_3","label":"Đối chiếu số liệu","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Kiểm tra chứng từ","description":"Nêu được việc tiếp nhận, kiểm tra hóa đơn và chứng từ liên quan.","keywords":[],"weight":15,"maxScore":15,"skill":"Attention to Detail"},{"id":"criterion_2","label":"Nhập liệu & hạch toán","description":"Hiểu việc nhập liệu và hạch toán các nghiệp vụ phát sinh vào phần mềm kế toán.","keywords":[],"weight":12,"maxScore":12,"skill":"Accounting Knowledge"},{"id":"criterion_3","label":"Đối chiếu số liệu","description":"Biết cần đối chiếu giữa chứng từ, sổ sách và các nguồn dữ liệu liên quan.","keywords":[],"weight":8,"maxScore":8,"skill":"Accuracy"}]'::jsonb, 'Công việc bao gồm: tiếp nhận và kiểm tra tính hợp lệ của chứng từ, hóa đơn; nhập liệu và hạch toán các nghiệp vụ kinh tế phát sinh; đối chiếu số liệu giữa chứng từ, sổ sách và các tài khoản ngân hàng, công nợ.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
