values ('7ae4a725-52d7-56ba-a0a5-a837a0189d24', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien'), 4, 'Khi phát hiện số liệu trên hóa đơn và chứng từ không khớp, bạn sẽ xử lý như thế nào?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Kiểm tra và đối chiếu","weight":15,"maxScore":15},{"id":"criterion_2","label":"Xác định nguyên nhân","weight":12,"maxScore":12},{"id":"criterion_3","label":"Xử lý đúng quy trình","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Kiểm tra và đối chiếu","description":"Đối chiếu hóa đơn với hợp đồng, phiếu nhập/xuất, biên bản giao nhận hoặc chứng từ thanh toán.","keywords":[],"weight":15,"maxScore":15,"skill":"Attention to Detail"},{"id":"criterion_2","label":"Xác định nguyên nhân","description":"Xác định chênh lệch về số tiền, số lượng, thông tin, thời điểm hoặc chứng từ.","keywords":[],"weight":12,"maxScore":12,"skill":"Problem Solving"},{"id":"criterion_3","label":"Xử lý đúng quy trình","description":"Điều chỉnh/bổ sung chứng từ theo quy định trước khi ghi nhận chính thức.","keywords":[],"weight":8,"maxScore":8,"skill":"Accounting Knowledge"}]'::jsonb, 'Kiểm tra và đối chiếu hóa đơn với hợp đồng, phiếu nhập/xuất, biên bản giao nhận hoặc chứng từ thanh toán; xác định nguyên nhân chênh lệch (số tiền, số lượng, thông tin, thời điểm); xử lý đúng quy trình bằng việc điều chỉnh/bổ sung chứng từ theo quy định trước khi ghi nhận chính thức.')
