insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('fbe0474d-b2f7-5b10-b45e-4d61a84683cf', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien'), 5, 'Hãy phân biệt doanh thu, chi phí và lợi nhuận trong hoạt động của doanh nghiệp.', '', '{}'::text[], 2, 30, '[{"id":"criterion_1","label":"Hiểu bản chất doanh thu","weight":15,"maxScore":15},{"id":"criterion_2","label":"Hiểu bản chất chi phí","weight":12,"maxScore":12},{"id":"criterion_3","label":"Hiểu bản chất lợi nhuận","weight":3,"maxScore":3}]'::jsonb, '[{"id":"criterion_1","label":"Hiểu bản chất doanh thu","description":"Giải thích đúng bản chất doanh thu từ hoạt động kinh doanh.","keywords":[],"weight":15,"maxScore":15,"skill":"Accounting Knowledge"},{"id":"criterion_2","label":"Hiểu bản chất chi phí","description":"Nêu được chi phí là các khoản phát sinh liên quan đến hoạt động tạo doanh thu.","keywords":[],"weight":12,"maxScore":12,"skill":"Accounting Knowledge"},{"id":"criterion_3","label":"Hiểu bản chất lợi nhuận","description":"Hiểu lợi nhuận được xác định dựa trên doanh thu và chi phí.","keywords":[],"weight":3,"maxScore":3,"skill":"Accounting Knowledge"}]'::jsonb, 'Doanh thu là tổng giá trị các lợi ích kinh tế doanh nghiệp thu được trong kỳ từ hoạt động SXKD thông thường. Chi phí là các khoản suy giảm lợi ích kinh tế phát sinh liên quan đến việc tạo ra doanh thu. Lợi nhuận là phần chênh lệch giữa doanh thu và chi phí (Lợi nhuận = Doanh thu - Chi phí).')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

