values ('e642b331-4bb3-58a0-8cb3-c937ee06c4e9', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien'), 6, 'Bạn sẽ làm gì nếu phát hiện một nghiệp vụ đã được ghi nhận sai?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Xác định sai sót","weight":18,"maxScore":18},{"id":"criterion_2","label":"Đánh giá ảnh hưởng","weight":7,"maxScore":7},{"id":"criterion_3","label":"Điều chỉnh đúng quy trình","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Xác định sai sót","description":"Kiểm tra sai tài khoản, số tiền, thời điểm hoặc nội dung nghiệp vụ.","keywords":[],"weight":18,"maxScore":18,"skill":"Accuracy"},{"id":"criterion_2","label":"Đánh giá ảnh hưởng","description":"Xem xét ảnh hưởng đến tài khoản, doanh thu/chi phí, thuế hoặc báo cáo.","keywords":[],"weight":7,"maxScore":7,"skill":"Accounting Knowledge"},{"id":"criterion_3","label":"Điều chỉnh đúng quy trình","description":"Thực hiện bút toán điều chỉnh hoặc xử lý chứng từ theo quy định.","keywords":[],"weight":10,"maxScore":10,"skill":"Problem Solving"}]'::jsonb, 'Xác định rõ nội dung sai sót (sai tài khoản, số tiền, thời điểm hoặc nội dung); đánh giá mức độ ảnh hưởng đến các tài khoản liên quan, doanh thu, chi phí, thuế và BCTC; thực hiện bút toán điều chỉnh (bút toán đảo, ghi âm hoặc ghi bổ sung) và hoàn thiện hồ sơ chứng từ theo đúng chuẩn mực kế toán.')
