insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('2bbc7ced-43f1-5f91-bf6e-2f749ce2658a', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien'), 7, 'Cuối ngày, bạn phát hiện một chứng từ quan trọng có sai sót nhưng quản lý đang yêu cầu hoàn thành báo cáo gấp. Bạn sẽ xử lý như thế nào?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Trung thực, không che giấu","weight":20,"maxScore":20},{"id":"criterion_2","label":"Đánh giá mức độ ảnh hưởng","weight":20,"maxScore":20},{"id":"criterion_3","label":"Ưu tiên công việc hợp lý","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Trung thực, không che giấu","description":"Thông báo về sai sót, không bỏ qua hoặc cố tình sửa số liệu.","keywords":[],"weight":20,"maxScore":20,"skill":"Integrity"},{"id":"criterion_2","label":"Đánh giá mức độ ảnh hưởng","description":"Xác định chứng từ ảnh hưởng đến phần nào của báo cáo.","keywords":[],"weight":20,"maxScore":20,"skill":"Problem Solving"},{"id":"criterion_3","label":"Ưu tiên công việc hợp lý","description":"Có thể hoàn thành phần báo cáo không bị ảnh hưởng trong khi xử lý sai sót.","keywords":[],"weight":10,"maxScore":10,"skill":"Attention to Detail"}]'::jsonb, 'Thể hiện tính trung thực, chủ động báo cáo ngay với quản lý về sai sót phát hiện được chứ không che giấu hay tự ý sửa số liệu; đánh giá nhanh phạm vi ảnh hưởng của chứng từ đó lên báo cáo; ưu tiên hoàn thiện các phần báo cáo không bị ảnh hưởng trong lúc phối hợp xử lý dứt điểm sai sót.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('9475c107-7131-53f9-ae88-79c58c8c385e', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien'), 8, 'Nếu đồng nghiệp đề nghị bạn bỏ qua một sai sót nhỏ trong chứng từ để kịp thời hạn báo cáo, bạn sẽ làm gì?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Nhận diện rủi ro sai sót","weight":20,"maxScore":20},{"id":"criterion_2","label":"Trao đổi với đồng nghiệp","weight":20,"maxScore":20},{"id":"criterion_3","label":"Tính trung thực nghề nghiệp","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Nhận diện rủi ro sai sót","description":"Hiểu rằng sai sót nhỏ vẫn có thể gây ảnh hưởng nếu không được xử lý.","keywords":[],"weight":20,"maxScore":20,"skill":"Accounting Knowledge"},{"id":"criterion_2","label":"Trao đổi với đồng nghiệp","description":"Giải thích lý do cần xử lý thay vì bỏ qua.","keywords":[],"weight":20,"maxScore":20,"skill":"Problem Solving"},{"id":"criterion_3","label":"Tính trung thực nghề nghiệp","description":"Đặt tính chính xác và trung thực của số liệu lên trên việc đối phó với deadline.","keywords":[],"weight":10,"maxScore":10,"skill":"Integrity"}]'::jsonb, 'Nhận diện rõ ràng ngay cả sai sót nhỏ nếu tích lũy cũng có thể dẫn đến lệch sổ sách hoặc rủi ro pháp lý; kiên định từ chối một cách lịch sự, giải thích rõ cho đồng nghiệp lý do cần đối chiếu chuẩn xác; đặt tính chính xác và trung thực nghề nghiệp lên trên áp lực đối phó deadline.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('52e56803-6264-54ca-938c-55f6dcf43231', (select id from public.interview_sets where slug = 'r2w-kiem-toan-vien'), 1, 'Hãy giới thiệu ngắn gọn về bản thân và lý do bạn lựa chọn công việc kiểm toán.', '', '{}'::text[], 1, 30, '[{"id":"criterion_1","label":"Giới thiệu bản thân","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","weight":10,"maxScore":10},{"id":"criterion_3","label":"Hiểu công việc kiểm toán","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Giới thiệu bản thân","description":"Nêu được ngành học, thực tập hoặc kinh nghiệm liên quan.","keywords":[],"weight":12,"maxScore":12,"skill":"Audit Knowledge"},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","description":"Nêu lý do cụ thể như yêu thích phân tích, kiểm tra số liệu, tìm hiểu hoạt động doanh nghiệp.","keywords":[],"weight":10,"maxScore":10,"skill":"Analytical Thinking"},{"id":"criterion_3","label":"Hiểu công việc kiểm toán","description":"Hiểu kiểm toán liên quan đến việc thu thập bằng chứng và đánh giá thông tin tài chính.","keywords":[],"weight":8,"maxScore":8,"skill":"Evidence Assessment"}]'::jsonb, 'Nêu được nền tảng học vấn, thực tập/kinh nghiệm kiểm toán; nêu lý do cụ thể đúng bản chất nghề nghiệp (thích tư duy phân tích, tìm tòi bản chất số liệu, kiểm chứng giao dịch); hiểu kiểm toán liên quan đến việc thu thập bằng chứng đầy đủ, thích hợp để đưa ra ý kiến đánh giá.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('6835c921-e9a7-5b80-a3cb-ad44d9bed085', (select id from public.interview_sets where slug = 'r2w-kiem-toan-vien'), 2, 'Theo bạn, một kiểm toán viên cần có những phẩm chất và kỹ năng nào?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Tư duy phân tích","weight":15,"maxScore":15},{"id":"criterion_2","label":"Khách quan và độc lập","weight":12,"maxScore":12},{"id":"criterion_3","label":"Cẩn thận, thận trọng nghề nghiệp","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Tư duy phân tích","description":"Hiểu cần phân tích số liệu và tìm nguyên nhân của biến động.","keywords":[],"weight":15,"maxScore":15,"skill":"Analytical Thinking"},{"id":"criterion_2","label":"Khách quan và độc lập","description":"Hiểu kiểm toán viên cần đưa ra đánh giá dựa trên bằng chứng, không thiên vị.","keywords":[],"weight":12,"maxScore":12,"skill":"Independence"},{"id":"criterion_3","label":"Cẩn thận, thận trọng nghề nghiệp","description":"Nhận thức được việc kiểm tra hồ sơ và bằng chứng cần chính xác.","keywords":[],"weight":8,"maxScore":8,"skill":"Evidence Assessment"}]'::jsonb, 'Cần tư duy phân tích sâu sắc để nhận diện bất thường; tính khách quan và độc lập để đưa ra đánh giá dựa trên bằng chứng mà không bị chi phối; tính cẩn thận, thận trọng nghề nghiệp khi kiểm tra mẫu hồ sơ và tài liệu.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
