insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('a865ca2c-055a-5030-b085-88c35f107191', (select id from public.interview_sets where slug = 'r2w-kiem-toan-vien'), 3, 'Theo bạn, sự khác nhau cơ bản giữa kế toán và kiểm toán là gì?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Hiểu vai trò kế toán","weight":20,"maxScore":20},{"id":"criterion_2","label":"Hiểu vai trò kiểm toán","weight":10,"maxScore":10},{"id":"criterion_3","label":"Ví dụ minh họa","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Hiểu vai trò kế toán","description":"Nêu đúng kế toán thực hiện ghi nhận và tổng hợp các nghiệp vụ.","keywords":[],"weight":20,"maxScore":20,"skill":"Audit Knowledge"},{"id":"criterion_2","label":"Hiểu vai trò kiểm toán","description":"Nêu đúng kiểm toán kiểm tra và đánh giá thông tin tài chính.","keywords":[],"weight":10,"maxScore":10,"skill":"Audit Knowledge"},{"id":"criterion_3","label":"Ví dụ minh họa","description":"Có thể đưa ra ví dụ thực tế để phân biệt rõ ràng hai vai trò.","keywords":[],"weight":5,"maxScore":5,"skill":"Analytical Thinking"}]'::jsonb, 'Kế toán mang tính kiến tạo và phản ánh (ghi nhận, phân loại, tổng hợp các nghiệp vụ phát sinh thành BCTC). Kiểm toán mang tính kiểm tra và đánh giá độc lập (thu thập bằng chứng để xác minh xem BCTC do kế toán lập có phản ánh trung thực, hợp lý hay không).')
on conflict (set_id, position) do update set
