insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('b2135660-3f79-50da-a0e5-ab8b7ace0a60', (select id from public.interview_sets where slug = 'r2w-kiem-toan-vien'), 4, 'Theo bạn, mục tiêu chính của một cuộc kiểm toán báo cáo tài chính là gì?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Xác định đúng mục tiêu","weight":18,"maxScore":18},{"id":"criterion_2","label":"Sai sót trọng yếu","weight":10,"maxScore":10},{"id":"criterion_3","label":"Bằng chứng kiểm toán","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Xác định đúng mục tiêu","description":"Nêu được mục tiêu đưa ra ý kiến về báo cáo tài chính dựa trên kết quả kiểm toán.","keywords":[],"weight":18,"maxScore":18,"skill":"Audit Knowledge"},{"id":"criterion_2","label":"Sai sót trọng yếu","description":"Hiểu kiểm toán tập trung vào những sai sót có thể ảnh hưởng đáng kể đến người sử dụng báo cáo.","keywords":[],"weight":10,"maxScore":10,"skill":"Risk Assessment"},{"id":"criterion_3","label":"Bằng chứng kiểm toán","description":"Hiểu cần thu thập bằng chứng kiểm toán thích hợp và đầy đủ.","keywords":[],"weight":7,"maxScore":7,"skill":"Evidence Assessment"}]'::jsonb, 'Mục tiêu chính là thu thập đầy đủ bằng chứng kiểm toán thích hợp để KTV đưa ra ý kiến chuyên môn về việc liệu BCTC có được lập trên các khía cạnh trọng yếu phù hợp với khuôn khổ về lập và trình bày BCTC áp dụng hay không; giúp gia tăng độ tin cậy cho người sử dụng BCTC.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('66850bb5-edcd-5773-8aab-542d14a21142', (select id from public.interview_sets where slug = 'r2w-kiem-toan-vien'), 5, 'Nếu phát hiện một giao dịch có giá trị bất thường gần ngày kết thúc năm tài chính, bạn sẽ làm gì?', '', '{}'::text[], 2, 30, '[{"id":"criterion_1","label":"Nhận diện rủi ro","weight":15,"maxScore":15},{"id":"criterion_2","label":"Kiểm tra hồ sơ chứng từ","weight":10,"maxScore":10},{"id":"criterion_3","label":"Kiểm tra thời điểm ghi nhận","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Nhận diện rủi ro","description":"Nhận thấy giao dịch lớn và gần ngày khóa sổ có thể có rủi ro ghi nhận sai kỳ hoặc bất thường.","keywords":[],"weight":15,"maxScore":15,"skill":"Risk Assessment"},{"id":"criterion_2","label":"Kiểm tra hồ sơ chứng từ","description":"Kiểm tra hợp đồng, hóa đơn, phiếu xuất kho, biên bản giao nhận và thanh toán.","keywords":[],"weight":10,"maxScore":10,"skill":"Evidence Assessment"},{"id":"criterion_3","label":"Kiểm tra thời điểm ghi nhận","description":"Đối chiếu ngày giao hàng/chuyển giao với ngày ghi nhận doanh thu/chi phí.","keywords":[],"weight":5,"maxScore":5,"skill":"Analytical Thinking"}]'::jsonb, 'Nhận diện rủi ro sai lệch niên độ (cut-off) hoặc giao dịch giả tạo nhằm làm đẹp BCTC; tiến hành kiểm tra chi tiết hồ sơ chứng từ gốc (hợp đồng, phiếu xuất, biên bản bàn giao, thanh toán); đối chiếu ngày chuyển giao quyền sở hữu/rủi ro thực tế với ngày ghi nhận trên sổ sách.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
