values ('f5e0e4bb-25b1-57c7-a1be-977aa0c5500a', (select id from public.interview_sets where slug = 'r2w-kiem-toan-vien'), 6, 'Bạn sẽ đánh giá rủi ro của một khoản mục như thế nào?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Tìm hiểu khoản mục","weight":20,"maxScore":20},{"id":"criterion_2","label":"Phân tích biến động","weight":10,"maxScore":10},{"id":"criterion_3","label":"Xác định khả năng sai sót","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Tìm hiểu khoản mục","description":"Hiểu bản chất và nguồn gốc phát sinh của khoản mục.","keywords":[],"weight":20,"maxScore":20,"skill":"Audit Knowledge"},{"id":"criterion_2","label":"Phân tích biến động","description":"So sánh với kỳ trước, kế hoạch hoặc các khoản mục liên quan.","keywords":[],"weight":10,"maxScore":10,"skill":"Analytical Thinking"},{"id":"criterion_3","label":"Xác định khả năng sai sót","description":"Xem xét ghi nhận sai, thiếu chứng từ, định giá sai hoặc gian lận.","keywords":[],"weight":5,"maxScore":5,"skill":"Risk Assessment"}]'::jsonb, 'Tìm hiểu bản chất, nguồn gốc phát sinh và mức độ phức tạp của khoản mục; phân tích xu hướng biến động so với kỳ trước, ngân sách và bình quân ngành; xác định các khả năng sai sót tiềm ẩn (định giá sai, thiếu chứng từ, trích lập dự phòng không đủ hoặc gian lận).')
