  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('8c709c38-97e8-53af-9b1e-3694cd7affb6', (select id from public.interview_sets where slug = 'r2w-kiem-toan-vien'), 8, 'Khách hàng đưa ra lời giải thích nhưng bằng chứng không hoàn toàn phù hợp với lời giải thích đó. Bạn sẽ làm gì?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Không chấp nhận ngay lời giải thích","weight":20,"maxScore":20},{"id":"criterion_2","label":"Kiểm tra thêm bằng chứng","weight":20,"maxScore":20},{"id":"criterion_3","label":"Đánh giá rủi ro gian lận","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Không chấp nhận ngay lời giải thích","description":"Hiểu rằng lời giải thích bằng miệng không thay thế hoàn toàn bằng chứng kiểm toán.","keywords":[],"weight":20,"maxScore":20,"skill":"Independence"},{"id":"criterion_2","label":"Kiểm tra thêm bằng chứng","description":"Đối chiếu hợp đồng, hóa đơn, thanh toán, giao nhận hoặc nguồn độc lập.","keywords":[],"weight":20,"maxScore":20,"skill":"Evidence Assessment"},{"id":"criterion_3","label":"Đánh giá rủi ro gian lận","description":"Xem xét có dấu hiệu sai sót hoặc gian lận hay không.","keywords":[],"weight":10,"maxScore":10,"skill":"Risk Assessment"}]'::jsonb, 'Duy trì thái độ hoài nghi nghề nghiệp, không chấp nhận giải thích bằng miệng nếu không có chứng từ chứng minh; mở rộng phạm vi kiểm tra, đối chiếu hợp đồng, chứng từ giao nhận, thanh toán thực tế; đánh giá khả năng có sai sót trọng yếu hoặc gian lận và báo cáo cấp quản lý.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('455ab92f-5c93-565a-9e27-8fe9a0236b7d', (select id from public.interview_sets where slug = 'r2w-logistics-ops'), 1, 'Chào em. Công ty mình đang chuẩn bị xuất khẩu một lô hàng Nông sản tươi (giá trị thấp, dễ hư hỏng) sang Châu Âu và nhập khẩu một lô Linh kiện điện tử (giá trị rất cao) từ Nhật Bản về. Theo em, với 2 lô hàng này, mình nên ưu tiên chọn điều kiện FOB hay CIF cho từng lô? Tại sao?', '', '{}'::text[], 2, 40, '[{"id":"criterion_1","label":"Xử lý lô Nông sản xuất (CIF + Lý do cước/thời gian)","weight":15,"maxScore":15},{"id":"criterion_2","label":"Xử lý lô Linh kiện nhập (FOB + Lý do bảo hiểm/kiểm soát)","weight":15,"maxScore":15},{"id":"criterion_3","label":"Từ vựng chuyên ngành & Phong thái tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Xử lý lô Nông sản xuất (CIF + Lý do cước/thời gian)","description":"Đề xuất CIF, giải thích vì nông sản dễ hỏng nên cần chủ động book tàu để kiểm soát thời gian vận chuyển nhanh nhất và tối ưu cước phí.","keywords":[],"weight":15,"maxScore":15,"skill":"Incoterms"},{"id":"criterion_2","label":"Xử lý lô Linh kiện nhập (FOB + Lý do bảo hiểm/kiểm soát)","description":"Đề xuất FOB, giải thích vì hàng giá trị cao nên cần tự mua bảo hiểm trong nước và kiểm soát hãng tàu để chủ động khiếu nại nếu rủi ro.","keywords":[],"weight":15,"maxScore":15,"skill":"Transport Risk Management"},{"id":"criterion_3","label":"Từ vựng chuyên ngành & Phong thái tự tin","description":"Sử dụng đúng các thuật ngữ Risk, Freight, Insurance, THC, hải quan với phong thái tự tin.","keywords":[],"weight":10,"maxScore":10,"skill":"Incident Communication"}]'::jsonb, 'Lô Nông sản xuất khẩu: Đề xuất bán CIF. Vì mặt hàng này giá trị thấp và dễ hư hỏng, công ty chủ động book cước tàu (Ocean Freight) số lượng lớn sẽ chọn được thời gian vận chuyển nhanh nhất, giảm rủi ro hư hỏng. Đồng thời, công ty có thể thu thêm lợi nhuận từ chênh lệch cước phí.
Lô Linh kiện điện tử nhập khẩu: Đề xuất mua FOB (hoặc FCA/EXW). Do hàng có giá trị rất cao và rủi ro lớn, mua FOB giúp công ty chủ động tự mua bảo hiểm hàng hóa tại Việt Nam và tự book tàu theo dõi lịch trình. Nếu xảy ra mất mát, việc đền bù và khiếu nại bảo hiểm trong nước sẽ thuận tiện hơn phụ thuộc vào bên bán nước ngoài.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('a9ca0085-d49c-5504-89fd-3223ea28b8aa', (select id from public.interview_sets where slug = 'r2w-logistics-ops'), 2, 'Giả sử lúc này là 2h sáng. Tài xế gọi điện cho em báo xe đầu kéo chở container thịt bò đông lạnh (-18°C) của công ty bị tai nạn lật ngang trên dốc cầu Phú Mỹ (TP.HCM). Thùng container bị móp, máy lạnh báo lỗi ngừng hoạt động. Tài xế đang hoảng loạn chờ cảnh sát giao thông. Là Ops trực ca đó, em hãy nêu từng bước hành động của em ngay trong đêm nay.', '', '{}'::text[], 3, 60, '[{"id":"criterion_1","label":"Bước 1 - Kiểm soát tài xế & Bằng chứng hiện trường","weight":15,"maxScore":15},{"id":"criterion_2","label":"Bước 2 - Phương án cứu nhiệt độ hàng hóa khẩn cấp","weight":20,"maxScore":20},{"id":"criterion_3","label":"Bước 3 - Thủ tục CSGT & Bảo hiểm","weight":15,"maxScore":15},{"id":"criterion_4","label":"Bước 4 - Báo cáo nội bộ & Khách hàng","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Bước 1 - Kiểm soát tài xế & Bằng chứng hiện trường","description":"Trấn an tài xế, chụp ảnh hiện trường, bảng nhiệt độ, không tự ý mở cửa thùng container.","keywords":[],"weight":15,"maxScore":15,"skill":"Crisis Management"},{"id":"criterion_2","label":"Bước 2 - Phương án cứu nhiệt độ hàng hóa khẩn cấp","description":"Điều xe cẩu, xe lạnh dự phòng sang hàng khẩn cấp duy trì nhiệt độ -18°C.","keywords":[],"weight":20,"maxScore":20,"skill":"Transport Risk Management"},{"id":"criterion_3","label":"Bước 3 - Thủ tục CSGT & Bảo hiểm","description":"Phối hợp biên bản CSGT, gọi hotline giám định viên bảo hiểm ngay trong đêm.","keywords":[],"weight":15,"maxScore":15,"skill":"Insurance Process"},{"id":"criterion_4","label":"Bước 4 - Báo cáo nội bộ & Khách hàng","description":"Báo cáo sếp trực tiếp, thông báo minh bạch rủi ro trễ tiến độ cho khách hàng vào sáng hôm sau.","keywords":[],"weight":10,"maxScore":10,"skill":"Incident Communication"}]'::jsonb, 'Bước 1 (Kiểm soát hiện trường): Trấn an tài xế bình tĩnh, yêu cầu chụp ảnh hiện trường, bảng đồng hồ nhiệt độ và chỗ móp để làm bằng chứng. Yêu cầu tuyệt đối không tự ý mở cửa container tránh làm thoát nhiệt.
Bước 2 (Cứu hàng): Điều động ngay 1 xe cẩu và 1 xe container lạnh dự phòng (hoặc xe tải lạnh) đến hiện trường để sang hàng (cross-docking) hoặc cẩu nguyên thùng lên xe mới, cắm điện lại càng sớm càng tốt để duy trì mốc -18°C.
Bước 3 (Pháp lý & Bảo hiểm): Hướng dẫn tài xế phối hợp lập biên bản hiện trường với CSGT. Liên hệ ngay hotline công ty Bảo hiểm hàng hóa để cử giám định viên xuống ghi nhận.
Bước 4 (Truyền thông & Báo cáo): Báo cáo sếp trực tiếp và gửi email thông báo rủi ro trễ tiến độ cho khách hàng vào sáng hôm sau một cách minh bạch.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('3e94a243-0f21-5393-a1fd-c52437fa8a0c', (select id from public.interview_sets where slug = 'r2w-marketing-intern'), 1, 'Hãy giới thiệu ngắn gọn về bản thân và lý do bạn lựa chọn theo đuổi công việc Marketing Intern.', '', '{}'::text[], 1, 10, '[{"id":"criterion_1","label":"Giới thiệu bản thân rõ ràng, tự tin","weight":2,"maxScore":2},{"id":"criterion_2","label":"Nêu nền tảng/kỹ năng sẵn có","weight":2,"maxScore":2},{"id":"criterion_3","label":"Lý do chọn ngành thuyết phục","weight":3,"maxScore":3},{"id":"criterion_4","label":"Thái độ học hỏi, cầu tiến","weight":2,"maxScore":2},{"id":"criterion_5","label":"Trình bày mạch lạc","weight":1,"maxScore":1}]'::jsonb, '[{"id":"criterion_1","label":"Giới thiệu bản thân rõ ràng, tự tin","description":"Trình bày rõ ràng, phong thái tự tin.","keywords":[],"weight":2,"maxScore":2,"skill":"Communication"},{"id":"criterion_2","label":"Nêu nền tảng/kỹ năng sẵn có","description":"Nêu được nền tảng/kỹ năng sẵn có (nghiên cứu thị trường, viết content, thiết kế cơ bản).","keywords":[],"weight":2,"maxScore":2,"skill":"Marketing Fundamentals"},{"id":"criterion_3","label":"Lý do chọn ngành thuyết phục","description":"Lý do lựa chọn ngành Marketing thuyết phục, gắn với đam mê và định hướng.","keywords":[],"weight":3,"maxScore":3,"skill":"Marketing Fundamentals"},{"id":"criterion_4","label":"Thái độ học hỏi, cầu tiến","description":"Thể hiện thái độ học hỏi, cầu tiến và tinh thần trách nhiệm.","keywords":[],"weight":2,"maxScore":2,"skill":"Learning Agility"},{"id":"criterion_5","label":"Trình bày mạch lạc","description":"Trình bày mạch lạc, đúng thời gian quy định.","keywords":[],"weight":1,"maxScore":1,"skill":"Communication"}]'::jsonb, 'Em là sinh viên chuyên ngành Marketing, có nền tảng về nghiên cứu thị trường, viết content cơ bản và thiết kế Canva. Em chọn vị trí Marketing Intern vì đam mê tạo ra các nội dung truyền cảm hứng, muốn áp dụng lý thuyết đã học vào thực tế doanh nghiệp và rèn luyện kỹ năng thực chiến dưới sự hướng dẫn của các anh chị đi trước.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('e1fdfb07-a690-51ec-a50c-a8e126bda172', (select id from public.interview_sets where slug = 'r2w-marketing-intern'), 2, 'Theo bạn, một Marketing Intern cần có những yếu tố hoặc kỹ năng quan trọng nào để hoàn thành tốt công việc?', '', '{}'::text[], 1, 10, '[{"id":"criterion_1","label":"Chủ động và ham học hỏi","weight":2,"maxScore":2},{"id":"criterion_2","label":"Kỹ năng tạo nội dung","weight":2,"maxScore":2},{"id":"criterion_3","label":"Sự nhạy bén với xu hướng","weight":2,"maxScore":2},{"id":"criterion_4","label":"Quản lý thời gian, deadline","weight":2,"maxScore":2},{"id":"criterion_5","label":"Giao tiếp và làm việc nhóm","weight":2,"maxScore":2}]'::jsonb, '[{"id":"criterion_1","label":"Chủ động và ham học hỏi","description":"Chủ động và tinh thần ham học hỏi nhanh trong môi trường mới.","keywords":[],"weight":2,"maxScore":2,"skill":"Learning Agility"},{"id":"criterion_2","label":"Kỹ năng tạo nội dung","description":"Kỹ năng tạo nội dung (viết/thiết kế cơ bản).","keywords":[],"weight":2,"maxScore":2,"skill":"Creativity"},{"id":"criterion_3","label":"Sự nhạy bén với xu hướng","description":"Sự nhạy bén với xu hướng thị trường/Gen Z trên mạng xã hội.","keywords":[],"weight":2,"maxScore":2,"skill":"Trend Awareness"},{"id":"criterion_4","label":"Quản lý thời gian, deadline","description":"Quản lý thời gian, đảm bảo hoàn thành deadline.","keywords":[],"weight":2,"maxScore":2,"skill":"Marketing Fundamentals"},{"id":"criterion_5","label":"Giao tiếp và làm việc nhóm","description":"Giao tiếp và làm việc nhóm linh hoạt.","keywords":[],"weight":2,"maxScore":2,"skill":"Communication"}]'::jsonb, 'Theo em, một Marketing Intern cần có tư duy chủ động và tinh thần học hỏi nhanh. Về kỹ năng, cần có khả năng viết lách, sự nhạy bén với các xu hướng trên mạng xã hội (Social Trends), kỹ năng quản lý thời gian để hoàn thành deadline, và khả năng làm việc nhóm tốt để phối hợp linh hoạt với các bộ phận khác.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('869b6660-5445-573e-a79b-bc572b008d25', (select id from public.interview_sets where slug = 'r2w-marketing-intern'), 3, 'Khi được giao nhiệm vụ viết bài đăng cho Fanpage nhưng bài viết đạt lượng tương tác (Reach/Engagement) rất thấp, bạn sẽ xử lý như thế nào?', '', '{}'::text[], 2, 15, '[{"id":"criterion_1","label":"Chủ động phân tích chỉ số","weight":3,"maxScore":3},{"id":"criterion_2","label":"Xác định nguyên nhân cốt lõi","weight":4,"maxScore":4},{"id":"criterion_3","label":"Nghiên cứu đối thủ/thị trường","weight":3,"maxScore":3},{"id":"criterion_4","label":"Đề xuất cải thiện cụ thể","weight":3,"maxScore":3},{"id":"criterion_5","label":"Báo cáo và xin ý kiến Mentor","weight":2,"maxScore":2}]'::jsonb, '[{"id":"criterion_1","label":"Chủ động phân tích chỉ số","description":"Không chán nản, chủ động phân tích chỉ số bài viết (Reach, CTR, Engagement).","keywords":[],"weight":3,"maxScore":3,"skill":"Marketing Fundamentals"},{"id":"criterion_2","label":"Xác định nguyên nhân cốt lõi","description":"Xác định các nguyên nhân cốt lõi (Content, Visual, Thời gian đăng).","keywords":[],"weight":4,"maxScore":4,"skill":"Creativity"},{"id":"criterion_3","label":"Nghiên cứu đối thủ/thị trường","description":"Nghiên cứu đối thủ/thị trường để tìm góc nhìn mới.","keywords":[],"weight":3,"maxScore":3,"skill":"Trend Awareness"},{"id":"criterion_4","label":"Đề xuất cải thiện cụ thể","description":"Đề xuất phương án cải thiện cụ thể (A/B testing headline, visual).","keywords":[],"weight":3,"maxScore":3,"skill":"Creativity"},{"id":"criterion_5","label":"Báo cáo và xin ý kiến Mentor","description":"Báo cáo và xin ý kiến của Mentor/Quản lý.","keywords":[],"weight":2,"maxScore":2,"skill":"Communication"}]'::jsonb, 'Trước tiên, em sẽ phân tích số liệu bài viết để tìm nguyên nhân: do tiêu đề chưa thu hút, hình ảnh chưa nổi bật, sai khung giờ đăng hay nội dung chưa đánh đúng tâm lý khách hàng. Sau đó, em sẽ tham khảo các bài viết có tương tác tốt của đối thủ và đề xuất với Mentor thử nghiệm phương án mới (A/B testing hình ảnh/tiêu đề) hoặc điều chỉnh lại góc nhìn bài viết trong các lần sau.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('8348ebf5-2ec8-5ba4-89fa-745956549578', (select id from public.interview_sets where slug = 'r2w-marketing-intern'), 4, 'Bạn sử dụng phương pháp nào để cập nhật các xu hướng (Trends) mới trên mạng xã hội và đưa chúng vào bài viết của thương hiệu?', '', '{}'::text[], 2, 15, '[{"id":"criterion_1","label":"Kênh/công cụ theo dõi trend","weight":3,"maxScore":3},{"id":"criterion_2","label":"Đánh giá Brand Voice phù hợp","weight":4,"maxScore":4},{"id":"criterion_3","label":"Biến tấu trend gắn liền sản phẩm","weight":4,"maxScore":4},{"id":"criterion_4","label":"Nhận thức rủi ro truyền thông","weight":2,"maxScore":2},{"id":"criterion_5","label":"Trình bày sáng tạo","weight":2,"maxScore":2}]'::jsonb, '[{"id":"criterion_1","label":"Kênh/công cụ theo dõi trend","description":"Nêu được các kênh/công cụ theo dõi trend thực tế (TikTok, Social Groups, Social Listening).","keywords":[],"weight":3,"maxScore":3,"skill":"Trend Awareness"},{"id":"criterion_2","label":"Đánh giá Brand Voice phù hợp","description":"Đánh giá mức độ phù hợp của trend với Brand Voice và đối tượng mục tiêu.","keywords":[],"weight":4,"maxScore":4,"skill":"Marketing Fundamentals"},{"id":"criterion_3","label":"Biến tấu trend gắn liền sản phẩm","description":"Tư duy biến tấu trend gắn liền với sản phẩm và thông điệp thương hiệu.","keywords":[],"weight":4,"maxScore":4,"skill":"Creativity"},{"id":"criterion_4","label":"Nhận thức rủi ro truyền thông","description":"Nhận thức về rủi ro truyền thông và an toàn thương hiệu khi đu trend.","keywords":[],"weight":2,"maxScore":2,"skill":"Marketing Fundamentals"},{"id":"criterion_5","label":"Trình bày sáng tạo","description":"Trình bày sáng tạo, mạch lạc, có ví dụ cụ thể.","keywords":[],"weight":2,"maxScore":2,"skill":"Communication"}]'::jsonb, 'Em thường xuyên theo dõi các kênh TikTok Trend, Social Trend Group và báo chí ngành Marketing. Khi thấy một trend mới, em sẽ phân tích xem trend đó có phù hợp với Brand Voice và tệp khách hàng của thương hiệu hay không. Nếu phù hợp, em sẽ biến tấu nội dung (Lồng ghép sản phẩm một cách khéo léo) chứ không đu trend mù quáng gây ảnh hưởng đến hình ảnh thương hiệu.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('e76cc3b4-6f63-51fb-b276-18081847dc96', (select id from public.interview_sets where slug = 'r2w-marketing-intern'), 5, 'Tối nay có một sự kiện/trend vô cùng hot bùng nổ trên mạng xã hội, nếu đu trend ngay sẽ mang lại tương tác rất lớn nhưng đã hết giờ làm việc và bạn không liên lạc được với Quản lý để duyệt bài. Bạn sẽ xử lý như thế nào?', '', '{}'::text[], 3, 20, '[{"id":"criterion_1","label":"Chủ động chuẩn bị nội dung","weight":5,"maxScore":5},{"id":"criterion_2","label":"Kiểm tra Brand Safety","weight":4,"maxScore":4},{"id":"criterion_3","label":"Chủ động liên hệ quản lý","weight":4,"maxScore":4},{"id":"criterion_4","label":"Quyết định dựa trên rủi ro","weight":4,"maxScore":4},{"id":"criterion_5","label":"Trách nhiệm theo dõi và báo cáo","weight":3,"maxScore":3}]'::jsonb, '[{"id":"criterion_1","label":"Chủ động chuẩn bị nội dung","description":"Linh hoạt, chủ động chuẩn bị sẵn nội dung và hình ảnh nháp.","keywords":[],"weight":5,"maxScore":5,"skill":"Learning Agility"},{"id":"criterion_2","label":"Kiểm tra Brand Safety","description":"Kiểm tra tính an toàn thương hiệu (Brand Safety) và tôn trọng pháp luật/thuần phong mỹ tục.","keywords":[],"weight":4,"maxScore":4,"skill":"Marketing Fundamentals"},{"id":"criterion_3","label":"Chủ động liên hệ quản lý","description":"Chủ động liên hệ và để lại thông tin đầy đủ cho Quản lý.","keywords":[],"weight":4,"maxScore":4,"skill":"Communication"},{"id":"criterion_4","label":"Quyết định dựa trên rủi ro","description":"Đưa ra quyết định hợp lý dựa trên mức độ rủi ro và Brand Guideline.","keywords":[],"weight":4,"maxScore":4,"skill":"Creativity"},{"id":"criterion_5","label":"Trách nhiệm theo dõi và báo cáo","description":"Trách nhiệm theo dõi phản hồi cộng đồng và báo cáo sau khi xử lý.","keywords":[],"weight":3,"maxScore":3,"skill":"Learning Agility"}]'::jsonb, 'Em sẽ nhanh chóng soạn sẵn khung nội dung/hình ảnh đu trend. Sau đó, em tự kiểm tra kỹ lưỡng theo Brand Guideline xem nội dung có vi phạm thuần phong mỹ tục, pháp luật hay đụng chạm đến đối thủ không. Em sẽ gửi tin nhắn/email cho Quản lý trình bày ngắn gọn cơ hội tương tác và bản nháp. Nếu trend mang tính an toàn cao và đúng tông giọng thương hiệu, em sẽ cân nhắc đăng bài và chịu trách nhiệm theo dõi sát phản hồi, đồng thời báo cáo ngay cho Quản lý khi họ phản hồi.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('8e7a7d08-a0b1-5510-b810-02a7eb978d06', (select id from public.interview_sets where slug = 'r2w-purchasing'), 1, 'Công ty mình đang cần tìm một nhà cung cấp Bao bì carton mới vì bên cũ liên tục giao hàng lỗi. Em hãy trình bày quy trình các bước em sẽ làm để chọn được nhà cung cấp mới. Trong đó, theo em bước nào là quan trọng nhất để phòng tránh rủi ro ''bắt tay ngầm'' (Kickback/Hoa hồng)?', '', '{}'::text[], 2, 40, '[{"id":"criterion_1","label":"Trình bày đủ & đúng quy trình Sourcing chuẩn","weight":20,"maxScore":20},{"id":"criterion_2","label":"Đề xuất cơ chế Đánh giá chéo / Vendor Scorecard minh bạch","weight":20,"maxScore":20}]'::jsonb, '[{"id":"criterion_1","label":"Trình bày đủ & đúng quy trình Sourcing chuẩn","description":"Nêu đủ các bước: Tìm kiếm, RFI/RFQ tối thiểu 3 bên, so sánh giá, test mẫu, audit nhà máy, đàm phán, ký HĐ.","keywords":[],"weight":20,"maxScore":20,"skill":"Sourcing"},{"id":"criterion_2","label":"Đề xuất cơ chế Đánh giá chéo / Vendor Scorecard minh bạch","description":"Cơ chế đánh giá chéo giữa Thu mua và QA/QC độc lập, phê duyệt cấp Giám đốc để phòng tránh kickback.","keywords":[],"weight":20,"maxScore":20,"skill":"Procurement Risk"}]'::jsonb, 'Quy trình Sourcing chuẩn: Tìm kiếm nhà cung cấp (Sourcing) -> Gửi Yêu cầu báo giá (RFI/RFQ cho ít nhất 3 bên) -> Nhận báo giá & Lập bảng so sánh -> Yêu cầu gửi hàng mẫu (Sample) -> Đánh giá năng lực nhà máy (Audit) -> Đàm phán -> Ký Hợp đồng nguyên tắc.
Bước chống rủi ro/minh bạch quan trọng nhất: Áp dụng cơ chế Đánh giá chéo & Bảng tiêu chí rõ ràng (Vendor Scorecard). Thu mua chỉ chịu trách nhiệm tìm giá và thương lượng, việc kiểm định chất lượng bao bì phải do phòng QA/QC độc lập thực hiện. Bảng tổng hợp điểm số được trình Giám đốc phê duyệt chứ Thu mua không tự mình đưa ra quyết định chọn bên nào.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('7c205cb6-eb91-5ceb-a80b-9abb31636bea', (select id from public.interview_sets where slug = 'r2w-purchasing'), 2, '(AI đóng vai Giám đốc xưởng Bao Bì với giọng căng thẳng): "Chào em. Chị nói thẳng luôn nhé. Tháng này giá bột giấy thế giới tăng sốc 30% rồi. Chị buộc phải tăng giá bán thùng carton cho bên em lên 15% bắt đầu từ đơn hàng sáng ngày mai. Nếu bên em không đồng ý thì chị đành ngừng cung cấp hàng vì chị bán giá cũ là lỗ nặng. Em tính sao?"', '', '{}'::text[], 3, 60, '[{"id":"criterion_1","label":"Chiến thuật 1 - Hạ nhiệt, câu giờ & Đòi chứng cứ","weight":20,"maxScore":20},{"id":"criterion_2","label":"Chiến thuật 2 - Áp dụng điều khoản Hợp đồng ràng buộc","weight":20,"maxScore":20},{"id":"criterion_3","label":"Chiến thuật 3 - Đàm phán Trade-off Win-Win (Công nợ/Sản lượng)","weight":20,"maxScore":20}]'::jsonb, '[{"id":"criterion_1","label":"Chiến thuật 1 - Hạ nhiệt, câu giờ & Đòi chứng cứ","description":"Hạ nhiệt, yêu cầu công văn chính thức kèm số liệu chứng minh giá bột giấy thế giới tăng để kéo dài thời gian.","keywords":[],"weight":20,"maxScore":20,"skill":"Negotiation"},{"id":"criterion_2","label":"Chiến thuật 2 - Áp dụng điều khoản Hợp đồng ràng buộc","description":"Áp dụng điều khoản thông báo trước 30 ngày trong HĐ hiện tại để giữ giá đơn hàng ngày mai.","keywords":[],"weight":20,"maxScore":20,"skill":"Vendor Management"},{"id":"criterion_3","label":"Chiến thuật 3 - Đàm phán Trade-off Win-Win (Công nợ/Sản lượng)","description":"Đổi giá trị win-win: tăng hạn mức công nợ lên 60 ngày hoặc cam kết tăng sản lượng để giữ mức tăng thấp.","keywords":[],"weight":20,"maxScore":20,"skill":"Trade-off / Win-Win"}]'::jsonb, 'Hạ nhiệt & Đòi chứng cứ: "Em rất chia sẻ khó khăn với xưởng mình. Tuy nhiên để em trình Ban Giám đốc phê duyệt mức tăng, chị vui lòng gửi Văn bản thông báo tăng giá chính thức kèm số liệu chứng minh giá nguyên liệu đầu vào tăng giúp em." (Dùng kỹ thuật câu giờ để chuẩn bị phương án dự phòng BATNA).
Sử dụng Hợp đồng bảo vệ ngắn hạn: "Theo Hợp đồng hiện tại giữa hai bên, mọi điều chỉnh về giá phải thông báo trước 30 ngày. Vì vậy, em đề nghị chị giữ nguyên giá cũ cho đơn hàng sáng mai và các đơn trong 30 ngày tới đúng theo cam kết."
Đàm phán đổi giá trị (Trade-off): "Nếu sau 30 ngày bắt đầu áp dụng mức tăng, bên em có thể hỗ trợ điều chỉnh nhưng đổi lại, xưởng phải nâng thời hạn công nợ (Payment terms) từ 30 ngày lên 60 ngày cho bên em. HOẶC bên em cam kết tăng sản lượng đặt hàng (Volume) gấp rưỡi để chị giữ mức tăng giá chỉ ở mốc 5% thay vì 15%."')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('b2e0fa2f-c324-54c2-8cbb-0562db4d0063', (select id from public.interview_sets where slug = 'r2w-qa-tester'), 1, 'Giới thiệu bản thân và vì sao bạn chọn nghề Tester/Quality Assurance (QA)', '', '{}'::text[], 1, 30, '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","description":"Nêu cụ thể kinh nghiệm/dự án đã từng kiểm thử, không nói chung chung.","keywords":[],"weight":12,"maxScore":12,"skill":"Testing Knowledge"},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","description":"Chỉ ra đặc thù công việc là tìm lỗi, đảm bảo chất lượng, tư duy phản biện - không nhầm với lập trình.","keywords":[],"weight":10,"maxScore":10,"skill":"Quality Assurance"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Trả lời mạch lạc, dùng được thuật ngữ Bug/Defect, Quality cơ bản.","keywords":[],"weight":8,"maxScore":8,"skill":"Communication"}]'::jsonb, 'Nêu cụ thể kinh nghiệm kiểm thử phần mềm; chỉ ra đặc thù công việc là tìm lỗi, đảm bảo chất lượng, tư duy phản biện để bảo vệ trải nghiệm người dùng cuối; không nhầm lẫn công việc kiểm thử với lập trình phần mềm.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('10d4e51a-78cc-50b0-924b-2f7e92268686', (select id from public.interview_sets where slug = 'r2w-qa-tester'), 2, 'Bạn hãy phân biệt Testing và Quality Assurance', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Định nghĩa đúng Testing","weight":15,"maxScore":15},{"id":"criterion_2","label":"Định nghĩa đúng QA","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Định nghĩa đúng Testing","description":"Là hoạt động PHÁT HIỆN lỗi trên sản phẩm cụ thể đã hoàn thành - mang tính phản ứng (reactive).","keywords":[],"weight":15,"maxScore":15,"skill":"Testing Knowledge"},{"id":"criterion_2","label":"Định nghĩa đúng QA","description":"Là tập hợp hoạt động đảm bảo QUY TRÌNH đúng chuẩn để PHÒNG NGỪA lỗi từ đầu - mang tính chủ động (proactive).","keywords":[],"weight":12,"maxScore":12,"skill":"Quality Assurance"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Dùng đúng thuật ngữ Reactive/Proactive, Quality Assurance/Quality Control.","keywords":[],"weight":8,"maxScore":8,"skill":"Communication"}]'::jsonb, 'Testing (Kiểm thử) là hoạt động kiểm tra sản phẩm cụ thể để tìm lỗi (mang tính phản ứng - reactive). QA (Đảm bảo chất lượng) là tập hợp các hoạt động giám sát quy trình phát triển phần mềm để phòng ngừa lỗi ngay từ đầu (mang tính chủ động - proactive).')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('1a5595b7-a06c-55ad-8b0b-c1ef9ecfa1b9', (select id from public.interview_sets where slug = 'r2w-qa-tester'), 3, 'Hãy kể tên các loại kiểm thử bạn biết (Manual, Automation, Unit, Integration...)', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Liệt kê đủ các loại kiểm thử","weight":20,"maxScore":20},{"id":"criterion_2","label":"Giải thích đúng ai thực hiện","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng tiếng Anh chuẩn","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đủ các loại kiểm thử","description":"Nêu tối thiểu 5/6: Manual, Automation, Unit, Integration, System, UAT.","keywords":[],"weight":20,"maxScore":20,"skill":"Testing Knowledge"},{"id":"criterion_2","label":"Giải thích đúng ai thực hiện","description":"Phân biệt rõ: Dev làm Unit/Integration, QA làm System/Manual/Automation, Khách hàng làm UAT.","keywords":[],"weight":10,"maxScore":10,"skill":"Quality Assurance"},{"id":"criterion_3","label":"Từ vựng tiếng Anh chuẩn","description":"Dùng đúng thuật ngữ tiếng Anh: Unit, Integration, System, UAT.","keywords":[],"weight":5,"maxScore":5,"skill":"Communication"}]'::jsonb, 'Liệt kê đầy đủ: Unit Test (do Dev viết cho hàm nhỏ), Integration Test (kiểm tra liên kết module), System Test (kiểm thử toàn hệ thống do QA làm), Manual Test (thao tác tay), Automation Test (chạy script tự động), và UAT (người dùng cuối nghiệm thu).')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('9df36996-abae-5fac-825d-4eaf38d67f0f', (select id from public.interview_sets where slug = 'r2w-qa-tester'), 4, 'Quy trình viết test case gồm những bước nào?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Thành phần cốt lõi của Test Case","weight":18,"maxScore":18},{"id":"criterion_2","label":"Trình tự logic","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Thành phần cốt lõi của Test Case","description":"ID/tiêu đề, điều kiện tiền đề (pre-condition), dữ liệu đầu vào, các bước thực hiện, kết quả mong đợi (expected result).","keywords":[],"weight":18,"maxScore":18,"skill":"Testing Knowledge"},{"id":"criterion_2","label":"Trình tự logic","description":"Các bước phải theo đúng thứ tự thực hiện thực tế, không đảo lộn.","keywords":[],"weight":10,"maxScore":10,"skill":"Problem Solving"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Dùng đúng thuật ngữ Pre-condition, Expected Result, Actual Result, Test Steps.","keywords":[],"weight":7,"maxScore":7,"skill":"Communication"}]'::jsonb, 'Quy trình: 1) Đọc hiểu tài liệu yêu cầu (SRS) -> 2) Xác định các kịch bản kiểm thử (Test Scenarios) -> 3) Viết chi tiết từng Test Case với đầy đủ: ID, Tiêu đề, Pre-conditions, Dữ liệu đầu vào, Các bước thực hiện (Steps), Kết quả mong đợi (Expected Result) -> 4) Review test case với BA/Dev.')
on conflict (set_id, position) do update set
