insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('737b9552-c930-528f-bb05-f3dbd7d8249d', (select id from public.interview_sets where slug = 'r2w-qa-tester'), 5, 'Phân biệt Black-box và White-box testing', '', '{}'::text[], 2, 30, '[{"id":"criterion_1","label":"Định nghĩa đúng Black-box","weight":15,"maxScore":15},{"id":"criterion_2","label":"Định nghĩa đúng White-box","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Định nghĩa đúng Black-box","description":"Kiểm thử dựa trên CHỨC NĂNG/đầu vào-đầu ra, KHÔNG cần biết code bên trong - do Tester thực hiện.","keywords":[],"weight":15,"maxScore":15,"skill":"Testing Knowledge"},{"id":"criterion_2","label":"Định nghĩa đúng White-box","description":"Kiểm thử dựa trên CẤU TRÚC CODE bên trong (nhánh, điều kiện) - thường do Developer thực hiện qua Unit Test.","keywords":[],"weight":10,"maxScore":10,"skill":"Quality Assurance"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Dùng đúng thuật ngữ Black-box/White-box Testing, Code Coverage.","keywords":[],"weight":5,"maxScore":5,"skill":"Communication"}]'::jsonb, 'Black-box testing là kiểm thử chức năng không cần biết cấu trúc code bên trong, chỉ kiểm tra đầu vào và đầu ra (thường do QA thực hiện). White-box testing là kiểm thử cấu trúc bên trong của mã nguồn (nhánh điều kiện, độ bao phủ code) do Developer thực hiện qua Unit test.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('4dc00cb5-e843-52d8-bd2a-e907a45edd22', (select id from public.interview_sets where slug = 'r2w-qa-tester'), 6, 'Bug life cycle gồm những trạng thái nào?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Trạng thái chính của Bug","weight":20,"maxScore":20},{"id":"criterion_2","label":"Trạng thái phụ","weight":10,"maxScore":10},{"id":"criterion_3","label":"Trình bày logic, đúng quy trình","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Trạng thái chính của Bug","description":"New → Assigned → Fixed → Retest → Closed (kèm nhánh Reopen nếu Retest fail).","keywords":[],"weight":20,"maxScore":20,"skill":"Defect Analysis"},{"id":"criterion_2","label":"Trạng thái phụ","description":"Rejected (không phải bug thật) hoặc Deferred (hoãn xử lý sang bản sau).","keywords":[],"weight":10,"maxScore":10,"skill":"Quality Assurance"},{"id":"criterion_3","label":"Trình bày logic, đúng quy trình","description":"Trình bày logic, đúng trình tự, mạch lạc, không dài dòng.","keywords":[],"weight":5,"maxScore":5,"skill":"Communication"}]'::jsonb, 'Vòng đời của Bug: New (phát hiện mới) -> Assigned (giao cho Dev) -> Fixed (Dev đã sửa) -> Retest (QA kiểm tra lại) -> Closed (đạt yêu cầu và đóng bug) hoặc Reopen (nếu lỗi vẫn còn); ngoài ra còn có Rejected (không phải bug) hoặc Deferred (hoãn sửa bản sau).')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('2f85d81b-306b-5ea5-8c4e-8237f5211390', (select id from public.interview_sets where slug = 'r2w-qa-tester'), 7, 'Bạn phát hiện bug nghiêm trọng sát ngày release, bạn xử lý ra sao?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Đánh giá mức độ ưu tiên","weight":20,"maxScore":20},{"id":"criterion_2","label":"Đề xuất phương án cụ thể","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng chuyên ngành","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Đánh giá mức độ ưu tiên","description":"Đánh giá Severity và Priority trước khi hành động, không hoảng loạn hoặc im lặng bỏ qua.","keywords":[],"weight":20,"maxScore":20,"skill":"Defect Analysis"},{"id":"criterion_2","label":"Đề xuất phương án cụ thể","description":"Ảnh hưởng luồng chính đề xuất hoãn release hoặc hotfix; ảnh hưởng nhỏ release kèm ghi chú fix bản sau.","keywords":[],"weight":20,"maxScore":20,"skill":"Problem Solving"},{"id":"criterion_3","label":"Từ vựng chuyên ngành","description":"Dùng đúng thuật ngữ Severity, Priority, Hotfix, Critical Bug.","keywords":[],"weight":10,"maxScore":10,"skill":"Quality Assurance"}]'::jsonb, 'Đánh giá chính xác Severity (mức độ nghiêm trọng kỹ thuật) và Priority (mức độ ưu tiên khắc phục); lập tức thông báo cho PM và Lead Dev kèm bằng chứng tái hiện (log, video); nếu ảnh hưởng luồng chính -> đề xuất hoãn release hoặc tung hotfix; nếu ảnh hưởng tính năng phụ -> bàn phương án release kèm ghi chú cho khách hàng.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

