values ('b6242710-dd96-5ea5-b99f-1ec60fb78113', (select id from public.interview_sets where slug = 'r2w-qa-tester'), 8, 'Dev không đồng ý đây là bug, bạn thuyết phục thế nào?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Cung cấp bằng chứng tái hiện","weight":20,"maxScore":20},{"id":"criterion_2","label":"Đối chiếu tài liệu gốc","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Cung cấp bằng chứng tái hiện","description":"Cung cấp Steps to Reproduce, ảnh chụp/video, log lỗi cụ thể - không tranh cãi suông.","keywords":[],"weight":20,"maxScore":20,"skill":"Defect Analysis"},{"id":"criterion_2","label":"Đối chiếu tài liệu gốc","description":"Chỉ ra cách chứng minh hành vi sai khác với đặc tả SRS, mời BA/PM xác nhận nếu cần.","keywords":[],"weight":20,"maxScore":20,"skill":"Quality Assurance"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Dùng đúng thuật ngữ Steps to Reproduce, Log, Specification.","keywords":[],"weight":10,"maxScore":10,"skill":"Communication"}]'::jsonb, 'Tuyệt đối không tranh cãi cảm tính; cung cấp Steps to Reproduce chi tiết, ảnh chụp/video màn hình, log lỗi và dữ liệu test; đối chiếu hành vi thực tế với tài liệu đặc tả yêu cầu (SRS/Acceptance Criteria) đã thống nhất; nếu vẫn bất đồng, mời BA vào xác nhận mục đích ban đầu của tính năng.')
