values ('127dc59f-6859-513d-8578-7e50a493d4a3', (select id from public.interview_sets where slug = 'r2w-risk-analyst'), 1, 'Giới thiệu bản thân và vì sao bạn theo đuổi Risk Analyst', '', '{}'::text[], 1, 30, '[{"id":"criterion_1","label":"Nền tảng chuyên môn liên quan","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Nền tảng chuyên môn liên quan","description":"Nêu ngành học/dự án cụ thể có liên quan đến tài chính, rủi ro, thống kê hoặc phân tích dữ liệu.","keywords":[],"weight":12,"maxScore":12,"skill":"Quantitative Analysis"},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","description":"Chỉ ra đặc thù công việc là nhận diện, đo lường, kiểm soát rủi ro; không nhầm với Kiểm toán hoặc Compliance thuần túy.","keywords":[],"weight":10,"maxScore":10,"skill":"Risk Management"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Dùng được các thuật ngữ: Risk, Risk Management, Mitigation.","keywords":[],"weight":8,"maxScore":8,"skill":"Risk Identification"}]'::jsonb, 'Nêu cụ thể ngành học tài chính, toán kinh tế, thống kê; lý do chọn nghề đúng bản chất (nhận diện, đo lường và kiểm soát các loại rủi ro nhằm bảo vệ an toàn vốn của tổ chức); sử dụng thành thạo các thuật ngữ Risk, Risk Management, Mitigation.')
on conflict (set_id, position) do update set
