values ('b5580fac-dd0d-57a7-b9b3-dc3577a08efa', (select id from public.interview_sets where slug = 'r2w-risk-analyst'), 2, 'Vai trò của Risk Analyst trong ngân hàng là gì?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Xác định đúng vai trò","weight":15,"maxScore":15},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng chuyên ngành","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Xác định đúng vai trò","description":"Nhận diện rủi ro tín dụng, thị trường, vận hành; đo lường, mô hình hóa, báo cáo và đề xuất biện pháp.","keywords":[],"weight":15,"maxScore":15,"skill":"Risk Identification"},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","description":"Thu thập dữ liệu, tính toán chỉ số, stress test, báo cáo rủi ro, giám sát hạn mức.","keywords":[],"weight":12,"maxScore":12,"skill":"Stress Testing"},{"id":"criterion_3","label":"Từ vựng chuyên ngành","description":"Dùng đúng thuật ngữ: Credit Risk, Market Risk, Operational Risk, Stress Testing.","keywords":[],"weight":8,"maxScore":8,"skill":"Risk Management"}]'::jsonb, 'Nhận diện, đo lường các loại rủi ro (tín dụng, thị trường, thanh khoản, vận hành); xây dựng và kiểm định mô hình rủi ro; thực hiện stress test danh mục; theo dõi hạn mức rủi ro và đề xuất các biện pháp phòng ngừa, trích lập dự phòng.')
on conflict (set_id, position) do update set
