values ('6b8e8fa3-8d1a-5df9-949d-3f29480320de', (select id from public.interview_sets where slug = 'r2w-risk-analyst'), 3, 'Bạn đã từng tham gia dự án/bài tập nào liên quan đến quản trị rủi ro chưa?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","weight":15,"maxScore":15},{"id":"criterion_2","label":"Trình bày theo STAR","weight":12,"maxScore":12},{"id":"criterion_3","label":"Bài học cụ thể rút ra","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","description":"Nêu rõ bối cảnh, vai trò và kết quả bài tập/dự án quản trị rủi ro.","keywords":[],"weight":15,"maxScore":15,"skill":"Quantitative Analysis"},{"id":"criterion_2","label":"Trình bày theo STAR","description":"Bối cảnh → Nhiệm vụ → Hành động → Kết quả.","keywords":[],"weight":12,"maxScore":12,"skill":"Risk Management"},{"id":"criterion_3","label":"Bài học cụ thể rút ra","description":"Ví dụ: ''Dữ liệu và giả định đầu vào quyết định độ tin cậy của mô hình rủi ro.''","keywords":[],"weight":8,"maxScore":8,"skill":"Risk Mitigation"}]'::jsonb, 'Nêu dự án mô hình rủi ro (VaR, tính xác suất vỡ nợ PD, stress test thanh khoản); trình bày theo STAR và nêu rõ bài học về chất lượng dữ liệu và tính chặt chẽ của các giả định rủi ro.')
