insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('054b76eb-1e02-5bfa-98a6-1cd4c31583c8', (select id from public.interview_sets where slug = 'r2w-risk-analyst'), 4, 'Phân biệt các loại rủi ro chính trong ngân hàng', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Liệt kê đúng các loại rủi ro","weight":18,"maxScore":18},{"id":"criterion_2","label":"Giải thích kèm ví dụ","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng chuyên ngành","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đúng các loại rủi ro","description":"Rủi ro tín dụng, rủi ro thị trường, rủi ro thanh khoản, rủi ro vận hành, rủi ro lãi suất, rủi ro tỷ giá.","keywords":[],"weight":18,"maxScore":18,"skill":"Risk Identification"},{"id":"criterion_2","label":"Giải thích kèm ví dụ","description":"Nêu ví dụ thực tế cho từng loại rủi ro trong hoạt động ngân hàng.","keywords":[],"weight":10,"maxScore":10,"skill":"Risk Management"},{"id":"criterion_3","label":"Từ vựng chuyên ngành","description":"Dùng đúng thuật ngữ: Credit, Market, Liquidity, Operational Risk.","keywords":[],"weight":7,"maxScore":7,"skill":"Quantitative Analysis"}]'::jsonb, 'Các loại rủi ro chính: 1) Rủi ro tín dụng (Credit Risk - người vay vỡ nợ); 2) Rủi ro thị trường (Market Risk - biến động lãi suất, tỷ giá, giá chứng khoán); 3) Rủi ro thanh khoản (Liquidity Risk - thiếu tiền mặt chi trả); 4) Rủi ro vận hành (Operational Risk - lỗi hệ thống, gian lận, quy trình).')
on conflict (set_id, position) do update set
