  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('3e4e135d-1409-5a4f-90cc-e0427e5a31dc', (select id from public.interview_sets where slug = 'r2w-risk-analyst'), 5, 'Các chỉ số đo lường rủi ro tín dụng thường dùng là gì', '', '{}'::text[], 2, 30, '[{"id":"criterion_1","label":"Liệt kê đúng các chỉ số","weight":15,"maxScore":15},{"id":"criterion_2","label":"Giải thích ý nghĩa từng chỉ số","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng chuẩn tiếng Anh","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đúng các chỉ số","description":"NPL, PD, LGD, EAD, EL theo chuẩn mực quản trị rủi ro.","keywords":[],"weight":15,"maxScore":15,"skill":"Quantitative Analysis"},{"id":"criterion_2","label":"Giải thích ý nghĩa từng chỉ số","description":"Nêu rõ cách dùng và ý nghĩa kinh tế của từng chỉ số đối với trích lập dự phòng.","keywords":[],"weight":10,"maxScore":10,"skill":"Risk Management"},{"id":"criterion_3","label":"Từ vựng chuẩn tiếng Anh","description":"Dùng đúng tên viết tắt và thuật ngữ tiếng Anh trong Basel.","keywords":[],"weight":5,"maxScore":5,"skill":"Risk Mitigation"}]'::jsonb, 'Các chỉ số cốt lõi theo chuẩn Basel: Tỷ lệ nợ xấu NPL (Non-Performing Loans); PD (Probability of Default - Xác suất vỡ nợ); LGD (Loss Given Default - Tỷ lệ tổn thất khi vỡ nợ); EAD (Exposure at Default - Dư nợ tại thời điểm vỡ nợ); và EL (Expected Loss = PD x LGD x EAD).')
