  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('81588167-69f6-55f0-8bc2-f3ce118c6f51', (select id from public.interview_sets where slug = 'r2w-risk-analyst'), 6, 'Stress testing là gì? Quy trình cơ bản gồm những bước nào?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Định nghĩa đúng Stress Testing","weight":18,"maxScore":18},{"id":"criterion_2","label":"Quy trình thực hiện cơ bản","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng chuyên ngành","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Định nghĩa đúng Stress Testing","description":"Là phương pháp kiểm tra danh mục dưới các kịch bản bất lợi nghiêm trọng.","keywords":[],"weight":18,"maxScore":18,"skill":"Stress Testing"},{"id":"criterion_2","label":"Quy trình thực hiện cơ bản","description":"Chọn kịch bản → xác định biến số → chạy mô hình → đánh giá an toàn vốn → báo cáo.","keywords":[],"weight":10,"maxScore":10,"skill":"Quantitative Analysis"},{"id":"criterion_3","label":"Từ vựng chuyên ngành","description":"Dùng đúng thuật ngữ: Stress Test, Scenario, Capital Adequacy, Shock.","keywords":[],"weight":7,"maxScore":7,"skill":"Risk Management"}]'::jsonb, 'Stress testing là kỹ thuật kiểm tra sức chịu đựng của danh mục hoặc toàn bộ ngân hàng dưới các kịch bản kinh tế vĩ mô cực đoan nhưng có thể xảy ra; Quy trình gồm: Thiết kế kịch bản (Scenario design) -> Xác định các biến số gây sốc (Shock variables) -> Chạy mô hình lượng hóa tổn thất -> Đánh giá mức độ suy giảm an toàn vốn CAR -> Đề xuất kế hoạch dự phòng vốn.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('69ffb76d-8560-5e1f-9cb4-d5829c4ec953', (select id from public.interview_sets where slug = 'r2w-risk-analyst'), 7, 'Phát hiện khoản vay lớn có dấu hiệu suy giảm, bạn xử lý thế nào?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Kiểm tra và đánh giá rủi ro","weight":20,"maxScore":20},{"id":"criterion_2","label":"Đề xuất biện pháp xử lý nợ","weight":20,"maxScore":20},{"id":"criterion_3","label":"Tính kịp thời và minh bạch","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Kiểm tra và đánh giá rủi ro","description":"Rà soát toàn diện tình trạng khách hàng, dòng tiền và tài sản bảo đảm.","keywords":[],"weight":20,"maxScore":20,"skill":"Risk Identification"},{"id":"criterion_2","label":"Đề xuất biện pháp xử lý nợ","description":"Chủ động đề xuất thu hồi nợ, tăng TSBĐ, cơ cấu lại hoặc chuyển nhóm nợ.","keywords":[],"weight":20,"maxScore":20,"skill":"Risk Mitigation"},{"id":"criterion_3","label":"Tính kịp thời và minh bạch","description":"Báo cáo trung thực, kịp thời lên Ủy ban Quản lý rủi ro mà không chậm trễ.","keywords":[],"weight":10,"maxScore":10,"skill":"Risk Management"}]'::jsonb, 'Kích hoạt quy trình cảnh báo sớm; rà soát lại dòng tiền, tình trạng kinh doanh của khách hàng và tính pháp lý của tài sản bảo đảm; phối hợp bộ phận quan hệ khách hàng và quản lý nợ đề xuất biện pháp xử lý: thu hồi nợ trước hạn, bổ sung tài sản hoặc chuyển nhóm nợ để trích lập dự phòng đầy đủ.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('43d95eb6-f7d2-57de-9e2e-b164e48214d9', (select id from public.interview_sets where slug = 'r2w-risk-analyst'), 8, 'Mô hình rủi ro cho kết quả khác thực tế, bạn xử lý thế nào?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Kiểm tra dữ liệu và giả định","weight":20,"maxScore":20},{"id":"criterion_2","label":"Hiệu chỉnh và Backtesting","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng chuyên môn","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Kiểm tra dữ liệu và giả định","description":"Rà soát dữ liệu đầu vào, giả định toán học và phương pháp tính toán.","keywords":[],"weight":20,"maxScore":20,"skill":"Quantitative Analysis"},{"id":"criterion_2","label":"Hiệu chỉnh và Backtesting","description":"Thực hiện Backtesting, báo cáo minh bạch và hiệu chỉnh lại mô hình.","keywords":[],"weight":20,"maxScore":20,"skill":"Stress Testing"},{"id":"criterion_3","label":"Từ vựng chuyên môn","description":"Dùng đúng thuật ngữ: Backtesting, Model Validation, Assumption, Calibration.","keywords":[],"weight":10,"maxScore":10,"skill":"Risk Management"}]'::jsonb, 'Tiến hành backtesting để kiểm tra độ tin cậy của mô hình; rà soát dữ liệu đầu vào xem có bị sai lệch hoặc thiếu cập nhật không; kiểm tra lại các giả định toán học; báo cáo minh bạch cho cấp quản lý và tiến hành hiệu chỉnh lại tham số (Model Calibration).')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('87d57334-2816-5015-a4e5-9827f638af23', (select id from public.interview_sets where slug = 'r2w-supply-chain'), 1, 'Trong giai đoạn đại dịch COVID-19, em hẳn đã thấy hiện tượng người dân đổ xô đi mua giấy vệ sinh và mì tôm, dẫn đến các nhà máy sản xuất ồ ạt, nhưng sau đó lại tồn kho chất đống. Đây là ví dụ của Hiệu ứng Bullwhip (Cái roi da). Nếu em làm Analyst tại nhà máy mì tôm đó, em đề xuất giải pháp cốt lõi nào để công ty không bị sập bẫy ''sản xuất thừa'' khi có biến động giá như vậy?', '', '{}'::text[], 2, 40, '[{"id":"criterion_1","label":"Phân tích bản chất Panic buying & sự sai lệch thông tin","weight":15,"maxScore":15},{"id":"criterion_2","label":"Đề xuất giải pháp POS Data thực tế","weight":15,"maxScore":15},{"id":"criterion_3","label":"Đề xuất giải pháp CPFR/VMI & Minh bạch dữ liệu","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Phân tích bản chất Panic buying & sự sai lệch thông tin","description":"Nhận diện nhu cầu hoảng loạn ngắn hạn và hiện tượng bóp méo thông tin qua các cấp trong chuỗi.","keywords":[],"weight":15,"maxScore":15,"skill":"Bullwhip Effect"},{"id":"criterion_2","label":"Đề xuất giải pháp POS Data thực tế","description":"Lấy dữ liệu bán lẻ thực tế tại điểm bán (POS Data) để phản ánh sức mua tiêu dùng thực.","keywords":[],"weight":15,"maxScore":15,"skill":"Data Analysis"},{"id":"criterion_3","label":"Đề xuất giải pháp CPFR/VMI & Minh bạch dữ liệu","description":"Phối hợp lập kế hoạch và chia sẻ dữ liệu tồn kho minh bạch toàn chuỗi (CPFR/VMI).","keywords":[],"weight":10,"maxScore":10,"skill":"Supply Chain Analysis"}]'::jsonb, 'Phân tích nguyên nhân: Hiện tượng mua tích trữ là nhu cầu hoảng loạn (Panic buying) ngắn hạn, không đại diện cho sức mua tiêu dùng thực tế bền vững. Thông tin bị bóp méo gia tăng qua từng cấp trong chuỗi (Đại lý -> Nhà phân phối -> Nhà máy).
Giải pháp Data cốt lõi:
Thu thập dữ liệu POS (Point of Sale): Căn cứ vào dữ liệu bán hàng thực tế tại máy tính tiền của các siêu thị/điểm bán lẻ thay vì chỉ dựa vào đơn đặt hàng dồn dập từ đại lý.
Triển khai mô hình CPFR/VMI: Phối hợp lập kế hoạch và chia sẻ dữ liệu tồn kho minh bạch toàn chuỗi với các bên bán lẻ (Vendor Managed Inventory).')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('f25d36f3-8e86-51b9-b957-8a945174d4ec', (select id from public.interview_sets where slug = 'r2w-supply-chain'), 2, '"Chị là Giám đốc Kinh doanh. Chị vừa nhận báo cáo chi phí Logistics tháng này tăng vọt 40% so với tháng trước. Chị không có thời gian đọc file Excel dài 1000 dòng của em. Em hãy giải thích cho chị nghe bằng giọng nói: Tại sao chi phí tăng, nguyên nhân từ phòng ban nào, và đề xuất 1 hành động ngay ngày mai để giải quyết?"', '', '{}'::text[], 3, 60, '[{"id":"criterion_1","label":"Trình bày phi kỹ thuật (Ngôn ngữ kinh doanh)","weight":15,"maxScore":15},{"id":"criterion_2","label":"Xác định chính xác nguyên nhân & Quy trách nhiệm logic","weight":20,"maxScore":20},{"id":"criterion_3","label":"Đề xuất giải pháp hành động cụ thể (Bundling / Transfer)","weight":25,"maxScore":25}]'::jsonb, '[{"id":"criterion_1","label":"Trình bày phi kỹ thuật (Ngôn ngữ kinh doanh)","description":"Tránh từ ngữ quá phức tạp, dùng ngôn ngữ kinh doanh ngắn gọn, trực diện cho Leadership.","keywords":[],"weight":15,"maxScore":15,"skill":"Data Storytelling"},{"id":"criterion_2","label":"Xác định chính xác nguyên nhân & Quy trách nhiệm logic","description":"Chỉ rõ phí kho ngoài tăng do chênh lệch dự báo Sales (10.000 vs 6.000 thùng thực tế).","keywords":[],"weight":20,"maxScore":20,"skill":"Supply Chain Analysis"},{"id":"criterion_3","label":"Đề xuất giải pháp hành động cụ thể (Bundling / Transfer)","description":"Hành động ngay ngày mai: Bundling xả hàng hoặc chuyển vùng sang chi nhánh có sức mua tốt.","keywords":[],"weight":25,"maxScore":25,"skill":"Inventory Optimization"}]'::jsonb, 'Diễn giải kinh doanh: "Sếp ơi, chi phí tháng này tăng 40% nguyên nhân chính nằm ở Phí lưu kho ngoài (Storage cost) do chênh lệch Forecast giữa Sales và thực tế. Tháng trước team Sales dự báo bán 10,000 thùng nên nhà máy đã sản xuất và đẩy hàng ra kho. Tuy nhiên, thực tế Sales chốt được 6,000 thùng, dẫn đến 4,000 thùng tồn đọng phải thuê kho ngoài phát sinh."
Hành động ngay ngày mai: "Để xả nhanh lô 4,000 thùng cận date này, ngay ngày mai em đề xuất mình làm chương trình Bundling (Bán bia tặng ly / Mua 5 tặng 1) hoặc Điều chuyển nội bộ (Transfer) sang chi nhánh miền Tây – nơi đang có tốc độ bán hàng tốt hơn."')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('c61d4075-3d66-5091-8458-c527cc0f0db4', (select id from public.interview_sets where slug = 'r2w-tro-ly-thue'), 1, 'Hãy giới thiệu ngắn gọn về bản thân và lý do bạn lựa chọn công việc Trợ lý thuế?', '', '{}'::text[], 1, 30, '[{"id":"criterion_1","label":"Giới thiệu đúng trọng tâm","weight":14,"maxScore":14},{"id":"criterion_2","label":"Lý do chọn nghề thuế","weight":11,"maxScore":11},{"id":"criterion_3","label":"Trình bày rõ ràng","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Giới thiệu đúng trọng tâm","description":"Nêu ngành học, kinh nghiệm/thực tập hoặc hoạt động liên quan.","keywords":[],"weight":14,"maxScore":14,"skill":"Tax Knowledge"},{"id":"criterion_2","label":"Lý do chọn nghề thuế","description":"Nêu được lý do cụ thể như quan tâm chính sách thuế, thích số liệu và quy định.","keywords":[],"weight":11,"maxScore":11,"skill":"Regulatory Compliance"},{"id":"criterion_3","label":"Trình bày rõ ràng","description":"Rõ ràng, có cấu trúc, không lan man.","keywords":[],"weight":5,"maxScore":5,"skill":"Professional Communication"}]'::jsonb, 'Nêu rõ chuyên ngành học, kinh nghiệm/thực tập liên quan; lý do lựa chọn ngành thuế (hứng thú với chính sách thuế, các quy định pháp luật và tối ưu hóa tuân thủ cho DN); trình bày tự tin, mạch lạc, có cấu trúc rõ ràng.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
