insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('f28080da-dcea-5d47-999a-96925a72865b', (select id from public.interview_sets where slug = 'r2w-tro-ly-thue'), 2, 'Theo bạn, trợ lý thuế cần có những kỹ năng quan trọng nào?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Kiến thức thuế cơ bản","weight":20,"maxScore":20},{"id":"criterion_2","label":"Kiểm tra chứng từ","weight":10,"maxScore":10},{"id":"criterion_3","label":"Cập nhật quy định","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Kiến thức thuế cơ bản","description":"Hiểu sự cần thiết của kiến thức về các sắc thuế và quy định liên quan.","keywords":[],"weight":20,"maxScore":20,"skill":"Tax Knowledge"},{"id":"criterion_2","label":"Kiểm tra chứng từ","description":"Biết kiểm tra hóa đơn, chứng từ và đối chiếu số liệu.","keywords":[],"weight":10,"maxScore":10,"skill":"Document Verification"},{"id":"criterion_3","label":"Cập nhật quy định","description":"Nhận thức chính sách thuế có thể thay đổi thường xuyên.","keywords":[],"weight":5,"maxScore":5,"skill":"Regulatory Compliance"}]'::jsonb, 'Cần nắm vững kiến thức thuế cơ bản (GTGT, TNDN, TNCN, hóa đơn điện tử); kỹ năng kiểm tra và đối chiếu hóa đơn chứng từ chính xác; tinh thần chủ động cập nhật các thay đổi của Luật và Thông tư hướng dẫn.')
