insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('dcf9c1c0-0124-53e1-90ed-08afe2b29a69', (select id from public.interview_sets where slug = 'r2w-tro-ly-thue'), 3, 'Vì sao việc cập nhật các quy định thuế lại quan trọng đối với một trợ lý thuế?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Nhận thức về thay đổi chính sách","weight":18,"maxScore":18},{"id":"criterion_2","label":"Ảnh hưởng đến công việc","weight":10,"maxScore":10},{"id":"criterion_3","label":"Chủ động cập nhật nguồn chính thống","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Nhận thức về thay đổi chính sách","description":"Hiểu quy định thuế có thể được cập nhật/thay đổi liên tục.","keywords":[],"weight":18,"maxScore":18,"skill":"Regulatory Compliance"},{"id":"criterion_2","label":"Ảnh hưởng đến công việc","description":"Biết thay đổi chính sách có thể ảnh hưởng đến cách kê khai và xử lý hồ sơ.","keywords":[],"weight":10,"maxScore":10,"skill":"Tax Knowledge"},{"id":"criterion_3","label":"Chủ động cập nhật nguồn chính thống","description":"Nêu được cách cập nhật từ nguồn chính thống, tài liệu chuyên môn hoặc hướng dẫn của doanh nghiệp.","keywords":[],"weight":7,"maxScore":7,"skill":"Attention to Detail"}]'::jsonb, 'Chính sách thuế Việt Nam thường xuyên sửa đổi, bổ sung; việc không cập nhật kịp thời sẽ dẫn đến kê khai sai, áp dụng sai thuế suất, gây truy thu và phạt vi phạm cho khách hàng; nêu được các nguồn cập nhật chính thống như Cổng TT Tổng cục Thuế, Thư viện pháp luật, công văn hướng dẫn.')
