insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('c4d5643e-67d7-55bd-9919-0e37b7911747', (select id from public.interview_sets where slug = 'r2w-tro-ly-thue'), 4, 'Khi kiểm tra một hóa đơn chứng từ để phục vụ kê khai thuế, bạn sẽ thực hiện những bước kiểm tra và đối chiếu nào?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Kiểm tra hóa đơn hợp lệ","weight":20,"maxScore":20},{"id":"criterion_2","label":"Đối chiếu chứng từ liên quan","weight":10,"maxScore":10},{"id":"criterion_3","label":"Xử lý trước khi kê khai","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Kiểm tra hóa đơn hợp lệ","description":"Kiểm tra tên, mã số thuế, số tiền, thuế suất, ngày và nội dung.","keywords":[],"weight":20,"maxScore":20,"skill":"Document Verification"},{"id":"criterion_2","label":"Đối chiếu chứng từ liên quan","description":"So sánh với hợp đồng, phiếu nhập/xuất, biên bản giao nhận và sổ kế toán.","keywords":[],"weight":10,"maxScore":10,"skill":"Attention to Detail"},{"id":"criterion_3","label":"Xử lý trước khi kê khai","description":"Trao đổi với người phụ trách/khách hàng và xử lý theo quy định.","keywords":[],"weight":5,"maxScore":5,"skill":"Regulatory Compliance"}]'::jsonb, 'Kiểm tra tính hợp lệ của hóa đơn (tên người mua/bán, mã số thuế, số tiền, thuế suất, thời điểm lập, mã cơ quan thuế); đối chiếu hóa đơn với hợp đồng, phiếu nhập kho, biên bản giao nhận và chứng từ thanh toán không dùng tiền mặt (nếu trên 20 triệu); xử lý các sai sót trước khi kê khai.')
