insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('3fd7e08a-d144-5457-ab8b-ef99b84a151d', (select id from public.interview_sets where slug = 'r2w-tro-ly-thue'), 6, 'Khi kiểm tra hồ sơ thuế, bạn phát hiện số liệu doanh thu giữa hóa đơn và bảng tổng hợp không khớp. Bạn sẽ kiểm tra những gì?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Kiểm tra danh sách hóa đơn","weight":18,"maxScore":18},{"id":"criterion_2","label":"Kiểm tra công thức và nhập liệu","weight":10,"maxScore":10},{"id":"criterion_3","label":"Xử lý đúng quy trình","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Kiểm tra danh sách hóa đơn","description":"Đối chiếu số lượng và giá trị các hóa đơn đã phát hành.","keywords":[],"weight":18,"maxScore":18,"skill":"Document Verification"},{"id":"criterion_2","label":"Kiểm tra công thức và nhập liệu","description":"Kiểm tra công thức, dữ liệu nhập và các khoản đã tổng hợp.","keywords":[],"weight":10,"maxScore":10,"skill":"Attention to Detail"},{"id":"criterion_3","label":"Xử lý đúng quy trình","description":"Báo cáo người phụ trách và điều chỉnh khi xác định được nguyên nhân.","keywords":[],"weight":7,"maxScore":7,"skill":"Regulatory Compliance"}]'::jsonb, 'Rà soát lại danh sách hóa đơn xuất ra (số lượng và giá trị từng số hóa đơn); kiểm tra lại công thức tính toán và dữ liệu nhập trên bảng tổng hợp; xác định hóa đơn bị sót hoặc hủy mà chưa cập nhật và báo cáo quản lý để xử lý.')
