insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('62b67068-4fa6-5213-8cd2-bf2aa418940f', (select id from public.interview_sets where slug = 'r2w-tro-ly-thue'), 7, 'Gần đến hạn nộp hồ sơ thuế nhưng khách hàng chưa cung cấp đầy đủ chứng từ. Bạn sẽ xử lý như thế nào?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Xác định chứng từ thiếu","weight":20,"maxScore":20},{"id":"criterion_2","label":"Chủ động liên hệ khách hàng","weight":20,"maxScore":20},{"id":"criterion_3","label":"Không tự ý kê khai khống","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Xác định chứng từ thiếu","description":"Lập danh sách hóa đơn, chứng từ hoặc thông tin còn thiếu.","keywords":[],"weight":20,"maxScore":20,"skill":"Attention to Detail"},{"id":"criterion_2","label":"Chủ động liên hệ khách hàng","description":"Nhắc khách hàng về tài liệu và thời hạn cần cung cấp.","keywords":[],"weight":20,"maxScore":20,"skill":"Professional Communication"},{"id":"criterion_3","label":"Không tự ý kê khai khống","description":"Không tự tạo số liệu hoặc kê khai khi chưa có đủ cơ sở.","keywords":[],"weight":10,"maxScore":10,"skill":"Regulatory Compliance"}]'::jsonb, 'Lập danh sách cụ thể các chứng từ, hóa đơn còn thiếu; chủ động liên hệ nhắc nhở khách hàng qua email và điện thoại, nêu rõ hạn chót nộp tờ khai và rủi ro phạt nộp chậm; tuyệt đối không tự ý bịa đặt số liệu để nộp thay.')
on conflict (set_id, position) do update set
