insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('69844d42-65a0-5655-a063-1957c76ce3f3', (select id from public.interview_sets where slug = 'r2w-tro-ly-thue'), 8, 'Khách hàng yêu cầu bạn đưa một khoản chi phí vào hồ sơ thuế nhưng chứng từ cung cấp chưa đủ để xác định khoản chi phí đó có phù hợp hay không. Bạn sẽ làm gì?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Kiểm tra tính hợp lệ của chi phí","weight":20,"maxScore":20},{"id":"criterion_2","label":"Yêu cầu bổ sung chứng từ","weight":20,"maxScore":20},{"id":"criterion_3","label":"Trao đổi với người phụ trách","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Kiểm tra tính hợp lệ của chi phí","description":"Kiểm tra hóa đơn và các tài liệu chứng minh liên quan.","keywords":[],"weight":20,"maxScore":20,"skill":"Tax Knowledge"},{"id":"criterion_2","label":"Yêu cầu bổ sung chứng từ","description":"Chủ động yêu cầu khách hàng cung cấp tài liệu còn thiếu.","keywords":[],"weight":20,"maxScore":20,"skill":"Document Verification"},{"id":"criterion_3","label":"Trao đổi với người phụ trách","description":"Báo cáo cấp quản lý nếu chưa thể xác định cách xử lý phù hợp.","keywords":[],"weight":10,"maxScore":10,"skill":"Regulatory Compliance"}]'::jsonb, 'Kiểm tra kỹ lưỡng các điều kiện để chi phí được trừ theo Luật thuế TNDN; giải thích rõ cho khách hàng về rủi ro bị cơ quan thuế xuất toán và xử phạt nếu không có đủ hồ sơ hợp lệ; yêu cầu bổ sung chứng từ hoặc xin ý kiến của quản lý cấp trên.')
on conflict (set_id, position) do update set
